// ── Резолв канала ──────────────────────────────────────────────────────────
// Project webhook message.help ловит сообщения со ВСЕХ каналов проекта
// (WhatsApp 1, WhatsApp 2, Instagram, …). Мы обслуживаем только те, что
// прописаны в MH_CHANNELS (JSON-карта channelId → channelUuid). Для
// незнакомого канала функция вернёт null — processMessage молча скипает.
function resolveChannelUuid(env, channelId) {
  const map = parseKnownChannelMap(env);
  const uuid = map.get(String(channelId));
  if (uuid) return uuid;
  // Backward-compat: один канал через MH_CHANNEL_UUID (без проверки channelId).
  return env.MH_CHANNEL_UUID || null;
}

// ── Точка входа ────────────────────────────────────────────────────────────
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === 'GET') {
      // Ops: проверка Telegram-канала менеджеров — GET ?tgtest=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('tgtest') === env.WEBHOOK_SECRET) {
        const t0 = Date.now();
        const ok = await sendTelegramAlert(env,
          '🧪 mh-bot: тест канала уведомлений менеджеров. Сообщение можно игнорировать.');
        return json({ ok, ms: Date.now() - t0 });
      }
      // Ops: проверка транскрипции голосового — GET ?voicetest=<WEBHOOK_SECRET>&url=<file_url>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('voicetest') === env.WEBHOOK_SECRET) {
        const fileUrl = url.searchParams.get('url') || '';
        if (!fileUrl) return json({ ok: false, error: 'no_url' });
        const t0 = Date.now();
        const text = await transcribeVoice(env, { fileUrl, messageType: 'audio' });
        return json({ ok: !!text, ms: Date.now() - t0, text });
      }
      // Ops: симуляция диалога с ботом (golden-тесты промпта, БЕЗ отправок клиенту
      // и в Telegram) — GET ?sim=<WEBHOOK_SECRET>&u=<id>&text=<сообщение>[&reset=1].
      if (env.WEBHOOK_SECRET && url.searchParams.get('sim') === env.WEBHOOK_SECRET) {
        const r = await simulateDialog(env,
          url.searchParams.get('u') || 'sim1',
          url.searchParams.get('text') || '',
          url.searchParams.get('reset') === '1',
          url.searchParams.get('ab') === '1');
        return json(r);
      }
      // Ops: список мастеров под услугу-консультацию (сверка staff_id для
      // ALTEGIO_CONSULT_STAFF_IDS) — GET ?staffdump=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('staffdump') === env.WEBHOOK_SECRET) {
        return json(await staffDump(env));
      }
      // Ops: dry-run слотов авто-записи (какие вернутся и пройдут фильтр окна,
      // БЕЗ создания записи) — GET ?autobooktest=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('autobooktest') === env.WEBHOOK_SECRET) {
        const now = almatyNow();
        const slots = await fetchConsultSlots(env, { dayHint: url.searchParams.get('hint') || '' });
        return json({
          ok: true,
          enabled: autobookEnabled(env, now),
          night: isAutobookNight(now),
          staff: [...parseConsultStaff(env).entries()].map(([id, name]) => ({ id, name })),
          window: `${env.AUTOBOOK_START || AUTOBOOK_START_DEFAULT}–${env.AUTOBOOK_END || AUTOBOOK_END_DEFAULT}`,
          slots: slots.map((s) => ({ ref: s.ref, when: `${s.humanDate} ${s.hhmm}`, staff: s.staffName, datetime: s.datetime })),
        });
      }
      // Ops: dry-run follow-up после консультации (кто в какую ветку попадёт +
      // тексты, БЕЗ отправки) — GET ?consultfutest=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('consultfutest') === env.WEBHOOK_SECRET) {
        return json(await consultFollowupDryRun(env));
      }
      // Ops: полный каталог услуг Altegio с ценами (сверка с промптом) —
      // GET ?servicesdump=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('servicesdump') === env.WEBHOOK_SECRET) {
        const co = env.ALTEGIO_COMPANY_ID;
        const sres = await fetch(`${ALTEGIO_API}/company/${co}/services`, { headers: altegioHeaders(env) });
        if (!sres.ok) return json({ ok: false, status: sres.status, body: (await sres.text()).slice(0, 300) });
        const sdata = await sres.json().catch(() => null);
        const slist = (sdata && sdata.data) || [];
        const services = (Array.isArray(slist) ? slist : []).map((s) => ({
          id: s.id, title: s.title, price_min: s.price_min, price_max: s.price_max,
          active: s.active, category_id: s.category_id,
        }));
        return json({ ok: true, count: services.length, services });
      }
      // Ops: проба форматов поиска клиента Altegio (clients/search сломан на
      // quick_search) — GET ?clienttest=<WEBHOOK_SECRET>&phone=7701...
      if (env.WEBHOOK_SECRET && url.searchParams.get('clienttest') === env.WEBHOOK_SECRET) {
        const co = env.ALTEGIO_COMPANY_ID;
        const phone = (url.searchParams.get('phone') || '77012345678').replace(/\D/g, '');
        const tries = [];
        const tryReq = async (variant, method, path, body) => {
          try {
            const r = await fetch(`${ALTEGIO_API}${path}`, {
              method, headers: altegioHeaders(env),
              body: body ? JSON.stringify(body) : undefined,
            });
            tries.push({ variant, status: r.status, body: (await r.text()).slice(0, 300) });
          } catch (e) { tries.push({ variant, err: String(e && e.message) }); }
        };
        await tryReq('v1_search_state_value', 'POST', `/company/${co}/clients/search`,
          { page: 1, page_size: 5, fields: ['id', 'name', 'phone', 'visit_count', 'last_visit_date'],
            filters: [{ type: 'quick_search', state: { value: phone } }] });
        await tryReq('v2_search_nofilter', 'POST', `/company/${co}/clients/search`,
          { page: 1, page_size: 5, fields: ['id', 'name', 'phone', 'visit_count'] });
        await tryReq('v3_get_clients_phone', 'GET', `/clients/${co}?phone=${phone}`, null);
        await tryReq('v4_company_clients', 'GET', `/company/${co}/clients?phone=${phone}`, null);
        return json({ ok: true, phone, tries });
      }
      // Ops: проверка готовой функции узнавания клиента — GET ?clientlookup=<WEBHOOK_SECRET>&phone=7701...
      if (env.WEBHOOK_SECRET && url.searchParams.get('clientlookup') === env.WEBHOOK_SECRET) {
        return json({ ok: true, result: await altegioClientLookup(env, url.searchParams.get('phone') || '') });
      }
      // Ops: dry-run реактивации — кого бот пригласил бы (БЕЗ отправки) —
      // GET ?reacttest=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('reacttest') === env.WEBHOOK_SECRET) {
        const now = almatyNow();
        let cands = [];
        try { cands = await collectReactivationCandidates(env, now); } catch (e) { return json({ ok: false, error: String(e && e.message) }); }
        return json({
          ok: true, active: String(env.REACTIVATION_ACTIVE) === '1',
          window: `${ymdDaysAhead(now, -(Number(env.REACT_MAX_DAYS) || 90))}..${ymdDaysAhead(now, -(Number(env.REACT_MIN_DAYS) || 60))}`,
          perRun: Number(env.REACT_PER_RUN) || 5, candidates: cands.length,
          sample: cands.slice(0, 10).map((c) => ({ phone: maskPhone(c.phone), name: c.name })),
        });
      }
      // Ops: dry-run отмены — какую запись бот нашёл бы по телефону (БЕЗ удаления) —
      // GET ?canceltest=<WEBHOOK_SECRET>&phone=7701...
      if (env.WEBHOOK_SECRET && url.searchParams.get('canceltest') === env.WEBHOOK_SECRET) {
        const phone = url.searchParams.get('phone') || '';
        const rec = await altegioFindCancelable(env, phone);
        return json({
          ok: true, enabled: cancelEnabled(env),
          phone: maskPhone(normalizePhone(phone) || phone), found: !!rec,
          record: rec ? {
            recordId: rec.recordId, when: `${humanizeSlotDate(rec.ms, almatyNow())} ${rec.hhmm}`,
            service: rec.serviceTitle, staff: rec.staffName,
          } : null,
        });
      }
      // Ops: dry-run напоминаний за сутки — кого бот напомнил бы СЕЙЧАС (без
      // отправки) — GET ?confirmtest=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('confirmtest') === env.WEBHOOK_SECRET) {
        const now = almatyNow();
        const inWindow = now.hour >= CONFIRM_HOUR_START && now.hour < CONFIRM_HOUR_END;
        const preflight = confirmPreflightOk(env);
        const tomorrowStr = ymdDaysAhead(now, 1);
        const records = await fetchTomorrowRecordsSafe(env, tomorrowStr);
        if (records === null) {
          return json({ ok: false, error: 'altegio_fetch_failed', preflight, inWindow, tomorrow: tomorrowStr });
        }
        const candidates = await collectConfirmCandidates(env, records, now);
        return json({
          ok: true,
          now: `${now.ymd} ${String(now.hour).padStart(2, '0')}:${String(now.minute).padStart(2, '0')}`,
          window: `${CONFIRM_HOUR_START}:00–${CONFIRM_HOUR_END}:00`,
          inWindow, preflight,
          tomorrow: tomorrowStr,
          tomorrowRecords: records.length,
          candidates: candidates.length,
          sample: candidates.slice(0, 12).map((c) => ({
            phone: maskPhone(c.phone),
            appt: c.parts ? `${String(c.parts.hour).padStart(2, '0')}:${String(c.parts.minute).padStart(2, '0')}` : '?',
            name: (c.record && c.record.client && firstName(c.record.client.name)) || '',
          })),
        });
      }
      // Ops: воронка бота за сегодня/вчера — GET ?stats=<WEBHOOK_SECRET>.
      if (env.WEBHOOK_SECRET && url.searchParams.get('stats') === env.WEBHOOK_SECRET) {
        const n = almatyNow();
        const days = [n.ymd, ymdDaysAhead(n, -1)];
        const metrics = ['in', 'kev', 'handoff', 'confirm_yes', 'confirm_no',
          'autobook_done', 'autobook_reused', 'media_in', 'cancel_req', 'cancel_done', 'reschedule_req'];
        const stats = {};
        for (const d of days) {
          const row = {};
          for (const m of metrics) row[m] = await readStat(env, d, m);
          stats[d] = row;
        }
        return json({ ok: true, stats });
      }
      return json({ status: 'ok', service: 'mh-bot', ts: new Date().toISOString() });
    }
    if (request.method !== 'POST') {
      return json({ ok: false, error: 'method_not_allowed' }, 405);
    }

    const missing = ['ANTHROPIC_API_KEY', 'MH_LOGIN', 'MH_PASSWORD', 'WEBHOOK_SECRET',
      'MH_PROJECT_ID', 'MH_CHANNELS'].filter((k) => !env[k]);
    if (!env.BOT_KV || typeof env.BOT_KV.get !== 'function') missing.push('BOT_KV');
    if (missing.length) {
      console.error('misconfigured: missing', missing.join(','));
      return json({ ok: false, error: 'misconfigured' }, 500);
    }

    // message.help не подписывает вебхуки — секрет передаём сами в URL вебхука.
    const provided = url.searchParams.get('secret')
      || request.headers.get('x-webhook-secret') || '';
    if (provided !== env.WEBHOOK_SECRET) {
      return json({ ok: false, error: 'unauthorized' }, 401);
    }

    let body;
    try {
      body = await request.json();
    } catch {
      return json({ ok: false, error: 'bad_json' }, 400);
    }

    // В лог — только метаданные (без PII/медданных). Полный сырой webhook —
    // лишь по явному флагу LOG_RAW='1' (для отладки), по умолчанию выключено.
    if (env.LOG_RAW === '1') {
      console.log('RAW_WEBHOOK ' + JSON.stringify(body).slice(0, 1500));
    } else {
      const pl = (body && body.payload) || {};
      console.log(`WEBHOOK action=${body && body.action} chan=${pl.channel_id || ''}`
        + ` type=${pl.message_type || ''} dst=${pl.destination || ''} len=${String(pl.message || '').length}`);
    }

    const msg = parseWebhook(body);
    if (msg) {
      // Отвечаем message.help сразу (200), обработку — в фоне, иначе таймаут.
      ctx.waitUntil(processMessage(msg, env).catch((e) =>
        console.error('processMessage failed:', e && e.message)));
    }
    return json({ ok: true });
  },

  // Cron-handler. Триггер `*/10 * * * *` запускает job'ы параллельно;
  // каждый сам пропускает «не свой» тик (confirmation/broadcast — окна часов,
  // утренний дайджест КЭВ — окно 08:30–09:30, nudge — только при KEV_NUDGE=1).
  async scheduled(event, env, ctx) {
    // Внешний «сторож» (dead-man's-switch): пинг HEARTBEAT_URL на каждом тике.
    // Замолчал воркер дольше N минут → внешний сервис (healthchecks.io и т.п.)
    // шлёт тревогу. Выключено, если HEARTBEAT_URL не задан.
    if (env.HEARTBEAT_URL) {
      ctx.waitUntil(fetchWithTimeout(env.HEARTBEAT_URL, { method: 'GET' }, 8000).catch(() => {}));
    }
    // Подтверждения записей — приоритет (это записи клиентов) и эталон времени
    // для разноса с рассылкой. Ждём их ПОЛНОСТЬЮ до старта рассылки, чтобы метка
    // last_confirm_send была актуальна, когда рассылка решает, слать ли в этот тик.
    // Так рассылка и авто-уведомление не уйдут клиентам в одну минуту.
    await runConfirmationJob(env).catch((e) =>
      console.error('confirmation job failed:', e && e.message));
    ctx.waitUntil(runBroadcastJob(env).catch((e) =>
      console.error('broadcast job failed:', e && e.message)));
    ctx.waitUntil(runKevMorningDigest(env).catch((e) =>
      console.error('kev digest failed:', e && e.message)));
    ctx.waitUntil(runKevNudgeJob(env).catch((e) =>
      console.error('kev nudge failed:', e && e.message)));
    ctx.waitUntil(runConsultFollowupJob(env).catch((e) =>
      console.error('consult followup failed:', e && e.message)));
    ctx.waitUntil(runDailyBotReport(env).catch((e) =>
      console.error('daily report failed:', e && e.message)));
    ctx.waitUntil(runReactivationJob(env).catch((e) =>
      console.error('reactivation job failed:', e && e.message)));
  },
};

// ── Парсинг вебхука message.help ────────────────────────────────────────────
// Тело вебхука: { action: "channel.message.created", payload: ChannelMessage }.
function parseWebhook(body) {
  if (!body || body.action !== 'channel.message.created' || !body.payload) return null;
  const p = body.payload;
  return {
    messageId: p.id,
    userId: p.user_id,
    channelId: p.channel_id,
    text: (p.message || '').trim(),
    messageType: p.message_type || 'text',
    destination: p.destination || '',
    createdAt: p.created_at || '',
    fileUrl: p.file_url || '',   // голосовые/вложения: ссылка на файл (.oga для voice-note)
  };
}

// ── Обработка одного входящего сообщения ───────────────────────────────────
async function processMessage(msg, env) {
  const tag = `u${msg.userId}`;

  // Резолвим канал из входящего: проектный вебхук message.help ловит сообщения
  // со ВСЕХ каналов проекта, но мы обслуживаем только те, что в MH_CHANNELS.
  // Незнакомый канал (Instagram и т.п.) — молча скипаем.
  const channelUuid = resolveChannelUuid(env, msg.channelId);
  if (!channelUuid) {
    console.log(`unknown channel ${msg.channelId}, skip ${tag}`);
    return;
  }
  msg.channelUuid = channelUuid;

  // Эхо-защита: сообщение, отправленное самим ботом, message.help может вернуть
  // обратно вебхуком. Свои id мы помечаем при отправке — такие пропускаем.
  if (msg.messageId && await env.BOT_KV.get(`sent:${msg.messageId}`)) return;

  // Сотрудник подключился к чату — бот немедленно умолкает и больше не
  // перебивает. Сигналы message.help (подтверждено на проде в pulse-боте):
  //   from_whatsapp / from_instagram / from_operator / from_* — ИСХОДЯЩИЙ
  //     ответ человека через канал (раньше ловили только from_operator —
  //     реальные ответы менеджеров приходят как from_<канал>, и днём бот
  //     перебивал бы живой диалог);
  //   contact_in_work — сотрудник взял контакт в работу (ловим подключение
  //     ещё до того, как он что-то напишет).
  // Свои сообщения отсеяны эхо-защитой выше; на случай гонки «вебхук обогнал
  // запись sent:» — перепроверяем пометку после паузы, чтобы бот не заглушил
  // сам себя собственным эхом.
  const isOutboundEcho = typeof msg.destination === 'string'
    && msg.destination !== 'from' && msg.destination.startsWith('from_');
  if (isOutboundEcho || msg.destination === 'contact_in_work') {
    if (isOutboundEcho && msg.messageId) {
      await sleep(1500);
      if (await env.BOT_KV.get(`sent:${msg.messageId}`)) return; // своё эхо
    }
    if (msg.userId) {
      await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
      console.log(`operator joined -> bot paused ${tag} (${msg.destination})`);
    }
    return;
  }

  // Обрабатываем входящие сообщения клиента: ТЕКСТ и ГОЛОСОВЫЕ.
  // destination=from — «От пользователя». Всё прочее (to, notice_*, ai,
  // comment, altegio_*, ...) — исходящее/служебное/автоматическое, не наше.
  // Фото/видео/стикеры/документы — по-прежнему менеджерам (бот их не видит).
  if (msg.destination !== 'from') return;
  if (!msg.userId) return;
  const isVoice = isVoiceMessage(msg);
  // Медиа от клиента (фото/видео/документ/стикер): бот «не видит» контент, но
  // больше НЕ теряет его молча — помечаем seen, считаем в воронку, шлём карточку
  // менеджеру и ставим op-паузу (дальше ведёт человек). Голосовые сюда не
  // попадают (isVoice идёт ниже на транскрипцию).
  if (!isVoice && msg.messageType !== 'text') {
    if (msg.messageId) {
      if (await env.BOT_KV.get(`seen:${msg.messageId}`)) return;
      await env.BOT_KV.put(`seen:${msg.messageId}`, '1', { expirationTtl: DEDUP_TTL });
    }
    const mt = String(msg.messageType || 'медиа').toLowerCase();
    const label = (mt.includes('image') || mt.includes('photo')) ? 'фото'
      : mt.includes('video') ? 'видео'
      : mt.includes('sticker') ? 'стикер'
      : (mt.includes('document') || mt.includes('file')) ? 'документ'
      : `вложение (${mt})`;
    await bumpStat(env, 'media_in');
    // Зрение: фото + VISION_ACTIVE='1' → бот сам смотрит и ведёт на консультацию
    // (с анти-медицинскими гайками). Не вышло — падаем в карточку менеджеру.
    if (isImageMessage(msg) && env.VISION_ACTIVE === '1') {
      try {
        if (await handleClientImage(env, msg)) { console.log(`vision answered ${tag}`); return; }
      } catch (e) { console.error('vision failed:', e && e.message); }
    }
    // op-паузу ставим ВСЕГДА (дальше ведёт человек). Карточку менеджеру — ОДИН
    // раз на пачку: видео/стикеры/доки тоже приходят по разу на файл, иначе
    // менеджер получает дубли. Дубль в окне cooldown гасим (человек уже вызван).
    if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
    const cardKey = `media_card:${msg.userId}`;
    if (msg.userId && await env.BOT_KV.get(cardKey)) {
      console.log(`media -> manager (дубль карточки погашен) ${tag} type=${mt}`);
      return;
    }
    if (msg.userId) await env.BOT_KV.put(cardKey, '1', { expirationTtl: VISION_DONE_TTL });
    let mphone = null;
    try { mphone = await getContactPhone(env, msg); } catch (_) { /* без телефона */ }
    await sendTelegramAlert(env, [
      `📎 Клиент прислал ${label} — бот не видит вложение · ${almatyHHMM()}`,
      `Клиент: ${mphone ? fmtPhoneHuman(mphone) : `чат №${msg.userId}`}`,
      'Бот поставил диалог на паузу — откройте вложение в message.help и продолжите.',
    ].join('\n'));
    console.log(`media -> manager ${tag} type=${mt}`);
    return;
  }
  if (!isVoice && !msg.text) return;

  // Дедуп — message.help может повторить доставку вебхука. ДО транскрипции
  // (не распознавать дважды) и ДО confirm_pending (не среагировать дважды
  // на ответ «Да/Нет»).
  const seenKey = `seen:${msg.messageId}`;
  if (await env.BOT_KV.get(seenKey)) return;
  await bumpStat(env, 'in');                            // воронка: входящее обработано

  // Голосовое → текст (Whisper, Workers AI). Удалось — сообщение дальше
  // живёт как обычный текст (включая «Да/Нет» на подтверждение записи).
  // Не удалось — placeholder: в confirm/engage-цепочках уйдёт менеджеру
  // стандартным follow-up'ом, в чате бота клиента вежливо попросим написать
  // текстом (фолбэк ниже, после проверок принадлежности чата).
  let voiceFailed = false;
  if (isVoice) {
    const transcript = await transcribeVoice(env, msg);
    if (transcript) {
      msg.text = transcript;
      console.log(`voice ok ${tag}: ${transcript.length} симв.`);
    } else {
      voiceFailed = true;
      msg.text = '[голосовое сообщение — распознать не удалось]';
      console.log(`voice FAIL ${tag}`);
    }
  }

  // Ответ клиента на подтверждение записи — НЕЗАВИСИМО от часа суток.
  // Цепочка должна быть доведена в любом случае: «Да» → attendance=2,
  // «Нет» → передача менеджеру, любой другой ответ («можно перенести?»,
  // «во сколько было?», «не уверена пока») → ТАКЖЕ передача менеджеру.
  // Раньше «другой» ответ проваливался в Claude-flow, а днём бот его
  // скипал по night-window → клиент оставался без ответа.
  const pendingRaw = await env.BOT_KV.get(`confirm_pending:user:${msg.userId}`);
  if (pendingRaw) {
    // В чат уже вступил человек-менеджер (op:-пауза выставляется, когда менеджер
    // пишет клиенту) — НЕ перебиваем его своей цепочкой подтверждения. Менеджер
    // доведёт сам; иначе бот и человек дублируют «подтвердите запись». Гасим
    // pending, отмечаем seen, молчим.
    if (await env.BOT_KV.get(`op:${msg.userId}`)) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
      await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);
      console.log(`confirm_pending: operator active -> bot silent ${tag}`);
      return;
    }
    let pending = null;
    try { pending = JSON.parse(pendingRaw); } catch (_) { pending = null; }
    await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });

    // Распознаём интент глубоко (перенос/болезнь/отмена/подтверждение/опоздание).
    // sameBookedDay: клиент назвал ИМЕННО день записи («завтра же, да?») — не перенос.
    const nowR = almatyNow();
    const horizonR = parseInt(env.AUTOBOOK_HORIZON_DAYS, 10) || AUTOBOOK_HORIZON_DEFAULT;
    let bookedYmd = '';
    if (pending && pending.apptDate) {
      const apb = parseAltegioParts(pending.apptDate);
      if (apb) bookedYmd = `${apb.year}-${String(apb.month).padStart(2, '0')}-${String(apb.day).padStart(2, '0')}`;
    }
    const namedDays = resolveTargetDates(msg.text, nowR, horizonR);
    const sameBookedDay = !!bookedYmd && namedDays.size > 0 && [...namedDays].every((d) => d === bookedYmd);
    const ri = classifyReminderIntent(msg.text, { sameBookedDay });
    const phoneR = (pending && pending.phone) || '';

    if (ri.intent === 'reschedule') {
      // Бот сам ведёт перенос (любая услуга): находит запись, показывает реальные
      // окна того же мастера. Нет окон/ошибка → handleRescheduleStart отдаёт админу.
      await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);
      let rs = { clientText: 'Поняла 🌷 Передаю администратору — поможет с переносом.', handoff: 'перенос' };
      try { rs = await handleRescheduleStart(env, msg, phoneR); }
      catch (e) { console.error('reminder reschedule:', e && e.message); }
      if (rs.clientText) await sendMessage(env, msg, rs.clientText);
      if (rs.handoff) {
        if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
        await assignToManager(env, msg);
        await sendTelegramAlert(env, [
          `🔁 ПЕРЕНОС (с напоминания) → ${rs.handoff} · ${almatyHHMM()}`,
          `${phoneR ? fmtPhoneHuman(phoneR) : 'чат №' + msg.userId} · запись #${(pending && pending.recordId) || '—'}`,
          ri.reason ? `причина: ${ri.reason}` : `«${String(msg.text || '').slice(0, 40)}»`,
        ].join('\n'));
      }
    } else if (ri.intent === 'cancel') {
      await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);
      if (cancelEnabled(env)) {
        let cs = { clientText: 'Поняла 🌷 Передаю менеджеру.', found: false, handoff: 'отмена' };
        try { cs = await handleCancelStart(env, msg, phoneR); }
        catch (e) { console.error('reminder cancel:', e && e.message); }
        if (cs.clientText) await sendMessage(env, msg, cs.clientText);
        if (!cs.found && cs.handoff) {
          if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
          await assignToManager(env, msg);
        }
      } else {
        await sendMessage(env, msg, 'Поняла, передаю менеджеру — он(а) свяжется и поможет 🤍');
        if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
        await assignToManager(env, msg);
      }
      await sendTelegramAlert(env, [
        `🔴 ОТМЕНА/«не приду» (с напоминания) · ${almatyHHMM()}`,
        `${phoneR ? fmtPhoneHuman(phoneR) : 'чат №' + msg.userId} · запись #${(pending && pending.recordId) || '—'}`,
        ri.reason ? `причина: ${ri.reason}` : `«${String(msg.text || '').slice(0, 40)}»`,
      ].join('\n'));
    } else if (ri.intent === 'confirm' || ri.intent === 'late'
      || arrivalWithinTolerance(msg.text, pending && pending.apptMin, Number(env.CONFIRM_LATE_TOLERANCE_MIN) || 10)) {
      // Подтверждение / опоздание / названо время в пределах допуска — клиент придёт.
      await handleConfirmationResponse(env, msg, 'yes', pending);
    } else if (isAddressQuestion(msg.text)) {
      await sendMessage(env, msg, STUDIO_ADDRESS_LINE);    // pending оставляем активным
    } else if (ri.intent === 'question') {
      await handleConfirmationFollowUp(env, msg, pending); // реальный вопрос → менеджер
    } else if (isPoliteClosing(msg.text)) {
      await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);
      await sendMessage(env, msg, 'Будем рады видеть вас! 🌷');
    } else {
      // Неясное/приветствие — мягко переспрашиваем ОДИН раз; второй → тёплое закрытие.
      const rk = `confirm_reprompt:${msg.userId}`;
      if (await env.BOT_KV.get(rk)) {
        await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);
        await env.BOT_KV.delete(rk);
        await sendMessage(env, msg, 'Будем рады видеть вас! 🌷');
      } else {
        await env.BOT_KV.put(rk, '1', { expirationTtl: 7200 });
        await sendMessage(env, msg, 'Здравствуйте! 🌷 Подскажите, подтверждаете запись — придёте?');
      }
    }
    return;
  }

  // Ответ клиента на engage-сообщение рассылки акций. Так же круглосуточно.
  // «Да/+/интересно/расскажите» → отправляем полный шаблон акций (шаг 2).
  // «Нет/не нужно/отпишите» → opt-out на 365 дней + вежливый ответ.
  // Длинный/непонятный ответ → передаём менеджеру (он лучше отработает
  // вопросы про цену конкретной программы и т.п.).
  const engageRaw = await env.BOT_KV.get(`broadcast_engage_pending:user:${msg.userId}`);
  if (engageRaw) {
    // Менеджер уже в чате (op:-пауза) — не перебиваем ответом на акцию.
    if (await env.BOT_KV.get(`op:${msg.userId}`)) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
      await env.BOT_KV.delete(`broadcast_engage_pending:user:${msg.userId}`);
      console.log(`engage_pending: operator active -> bot silent ${tag}`);
      return;
    }
    let engage = null;
    try { engage = JSON.parse(engageRaw); } catch (_) { engage = null; }
    const kind = classifyConfirmationResponse(msg.text);
    await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
    if (kind === 'yes') {
      await handleBroadcastEngageYes(env, msg, engage);
    } else if (kind === 'no') {
      await handleBroadcastEngageNo(env, msg, engage);
    } else {
      await handleBroadcastEngageOther(env, msg, engage);
    }
    return;
  }

  // Ответ клиента в флоу ОТМЕНЫ записи (перенести/отменить/остаюсь) — так же
  // круглосуточно, как confirm/engage. Решение классифицируем кодом. Менеджер
  // уже в чате (op:-пауза) — не перебиваем, гасим pending.
  const cancelRaw = await env.BOT_KV.get(`cancel_pending:${msg.userId}`);
  if (cancelRaw) {
    if (await env.BOT_KV.get(`op:${msg.userId}`)) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
      await env.BOT_KV.delete(`cancel_pending:${msg.userId}`);
      console.log(`cancel_pending: operator active -> bot silent ${tag}`);
      return;
    }
    let pending = null;
    try { pending = JSON.parse(cancelRaw); } catch (_) { pending = null; }
    await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
    if (pending && pending.recordId) await handleCancelDecision(env, msg, pending);
    else await env.BOT_KV.delete(`cancel_pending:${msg.userId}`);
    return;
  }

  // Ответ клиента в флоу ПЕРЕНОСА записи (день → реальные окна → выбор номера).
  // Код-driven (как отмена). Менеджер уже в чате — молчим, гасим pending.
  const reschedRaw = await env.BOT_KV.get(`reschedule_pending:${msg.userId}`);
  if (reschedRaw) {
    if (await env.BOT_KV.get(`op:${msg.userId}`)) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
      await env.BOT_KV.delete(`reschedule_pending:${msg.userId}`);
      console.log(`reschedule_pending: operator active -> bot silent ${tag}`);
      return;
    }
    let rp = null;
    try { rp = JSON.parse(reschedRaw); } catch (_) { rp = null; }
    await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
    if (rp && rp.oldRecordId) await handleRescheduleDecision(env, msg, rp);
    else await env.BOT_KV.delete(`reschedule_pending:${msg.userId}`);
    return;
  }

  // Окно лид-диалога: с 12.06.2026 BOT_HOUR_* = 0..24 (круглосуточно), бот
  // отвечает и днём — менеджер «выигрывает» чат первым же своим сообщением
  // (op:-пауза выше). Эхо-защита, операторская пауза и обработка ответа на
  // confirmation работают всегда, независимо от окна.
  const hour = almatyNow().hour;
  const inWindow = BOT_HOUR_START < BOT_HOUR_END
    ? (hour >= BOT_HOUR_START && hour < BOT_HOUR_END)
    : (hour >= BOT_HOUR_START || hour < BOT_HOUR_END);
  if (!inWindow) {
    console.log(`outside bot hours (h=${hour}, window=${BOT_HOUR_START}-${BOT_HOUR_END}), skip ${tag}`);
    return;
  }

  // Чат уже ведёт человек (сотрудник подключился, или бот ранее сделал
  // handoff) — бот не вмешивается.
  if (await env.BOT_KV.get(`op:${msg.userId}`)) {
    console.log(`paused, human owns ${tag}`);
    return;
  }

  // КЭВ уже состоялся (заявка передана менеджеру, kev_pending активен 48ч):
  // бот продолжает отвечать на уточнения («а парковка есть?»), но заявку
  // заново не собирает и ПОВТОРНЫХ карточек не создаёт.
  let kevPending = null;
  const kevPendingRaw = await env.BOT_KV.get(`kev_pending:${msg.userId}`);
  if (kevPendingRaw) {
    try { kevPending = JSON.parse(kevPendingRaw); } catch (_) { kevPending = {}; }
  }

  // Прерванный добор полей КЭВ с прошлого хода — напомним Claude, чего не хватает.
  let kevMissing = null;
  if (!kevPending) {
    const kevMissingRaw = await env.BOT_KV.get(`kev_missing:${msg.userId}`);
    if (kevMissingRaw) {
      try { kevMissing = JSON.parse(kevMissingRaw); } catch (_) { kevMissing = null; }
    }
  }

  // История диалога (baseLen — для защиты от гонки при записи).
  const histKey = `hist:${msg.userId}`;
  const histBefore = (await env.BOT_KV.get(histKey, { type: 'json' })) || [];
  const baseLen = histBefore.length;
  let returningNote = '';   // контекст «действующий клиент» для модели (узнавание по Altegio)

  // Первый контакт бота с этим клиентом (истории ещё нет) — два гейта:
  if (baseLen === 0) {
    // 1) В этом чате сегодня-вчера уже отвечал ЧЕЛОВЕК (по журналу событий
    //    pulse-бота) — чат менеджера, бот не влезает. Без этого при дневном
    //    режиме бот перебивал бы живые диалоги, начатые до его включения.
    if (await humanOwnsDialog(env, msg.userId)) {
      await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
      console.log(`skip: human already in dialog ${tag} -> paused`);
      return;
    }
    // 2) Гейт «новый лид / действующий клиент» по РЕАЛЬНОЙ записи Altegio.
    //    Если у телефона есть запись на сегодня..+2 дня — это НЕ новый лид:
    //      • короткое «Приду/Да/Нет» → ответ на напоминание (внешнее — иначе
    //        сработал бы confirm_pending выше) → подтверждение/передача менеджеру;
    //      • иное (вопрос/просьба по своей записи) → вежливая передача администратору.
    //    Имя/противопоказания НЕ спрашиваем (собраны при записи). Гейт по РЕАЛЬНОЙ
    //    записи убирает регрессию: новый лид без записи сюда не попадает → лид-флоу.
    //    NB: это рабочая ЗАМЕНА прежнего classifyContact — clients/search в этом
    //    кабинете Altegio отдаёт 400 на quick_search и не возвращает visit_count,
    //    т.е. altegioHasVisitHistory молча возвращал 'new' (гейт не работал).
    const firstPhone = await getContactPhone(env, msg);
    // Внутренний номер (менеджер/сотрудник) — бот его НЕ ведёт как лида: молчит
    // и ставит op-паузу (как при подключении человека).
    if (firstPhone && isInternalPhone(env, firstPhone)) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
      if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
      console.log(`internal phone -> bot silent ${tag}`);
      return;
    }
    const booking = firstPhone ? await altegioUpcomingBooking(env, firstPhone) : null;
    if (booking) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
      // Глубокое распознавание интента (перенос/болезнь/отмена/подтверждение/
      // опоздание/вопрос). ДО подтверждения — иначе «приеду в понедельник» / «болею»
      // трактуются как «приду». sameBookedDay: назван ИМЕННО день записи → не перенос.
      const nowB = almatyNow();
      const horizonB = parseInt(env.AUTOBOOK_HORIZON_DAYS, 10) || AUTOBOOK_HORIZON_DEFAULT;
      const apB = parseAltegioParts(booking.date);
      const bookedYmdB = apB ? `${apB.year}-${String(apB.month).padStart(2, '0')}-${String(apB.day).padStart(2, '0')}` : '';
      const apptMinB = apB ? apB.hour * 60 + apB.minute : null;
      const tolMinB = Number(env.CONFIRM_LATE_TOLERANCE_MIN) || 10;
      const namedB = resolveTargetDates(msg.text, nowB, horizonB);
      const sameB = !!bookedYmdB && namedB.size > 0 && [...namedB].every((d) => d === bookedYmdB);
      const riB = classifyReminderIntent(msg.text, { sameBookedDay: sameB });

      if (riB.intent === 'reschedule' && cancelEnabled(env)) {
        // Бот сам ведёт перенос (любая услуга, тот же мастер).
        let rs = { clientText: 'Поняла 🌷 Передаю администратору — поможет с переносом.', handoff: 'перенос' };
        try { rs = await handleRescheduleStart(env, msg, firstPhone); }
        catch (e) { console.error('booked reschedule:', e && e.message); }
        await sendMessage(env, msg, rs.clientText);
        if (rs.handoff) await handleHandoff(env, msg, rs.handoff);
        console.log(`booked client reschedule ${tag} handoff=${!!rs.handoff}`);
      } else if (riB.intent === 'cancel' && cancelEnabled(env)) {
        const cs = await handleCancelStart(env, msg, firstPhone);
        await sendMessage(env, msg, cs.clientText);
        if (!cs.found && cs.handoff) await handleHandoff(env, msg, cs.handoff);
        console.log(`booked client cancel ${tag} found=${cs.found}`);
      } else if (riB.intent === 'confirm' || riB.intent === 'late'
        || arrivalWithinTolerance(msg.text, apptMinB, tolMinB)) {
        await handleBookedReminderReply(env, msg, 'yes', booking, firstPhone);
      } else if (isAddressQuestion(msg.text)) {
        await sendMessage(env, msg, STUDIO_ADDRESS_LINE);
        console.log(`booked client address-q ${tag}`);
      } else if (isPoliteClosing(msg.text)) {
        await sendMessage(env, msg, 'Будем рады видеть вас! 🌷');
        console.log(`booked client polite-closing ${tag}`);
      } else if (riB.intent === 'reschedule' || riB.intent === 'cancel') {
        // Перенос/отмена, но фича выключена → администратору.
        await handleBookedReminderReply(env, msg, 'no', booking, firstPhone);
      } else if (riB.intent === 'question') {
        await sendMessage(env, msg,
          'Вы уже записаны к нам 🌷 Передаю администратору — он(а) свяжется и поможет с вашей записью.');
        if (msg.userId) {
          await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
        }
        console.log(`booked client question ${tag} -> handoff`);
      } else {
        // Неясное/приветствие — мягкий переспрос ОДИН раз; второй → тёплое закрытие.
        const rk = `confirm_reprompt:${msg.userId}`;
        if (await env.BOT_KV.get(rk)) {
          await env.BOT_KV.delete(rk);
          await sendMessage(env, msg, 'Будем рады видеть вас! 🌷');
        } else {
          await env.BOT_KV.put(rk, '1', { expirationTtl: 7200 });
          await sendMessage(env, msg, 'Здравствуйте! 🌷 Подтверждаете запись — придёте?');
        }
      }
      return;
    }
    // Действующий клиент БЕЗ будущей записи — узнаём по истории визитов Altegio
    // (быстрый clients/search). Был у нас → подмешаем контекст модели, чтобы она
    // не вела его как нового лида (тёплое узнавание, без анкеты). firstPhone — выше.
    if (firstPhone) {
      const known = await altegioClientLookup(env, firstPhone);
      if (known && known.returning) {
        returningNote = '[Контекст из базы (клиенту НЕ сообщай, что смотришь карточку): это '
          + 'ДЕЙСТВУЮЩИЙ клиент студии, уже был у нас'
          + (known.lastVisitDate ? ` (последний визит ${String(known.lastVisitDate).slice(0, 10)})` : '')
          + '. Веди тепло, как с тем, кто уже бывал, можно «рады снова вас видеть». НЕ допрашивай '
          + 'по анкете и НЕ выясняй заново имя/противопоказания. НЕ называй его по имени, пока он сам '
          + 'не представится. Если хочет записаться — помоги и передай администратору.]';
      }
    }
  }

  // Голосовое не распозналось, чат ведёт бот (все проверки принадлежности
  // выше пройдены) — честно просим текст. В Claude placeholder не отправляем.
  if (voiceFailed) {
    const ok = await sendMessage(env, msg,
      'Простите, не получилось расслышать голосовое 🙈 Напишите, пожалуйста, текстом — сразу отвечу.');
    if (ok) await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });
    return;
  }

  // Склейка быстрых сообщений (debounce, за флагом DEBOUNCE_ACTIVE): клиент
  // пишет по одному слову несколькими сообщениями — отвечаем ОДИН раз на всё.
  // Trailing-механика: кладём текст в буфер, помечаем последним, ждём окно
  // тишины; пришло новее — выходим (ответит оно), иначе обрабатываем склейку.
  if (env.DEBOUNCE_ACTIVE === '1' && msg.messageId) {
    const bufKey = `msgbuf:${msg.userId}`;
    let bufArr = [];
    try { bufArr = (await env.BOT_KV.get(bufKey, { type: 'json' })) || []; } catch (_) { bufArr = []; }
    bufArr.push({ id: String(msg.messageId), text: msg.text });
    await env.BOT_KV.put(bufKey, JSON.stringify(bufArr.slice(-10)), { expirationTtl: 120 });
    await env.BOT_KV.put(`msglast:${msg.userId}`, String(msg.messageId), { expirationTtl: 120 });
    await sleep(DEBOUNCE_WINDOW_MS);
    const latest = await env.BOT_KV.get(`msglast:${msg.userId}`);
    if (latest && latest !== String(msg.messageId)) {
      await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });   // своё — не обрабатываем
      console.log(`debounce: superseded ${tag}`);
      return;
    }
    let combined = [];
    try { combined = (await env.BOT_KV.get(bufKey, { type: 'json' })) || []; } catch (_) { combined = []; }
    await env.BOT_KV.delete(bufKey);
    const joined = combined.map((m) => m.text).filter(Boolean).join('\n').trim();
    if (joined && joined !== msg.text) {
      msg.text = joined.slice(0, 2000);
      console.log(`debounce: merged ${combined.length} msgs ${tag}`);
    }
  }

  const contextHistory = appendTurn(histBefore, 'user', msg.text);

  // Слоты в промпт больше НЕ подмешиваем: бот не показывает временные окна.
  // Но подмешиваем доступность авто-записи СЕЙЧАС: только тогда Claude эмитит
  // OFFER_SLOTS (иначе ведёт обычный КЭВ). См. блок АВТО-ЗАПИСЬ в SYSTEM_PROMPT.
  const reply = await callClaude(env, contextHistory,
    buildServiceNote(kevPending, kevMissing, autobookEnabled(env, almatyNow()), cancelEnabled(env),
      baseLen === 0 && !returningNote)
    + (returningNote ? `\n\n${returningNote}` : ''));

  // Если Claude недоступен — НЕ молчим: мягкий ответ + handoff менеджеру.
  let clientText;
  let booking = null;
  let handoff = null;
  let claudeFailed = false;
  let autobooked = false;
  if (reply) {
    const parsed = parseControlTags(reply);
    clientText = parsed.cleanText || 'Спасибо за сообщение! 🌸 Передаю вас менеджеру.';
    booking = parsed.booking;
    handoff = parsed.handoff;

    // Авто-запись на консультацию (OFFER_SLOTS/BOOK_CONSULT). BOOK_CONSULT —
    // легитимное продолжение, НЕ гасится при kev_pending (блокер #7); OFFER_SLOTS
    // и BOOKING_JSON гасятся как раньше. handleAutoBook сам решает гейты/фоллбэк;
    // при handled=true он подменяет текст клиенту и (при успехе) создаёт запись.
    let autobookHandled = false;
    if (parsed.bookConsult || parsed.offerSlots) {
      try {
        const ab = await handleAutoBook(env, msg, parsed, kevPending, parsed.cleanText);
        if (ab && ab.handled) {
          autobookHandled = true;
          clientText = ab.clientText || clientText;
          if (ab.handoff) handoff = ab.handoff;
          if (ab.autobooked) autobooked = true;
          booking = null; // авто-флоу сам поставил карточку/решил фоллбэк
        }
      } catch (e) {
        console.error('handleAutoBook failed:', e && e.message);
        // фоллбэк: идём обычным КЭВ (booking/handoff из тегов, если были)
      }
    }

    // Просьба ОТМЕНИТЬ запись (тег от Claude). Не гасится kev_pending —
    // легитимное продолжение. Код находит запись по телефону и предлагает
    // перенос/отмену словами; решение клиента ловит cancel_pending на след. ходе.
    // Если в этом же ответе сработала авто-запись — отмену/перенос НЕ обрабатываем
    // (иначе создали запись, а клиенту ушёл бы текст про отмену — рассинхрон).
    if (parsed.cancelRequest && !autobookHandled) {
      if (!cancelEnabled(env)) {
        // Фича выключена — просьбу об отмене не глотаем, отдаём менеджеру.
        handoff = 'отмена записи (ручная)';
        booking = null;
      } else {
        try {
          let cphone = '';
          try { cphone = normalizePhone(await getContactPhone(env, msg)) || ''; } catch (_) { cphone = ''; }
          const cs = await handleCancelStart(env, msg, cphone);
          clientText = cs.clientText || clientText;
          handoff = (!cs.found && cs.handoff) ? cs.handoff : null;
          booking = null; // клиент про отмену, не про новую запись
        } catch (e) {
          console.error('handleCancelStart failed:', e && e.message);
        }
      }
    }

    // Просьба ПЕРЕНЕСТИ запись (тег от Claude). Бот переносит ЛЮБУЮ услугу САМ
    // (тот же мастер, реальные новые окна Altegio); нет окон/ошибка → администратору.
    // Решение клиента (день → выбор слота) ловит reschedule_pending на след. ходах.
    if (parsed.rescheduleRequest && !parsed.cancelRequest && !autobookHandled) {
      try {
        let rphone = '';
        try { rphone = normalizePhone(await getContactPhone(env, msg)) || ''; } catch (_) { rphone = ''; }
        const rs = await handleRescheduleStart(env, msg, rphone);
        clientText = rs.clientText || clientText;
        handoff = rs.handoff || null;
        booking = null;
      } catch (e) {
        console.error('handleRescheduleStart failed:', e && e.message);
      }
    }
  } else {
    claudeFailed = true;
    clientText = 'Спасибо за сообщение! 🌸 Сейчас передам вас менеджеру — '
      + 'он(а) свяжется с вами в ближайшее время.';
    handoff = 'bot_unavailable';
  }

  // После состоявшегося КЭВ повторные BOOKING-теги игнорируем (карточка уже у
  // менеджера). Запрос изменения/отмены Claude отдаёт HANDOFF'ом — он пройдёт.
  // (Авто-запись BOOK_CONSULT выше kev_pending НЕ гасит — это отдельная ветка.)
  if (booking && kevPending) {
    console.log(`booking suppressed (kev already pending) ${tag}`);
    booking = null;
  }

  // Валидация КЭВ: тег без обязательных полей НЕ закрывает диалог — бот
  // игнорирует тег, запоминает недостающее (kev_missing) и добирает дальше.
  let bookingMissing = null;
  if (booking) {
    const v = validateBooking(booking);
    if (v.ok) {
      booking.phone = v.phone; // нормализованный 7XXXXXXXXXX
    } else {
      bookingMissing = v.missing;
      console.log(`booking incomplete ${tag}: ${v.missing.join('; ')} — добор`);
      booking = null;
    }
  }

  // Ответ клиенту. Если не доставлено — не помечаем seen и не сохраняем
  // историю: остаётся шанс на повторную обработку.
  const sent = await sendMessage(env, msg, clientText);
  if (!sent) {
    console.error(`reply not delivered ${tag}`);
    return;
  }

  await env.BOT_KV.put(seenKey, '1', { expirationTtl: DEDUP_TTL });

  // Память добора: каких полей КЭВ не хватило в этом ходе (подмешается в
  // следующий запрос к Claude). Полный валидный BOOKING очищает её в handleBooking.
  if (bookingMissing) {
    await env.BOT_KV.put(`kev_missing:${msg.userId}`, JSON.stringify({
      missing: bookingMissing,
      at: Date.now(),
      channelId: msg.channelId,
      channelUuid: msg.channelUuid,
    }), { expirationTtl: KEV_MISSING_TTL });
  }

  // История: перечитываем свежую копию — параллельный вебхук того же клиента
  // мог записать раньше; берём более длинную, чтобы не затереть чужой ход.
  const histFresh = (await env.BOT_KV.get(histKey, { type: 'json' })) || [];
  const base = histFresh.length > baseLen ? histFresh : histBefore;
  let merged = appendTurn(base, 'user', msg.text);
  merged = appendTurn(merged, 'assistant', clientText);
  await env.BOT_KV.put(histKey, JSON.stringify(merged.slice(-HISTORY_LIMIT)),
    { expirationTtl: HISTORY_TTL });

  if (handoff) await handleHandoff(env, msg, handoff);
  if (booking) await handleBooking(env, msg, booking);

  console.log(`done ${tag} booking=${!!booking} handoff=${handoff || '-'}`
    + `${autobooked ? ' AUTO-BOOKED' : ''}`
    + `${bookingMissing ? ` missing=${bookingMissing.length}` : ''}`
    + `${kevPending ? ' kev-pending' : ''}${claudeFailed ? ' claude-fail' : ''}`);
}

// Служебная заметка для Claude (клиент её не видит, в KV-историю не пишется):
// контекст «КЭВ уже состоялся» / «каких полей не хватает» / «авто-запись доступна».
// autobookAvailable — авто-запись реально включена СЕЙЧАС (kill-switch + allowlist
// + ночь): только тогда Claude эмитит OFFER_SLOTS, иначе ведёт обычный КЭВ.
function buildServiceNote(kevPending, kevMissing, autobookAvailable, cancelAvailable, firstContact) {
  if (kevPending) {
    const what = [kevPending.service, kevPending.day, kevPending.interval]
      .filter(Boolean).join(', ');
    return '[СЛУЖЕБНОЕ, КЛИЕНТ ЭТОГО НЕ ВИДИТ: заявка этого клиента УЖЕ передана '
      + `администратору${what ? ` (${what})` : ''}. Отвечай на уточняющие вопросы по сути. `
      + 'Заявку заново НЕ собирай, теги BOOKING_JSON/BOOKING/OFFER_SLOTS НЕ ставь. По '
      + 'вопросам времени и записи: «администратор свяжется и подтвердит». '
      + (cancelAvailable
        ? 'Если клиент хочет ОТМЕНИТЬ запись — поставь [[CANCEL_REQUEST]]; если ПЕРЕНЕСТИ — [[HANDOFF | перенос записи]].]'
        : 'Если клиент хочет ИЗМЕНИТЬ или ОТМЕНИТЬ договорённость — поставь [[HANDOFF | изменение заявки]].]');
  }
  const parts = [];
  if (firstContact) {
    parts.push('ЭТО ПЕРВОЕ СООБЩЕНИЕ КЛИЕНТА. После короткого приветствия '
      + '(«Здравствуйте! Меня зовут Алия 🌸») ОБЯЗАТЕЛЬНО ответь по сути именно на то, '
      + 'что он написал, В ТОМ ЖЕ сообщении: (1) если он назвал зону или процедуру '
      + '(живот, бока, целлюлит, кавитация, ЛПГ, эпиляция, лицо и т.п.) — тепло подхвати '
      + 'ИМЕННО ЕЁ и НЕ переспрашивай «какая зона/процедура» (он уже сказал); (2) если он '
      + 'спросил ЦЕНУ — назови её ПЕРВОЙ строкой (золотое правило 1); нет точной цены этой '
      + 'процедуры — скажи про пробное со скидкой 50% и что точную подберёт мастер на '
      + 'консультации, но НЕ переспрашивай «какая процедура»; (3) задал конкретный вопрос — '
      + 'ответь на него. Отвечать на конкретный запрос пустым «Чем могу помочь?» / «Какая '
      + 'процедура вас интересует?» ЗАПРЕЩЕНО. Затем мягко веди к бесплатной консультации.');
  }
  if (autobookAvailable) {
    parts.push('АВТО-ЗАПИСЬ ДОСТУПНА СЕЙЧАС: клиент хочет записаться / спрашивает свободное '
      + 'время («когда свободно», «окошки на воскресенье», «запишите») / готов прийти — собери '
      + 'имя+фамилию, процедуру/зону, противопоказания (у нового) и ставь [[OFFER_SLOTS|{...}]] '
      + '(день клиента → day_hint) ВМЕСТО ответа «администратор подтвердит» и вместо BOOKING_JSON. '
      + 'Система сама покажет реальные окна и запишет. Сам время НЕ называй.');
  } else {
    parts.push('АВТО-ЗАПИСЬ СЕЙЧАС НЕДОСТУПНА: OFFER_SLOTS/BOOK_CONSULT НЕ ставь, '
      + 'закрывай обычным путём — день+интервал словами и BOOKING_JSON.');
  }
  if (kevMissing && Array.isArray(kevMissing.missing) && kevMissing.missing.length) {
    parts.push('Для заявки ещё не хватает: ' + kevMissing.missing.join(', ')
      + '. Уточни недостающее естественно (по одному вопросу за сообщение).');
  }
  return parts.length ? `[СЛУЖЕБНОЕ, КЛИЕНТ ЭТОГО НЕ ВИДИТ: ${parts.join(' ')}]` : '';
}

// ── Голосовые сообщения: распознавание через Workers AI (Whisper) ───────────

function isVoiceMessage(msg) {
  return VOICE_TYPES.includes(String(msg.messageType || '').toLowerCase())
    && !!msg.fileUrl;
}

// Транскрипция голосового. Возвращает текст или '' (не вышло — вызывающий
// решает, что делать). Best-effort: любые сбои логируются и не роняют поток.
async function transcribeVoice(env, msg) {
  if (!env.AI || typeof env.AI.run !== 'function') {
    console.log('voice: AI binding не подключён, пропуск');
    return '';
  }
  let buf;
  try {
    const res = await fetch(msg.fileUrl);
    if (!res.ok) {
      console.error('voice fetch:', res.status);
      return '';
    }
    const len = Number(res.headers.get('content-length') || 0);
    if (len && len > VOICE_MAX_BYTES) {
      console.log(`voice: файл ${len} байт > лимита, менеджеру`);
      return '';
    }
    buf = await res.arrayBuffer();
    if (buf.byteLength > VOICE_MAX_BYTES) {
      console.log('voice: файл больше лимита, менеджеру');
      return '';
    }
  } catch (e) {
    console.error('voice fetch error:', e && e.message);
    return '';
  }

  let out = null;
  try {
    out = await env.AI.run(VOICE_MODEL, { audio: bufToBase64(buf) });
  } catch (e1) {
    console.error(`voice ${VOICE_MODEL}:`, e1 && e1.message);
    try {
      out = await env.AI.run(VOICE_MODEL_FALLBACK, { audio: [...new Uint8Array(buf)] });
    } catch (e2) {
      console.error(`voice ${VOICE_MODEL_FALLBACK}:`, e2 && e2.message);
      return '';
    }
  }
  const text = String((out && out.text) || '').trim();
  // Совсем короткий «текст» — шум/вздох, не сообщение.
  return text.length >= 2 ? text.slice(0, 1500) : '';
}

// ArrayBuffer → base64 (вход whisper-large-v3-turbo) без переполнения стека.
function bufToBase64(buf) {
  const bytes = new Uint8Array(buf);
  let bin = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(bin);
}

// Зрение: скачать фото клиента, показать Claude (vision) с анти-медицинскими
// гайками, ответить тепло и увести на бесплатную консультацию. Возвращает true,
// если ответил клиенту; false → вызывающий падает на уведомление менеджеру.
async function handleClientImage(env, msg) {
  if (!msg.fileUrl || !env.ANTHROPIC_API_KEY) return false;

  // Дедуп ПАЧКИ фото — отвечаем ОДИН раз на серию фото, присланных разом.
  // claim+verify: каждый вызов пишет свой id, ждёт сбор пачки, перечитывает —
  // отвечает ТОЛЬКО последний writer (KV last-write-wins). Остальные → return true
  // (обслужено, без карточки менеджеру). После ответа ставим 'done' (cooldown).
  const burstKey = `vision_burst:${msg.userId}`;
  const myId = String(msg.messageId || msg.fileUrl || '');
  if (myId && msg.userId) {
    const cur = await env.BOT_KV.get(burstKey);
    if (cur === 'done') { console.log(`vision burst: пачка уже отвечена, skip u${msg.userId}`); return true; }
    await env.BOT_KV.put(burstKey, myId, { expirationTtl: VISION_BURST_TTL });
    await sleep(VISION_BURST_WAIT_MS);                  // собрать пачку + дать KV сойтись
    const owner = await env.BOT_KV.get(burstKey);
    if (owner === 'done') return true;                  // победитель уже ответил
    if (owner && owner !== myId) {                      // не я — ответит победитель
      console.log(`vision burst: не победитель, skip u${msg.userId}`);
      return true;
    }
  }

  let buf;
  let mime = '';
  try {
    const res = await fetchWithTimeout(msg.fileUrl, {}, 15000);
    if (!res.ok) { console.error('image fetch:', res.status); return false; }
    mime = String(res.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
    const len = Number(res.headers.get('content-length') || 0);
    if (len && len > IMAGE_MAX_BYTES) { console.log('vision: фото больше лимита'); return false; }
    buf = await res.arrayBuffer();
    if (buf.byteLength > IMAGE_MAX_BYTES) { console.log('vision: фото больше лимита'); return false; }
  } catch (e) { console.error('image fetch error:', e && e.message); return false; }
  if (!IMAGE_MIME_OK.includes(mime)) mime = 'image/jpeg';  // дефолт, если заголовок не отдал тип

  const payload = {
    model: env.ANTHROPIC_MODEL || DEFAULT_MODEL,
    max_tokens: 400,
    temperature: BOT_TEMPERATURE,
    system: [{ type: 'text', text: VISION_SYSTEM }],
    messages: [{
      role: 'user',
      content: [
        { type: 'image', source: { type: 'base64', media_type: mime, data: bufToBase64(buf) } },
        { type: 'text', text: 'Клиент прислал это фото в WhatsApp студии. Ответь строго по правилам.' },
      ],
    }],
  };
  let reply = '';
  try {
    const res = await fetchWithTimeout(ANTHROPIC_URL, {
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': ANTHROPIC_VERSION,
        'content-type': 'application/json',
      },
      body: JSON.stringify(payload),
    }, 25000);
    if (!res.ok) { console.error('vision claude:', res.status); return false; }
    const data = await res.json().catch(() => null);
    reply = ((data && data.content) || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim();
  } catch (e) { console.error('vision call error:', e && e.message); return false; }
  if (!reply) return false;
  // На всякий случай снимаем управляющие теги, если модель их вставила.
  reply = parseControlTags(reply).cleanText || reply;
  if (!reply) return false;

  const sent = await sendMessage(env, msg, reply);
  if (!sent) return false;

  // Пачка обслужена — cooldown, чтобы трейлинг-фото из той же серии не вызвали 2-й ответ.
  if (msg.userId) {
    try { await env.BOT_KV.put(`vision_burst:${msg.userId}`, 'done', { expirationTtl: VISION_DONE_TTL }); }
    catch (_) { /* best-effort */ }
  }

  // История: фиксируем, что был фото-обмен (следующий ход бот ведёт с контекстом).
  try {
    const histKey = `hist:${msg.userId}`;
    const hist = (await env.BOT_KV.get(histKey, { type: 'json' })) || [];
    let merged = appendTurn(hist, 'user', '[клиент прислал фото]');
    merged = appendTurn(merged, 'assistant', reply);
    await env.BOT_KV.put(histKey, JSON.stringify(merged.slice(-HISTORY_LIMIT)), { expirationTtl: HISTORY_TTL });
  } catch (_) { /* история best-effort */ }
  await bumpStat(env, 'vision_done');
  return true;
}

// ── Гейт: новый лид или действующий клиент (УСТАРЕЛО — не вызывается) ───────
// ⚠️ clients/search в кабинете 1330174 отдаёт 400 «Incorrect request filter
// state format» на quick_search И не возвращает visit_count → эта функция молча
// возвращала 'new' (гейт не работал). Заменено на altegioUpcomingBooking
// (records, рабочий запрос) в processMessage. Оставлено до починки clients/search
// (нужен рабочий формат фильтра по телефону / поддержка Altegio).
// Возвращает 'new' | 'existing'. Действующий клиент = есть история визитов в
// Altegio. Бот Altegio только ЧИТАЕТ.
// Altegio-проверка опциональна: без токенов гейт опирается на остальные слои
// (фильтр destination, пауза оператора, распознавание в промпте). При любой
// ошибке/неопределённости → 'new': лид не блокируем, действующего клиента
// подстрахуют пауза оператора и промпт ([[HANDOFF | existing_client]]).
async function classifyContact(msg, env) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN || !env.ALTEGIO_COMPANY_ID) {
    return 'new';
  }
  try {
    const phone = await getContactPhone(env, msg);
    if (!phone) return 'new';
    return (await altegioHasVisitHistory(env, phone)) ? 'existing' : 'new';
  } catch (e) {
    console.error('classifyContact error:', e && e.message);
    return 'new';
  }
}

// Отвечал ли в этом диалоге сегодня-вчера ЧЕЛОВЕК. Источник — журнал событий
// mm-pulse-bot (binding PULSE_KV, читаем read-only по соглашению): pulse пишет
// в events:{YYYY-MM-DD} все сообщения проекта; исходящие самого mh-bot там
// помечены bot:true и человеком не считаются. Нет binding'а / журнал пуст —
// false (бот работает как раньше). Проверяется один раз — на первом контакте
// бота с клиентом (дальше ownership ведут op:-пауза и сигналы from_*).
async function humanOwnsDialog(env, userId) {
  if (!env.PULSE_KV || typeof env.PULSE_KV.get !== 'function') return false;
  const now = almatyNow();
  for (const ymd of [now.ymd, ymdDaysAhead(now, -1)]) {
    let bucket = null;
    try {
      bucket = await env.PULSE_KV.get(`events:${ymd}`, { type: 'json' });
    } catch (e) {
      console.error('humanOwnsDialog read:', e && e.message);
      return false; // не смогли прочитать — не блокируем бота
    }
    if (!Array.isArray(bucket)) continue;
    for (const e of bucket) {
      if (e && String(e.dialog_id) === String(userId)
        && e.direction === 'operator' && !e.bot) return true;
    }
  }
  return false;
}

// Телефон клиента по user_id из message.help. Используем uuid того канала,
// откуда пришёл вебхук (msg.channelUuid).
async function getContactPhone(env, msg) {
  const token = await getMhToken(env);
  if (!token) return null;
  const url = `${MH_API}/app/projects/${env.MH_PROJECT_ID}`
    + `/channels/${msg.channelUuid}/users/${msg.userId}`;
  let res;
  try {
    res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  } catch (e) {
    console.error('mh get-user error:', e && e.message);
    return null;
  }
  if (!res.ok) {
    console.error('mh get-user:', res.status);
    return null;
  }
  const data = await res.json().catch(() => null);
  const u = (data && data.data) || data || {};
  const raw = u.phone || u.contact_phone || (u.contact && u.contact.phone) || '';
  const digits = String(raw).replace(/\D/g, '');
  return digits.length >= 10 ? digits : null;
}

// Есть ли у телефона история визитов в Altegio (= действующий клиент).
// Бот только читает.
async function altegioHasVisitHistory(env, phone) {
  const url = `${ALTEGIO_API}/company/${env.ALTEGIO_COMPANY_ID}/clients/search`;
  let res;
  try {
    res = await fetch(url, {
      method: 'POST',
      headers: altegioHeaders(env),
      body: JSON.stringify({
        page: 1,
        page_size: 5,
        fields: ['id', 'phone', 'visit_count'],
        filters: [{ type: 'quick_search', state: phone }],
      }),
    });
  } catch (e) {
    console.error('altegio search error:', e && e.message);
    return false;
  }
  if (!res.ok) {
    console.error('altegio search:', res.status);
    return false;
  }
  const data = await res.json().catch(() => null);
  const list = (data && data.data) || [];
  if (!Array.isArray(list) || !list.length) return false;
  // Действующий клиент — тот, кто уже был в студии (есть визиты).
  return list.some((c) => Number(c && c.visit_count) > 0);
}

// Ближайшая активная запись клиента (по телефону) на сегодня..+2 дня.
// Источник правды «клиент уже записан» (отвечает на напоминание, а не новый лид).
// Берём через records (start_date/end_date = ДАТА ВИЗИТА; clients/search в этом
// кабинете Altegio отдаёт 400 на quick_search). Бот только читает. Любая
// ошибка / нет токенов / нет телефона → null (безопасный фоллбэк на обычный поток).
// Быстрый поиск клиента по телефону (clients/search, quick_search → state.value
// — РАБОЧИЙ формат, в отличие от прежней пробы). Возвращает {found, name,
// lastVisitDate, returning} или null. Кэш clientlk:{tail} на 7 дней.
async function altegioClientLookup(env, phone) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN || !env.ALTEGIO_COMPANY_ID) return null;
  const norm = normalizePhone(phone);
  const tail = String(norm || '').replace(/\D/g, '').slice(-10);
  if (tail.length < 10) return null;
  const ck = `clientlk:${tail}`;
  try { const cached = await env.BOT_KV.get(ck); if (cached) return JSON.parse(cached); } catch (_) { /* пересоберём */ }
  let result = { found: false, name: null, lastVisitDate: null, returning: false };
  try {
    const res = await fetch(`${ALTEGIO_API}/company/${env.ALTEGIO_COMPANY_ID}/clients/search`, {
      method: 'POST', headers: altegioHeaders(env),
      body: JSON.stringify({
        page: 1, page_size: 5, fields: ['id', 'name', 'phone', 'last_visit_date'],
        filters: [{ type: 'quick_search', state: { value: norm } }],
      }),
    });
    if (!res.ok) { console.error('clientLookup:', res.status); return null; } // ошибку не кэшируем
    const data = await res.json().catch(() => null);
    const list = (data && data.data) || [];
    const hit = (Array.isArray(list) ? list : []).find((c) =>
      String(c.phone || '').replace(/\D/g, '').slice(-10) === tail);
    if (hit) {
      result = { found: true, name: hit.name || null, lastVisitDate: hit.last_visit_date || null, returning: !!hit.last_visit_date };
    }
  } catch (e) { console.error('clientLookup fetch:', e && e.message); return null; }
  try { await env.BOT_KV.put(ck, JSON.stringify(result), { expirationTtl: 7 * 24 * 3600 }); } catch (_) {}
  return result;
}

async function altegioUpcomingBooking(env, phone) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN || !env.ALTEGIO_COMPANY_ID) return null;
  const tail = String(phone || '').replace(/\D/g, '').slice(-10);
  if (tail.length < 10) return null;
  const now = almatyNow();
  const url = `${ALTEGIO_API}/records/${env.ALTEGIO_COMPANY_ID}`
    + `?start_date=${now.ymd}&end_date=${ymdDaysAhead(now, 2)}&count=300&page=1`;
  let res;
  try {
    res = await fetch(url, { headers: altegioHeaders(env) });
  } catch (e) {
    console.error('upcoming booking fetch:', e && e.message);
    return null;
  }
  if (!res.ok) { console.error('upcoming booking:', res.status); return null; }
  const data = await res.json().catch(() => null);
  const list = (data && data.data) || [];
  if (!Array.isArray(list)) return null;
  let best = null;
  for (const r of list) {
    if (!r || r.deleted) continue;
    const cph = String((r.client && r.client.phone) || '').replace(/\D/g, '').slice(-10);
    if (cph !== tail) continue;
    const parts = parseAltegioParts(r.date || r.datetime);
    const ms = parts ? partsToAlmatyMs(parts) : null;
    if (!ms) continue;
    if (!best || ms < best.ms) best = { recordId: r.id, date: r.date, ms };
  }
  return best;
}

// Ближайшая БУДУЩАЯ запись клиента (для отмены). Шире, чем altegioUpcomingBooking
// (горизонт CANCEL_LOOKAHEAD_DAYS, постранично — журнал за 200 строк не влезает),
// и возвращает детали для подтверждения клиенту. null — нет/не смогли.
async function altegioFindCancelable(env, phone) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN || !env.ALTEGIO_COMPANY_ID) return null;
  const tail = String(phone || '').replace(/\D/g, '').slice(-10);
  if (tail.length < 10) return null;
  const now = almatyNow();
  const look = parseInt(env.CANCEL_LOOKAHEAD_DAYS, 10) || CANCEL_LOOKAHEAD_DEFAULT;
  let recs;
  try { recs = await altegioFetchRecordsPaged(env, now.ymd, ymdDaysAhead(now, look), 5); }
  catch (e) { console.error('findCancelable fetch:', e && e.message); return null; }
  if (!Array.isArray(recs)) return null;
  const nowMs = Date.now();
  let best = null;
  for (const r of recs) {
    if (!r || r.deleted || Number(r.attendance) === -1) continue;
    const cph = String((r.client && r.client.phone) || '').replace(/\D/g, '').slice(-10);
    if (cph !== tail) continue;
    const parts = parseAltegioParts(r.date || r.datetime);
    const ms = parts ? partsToAlmatyMs(parts) : null;
    if (!ms || ms < nowMs + 60000) continue;            // только будущее
    if (best && ms >= best.ms) continue;
    const svcObj = (Array.isArray(r.services) && r.services[0]) || null;
    best = {
      recordId: r.id, datetime: r.date || r.datetime, ms,
      hhmm: `${parts.hour}:${String(parts.minute || 0).padStart(2, '0')}`,
      serviceTitle: (svcObj && svcObj.title) || '',
      serviceId: svcObj && svcObj.id != null ? String(svcObj.id) : '',
      staffId: (r.staff && r.staff.id != null) ? String(r.staff.id) : '',
      clientName: (r.client && r.client.name) || '',
      staffName: (r.staff && r.staff.name) || '',
    };
  }
  return best;
}

// Отмена записи (DELETE /record). Перед удалением СВЕРКА: запись существует,
// принадлежит этому телефону, в будущем. Возвращает true только при реальном
// удалении (или если запись уже была удалена). Любая неоднозначность → false
// (вызывающий передаст менеджеру).
async function altegioCancelRecord(env, recordId, expectPhone) {
  if (!recordId) return false;
  const rec = await altegioFetchRecord(env, recordId);
  if (!rec) { console.error('cancel: record not found', recordId); return false; }
  if (rec.deleted) return true;                          // уже отменена — идемпотентно
  const tail = String(expectPhone || '').replace(/\D/g, '').slice(-10);
  const cph = String((rec.client && rec.client.phone) || '').replace(/\D/g, '').slice(-10);
  if (tail && cph && tail !== cph) { console.error('cancel: phone mismatch, abort', recordId); return false; }
  const parts = parseAltegioParts(rec.date || rec.datetime);
  const ms = parts ? partsToAlmatyMs(parts) : null;
  if (ms && ms < Date.now() - 60000) { console.error('cancel: record in past, abort', recordId); return false; }
  const url = `${ALTEGIO_API}/record/${env.ALTEGIO_COMPANY_ID}/${recordId}`;
  let res;
  try { res = await fetchWithTimeout(url, { method: 'DELETE', headers: altegioHeaders(env) }, 12000); }
  catch (e) { console.error('cancel DELETE network:', e && e.message); return false; }
  if (res.status === 200 || res.status === 201 || res.status === 204) return true;
  console.error('cancel DELETE:', res.status, (await res.text().catch(() => '')).slice(0, 200));
  return false;
}

// Заголовки Altegio API (двойной токен: партнёр + пользователь).
function altegioHeaders(env) {
  return {
    Authorization: `Bearer ${env.ALTEGIO_PARTNER_TOKEN}, User ${env.ALTEGIO_USER_TOKEN}`,
    Accept: 'application/vnd.api.v2+json',
    'Content-Type': 'application/json',
  };
}

// ── История: чередование ролей, склейка подряд идущих сообщений одной роли ──
function appendTurn(history, role, content) {
  const h = history.slice();
  const last = h[h.length - 1];
  if (last && last.role === role) {
    h[h.length - 1] = { role, content: `${last.content}\n${content}` };
  } else {
    h.push({ role, content });
  }
  return h;
}

// ── Вызов Claude API (raw fetch, prompt caching, retry) ─────────────────────
// serviceNote (опц.) — служебный контекст хода («КЭВ уже передан» / «не хватает
// полей»), добавляется ТОЛЬКО в последнее user-сообщение запроса; в KV-историю
// не попадает, prompt cache системного префикса не ломает.
// ── Аналитика воронки бота (грубые дневные счётчики) ─────────────────────────
// stat:{ymd}:{metric} в KV, TTL 8 дней. read-modify-write — при гонке возможен
// небольшой недоучёт; для приблизительной аналитики это допустимо.
const STAT_TTL = 8 * 24 * 3600;
async function bumpStat(env, metric, n = 1) {
  try {
    if (!env.BOT_KV) return;
    const k = `stat:${almatyNow().ymd}:${metric}`;
    const cur = parseInt((await env.BOT_KV.get(k)) || '0', 10) || 0;
    await env.BOT_KV.put(k, String(cur + n), { expirationTtl: STAT_TTL });
  } catch (e) { console.error('bumpStat:', e && e.message); }
}
async function readStat(env, ymd, metric) {
  try { return parseInt((await env.BOT_KV.get(`stat:${ymd}:${metric}`)) || '0', 10) || 0; }
  catch (_) { return 0; }
}

// Дневной отчёт воронки бота + heartbeat «я жив» в Telegram управления. Раз в
// сутки в DAILY_REPORT_HOUR за ПРОШЕДШИЕ сутки, дедуп per-day.
const DAILY_REPORT_HOUR = 9;
async function runDailyBotReport(env) {
  const now = almatyNow();
  if (now.hour !== (Number(env.DAILY_REPORT_HOUR) || DAILY_REPORT_HOUR)) return;
  if (!env.BOT_KV) return;
  const y = ymdDaysAhead(now, -1);
  const dk = `dailyreport_sent:${y}`;
  if (await env.BOT_KV.get(dk)) return;
  await env.BOT_KV.put(dk, '1', { expirationTtl: STAT_TTL });
  const [inc, kev, handoff, yes, no, autob, media, cancelDone, resched] = await Promise.all([
    readStat(env, y, 'in'), readStat(env, y, 'kev'), readStat(env, y, 'handoff'),
    readStat(env, y, 'confirm_yes'), readStat(env, y, 'confirm_no'),
    readStat(env, y, 'autobook_done'), readStat(env, y, 'media_in'),
    readStat(env, y, 'cancel_done'), readStat(env, y, 'reschedule_req'),
  ]);
  // Доходимость до КОНСУЛЬТАЦИИ (главная метрика бота) — по журналу Altegio за
  // вчера: услуга-консультация с attendance==1 (пришёл). Студийно, best-effort.
  let consultCame = null;
  try {
    if (env.ALTEGIO_PARTNER_TOKEN && env.ALTEGIO_USER_TOKEN && env.ALTEGIO_COMPANY_ID) {
      const recs = await altegioFetchRecordsPaged(env, y, y, 5);
      const svc = String(env.ALTEGIO_CONSULT_SERVICE_ID || '');
      consultCame = (recs || []).filter((r) => r && !r.deleted
        && Number(r.attendance) === 1
        && (r.services || []).some((s) => String(s.id) === svc)).length;
    }
  } catch (e) { console.error('daily consult count:', e && e.message); }

  const lines = [
    `📊 Бот Алия — за ${y}`,
    `• Входящих обработано: ${inc}`,
    `• Договорённостей о визите (КЭВ): ${kev}`,
    `• Бот сам записал на консультацию: ${autob}`,
    `• Передач менеджеру: ${handoff}`,
    `• Прислали фото/медиа: ${media}`,
    `• Ответов на подтверждение: +${yes} / −${no}`,
  ];
  if (cancelDone || resched) lines.push(`• Отмена/перенос по просьбе: ${cancelDone} / ${resched}`);
  if (consultCame !== null) lines.push(`• Пришли на консультацию (вся студия): ${consultCame}`);
  lines.push('', 'Бот работает в штатном режиме ✅');
  await sendTelegramAlert(env, lines.join('\n'));
}

// ── РЕАКТИВАЦИЯ «давно не были» (за флагом REACTIVATION_ACTIVE) ───────────────
// База — НЕ список клиентов (Altegio в списке не отдаёт last_visit), а ЖУРНАЛ
// записей: кто был в окне [today-MAX, today-MIN] дней и НЕ появлялся с тех пор.
// Шлём мягкое приглашение на бесплатную консультацию ТОЛЬКО через канал, где
// клиент уже писал нам (mhSendByPhone — не открывает новый номер). Анти-бан:
// малый дневной лимит + спейсинг + дедуп react_done (90 дн) + opt-out.
const REACT_DONE_TTL = 90 * 24 * 3600;
function reactivationText(name) {
  const hi = name ? `Здравствуйте, ${name}! ` : 'Здравствуйте! ';
  return `${hi}Это студия M&M 🌷 Давно вас не было — будем рады видеть снова. `
    + 'У нас есть бесплатная консультация с диагностикой: мастер подскажет, что освежить под вашу задачу. '
    + 'Заглянете на этой неделе или на следующей?';
}
async function collectReactivationCandidates(env, now) {
  const minD = Number(env.REACT_MIN_DAYS) || 60;
  const maxD = Number(env.REACT_MAX_DAYS) || 90;
  const oldRecs = await altegioFetchRecordsPaged(env, ymdDaysAhead(now, -maxD), ymdDaysAhead(now, -minD), 5);
  const recentRecs = await altegioFetchRecordsPaged(env, ymdDaysAhead(now, -(minD - 1)), now.ymd, 5);
  const recent = new Set();
  for (const r of recentRecs || []) {
    const p = normalizePhone((r && r.client && r.client.phone) || '');
    if (p) recent.add(p);
  }
  const seen = new Set();
  const out = [];
  for (const r of oldRecs || []) {
    if (!r || r.deleted || Number(r.attendance) === -1) continue;
    const p = normalizePhone((r.client && r.client.phone) || '');
    if (!p || recent.has(p) || seen.has(p)) continue;
    if (isInternalPhone(env, p)) continue;
    seen.add(p);
    out.push({ phone: p, name: firstName((r.client && r.client.name) || '') });
  }
  return out;
}
async function runReactivationJob(env) {
  if (String(env.REACTIVATION_ACTIVE) !== '1') return;
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN || !env.ALTEGIO_COMPANY_ID) return;
  const now = almatyNow();
  if (now.hour !== (Number(env.REACT_HOUR) || 12)) return;
  const dk = `react_sent_day:${now.ymd}`;
  if (await env.BOT_KV.get(dk)) return;
  await env.BOT_KV.put(dk, '1', { expirationTtl: STAT_TTL });
  let cands = [];
  try { cands = await collectReactivationCandidates(env, now); }
  catch (e) { console.error('react candidates:', e && e.message); return; }
  if (!cands.length) { console.log('react: 0 candidates'); return; }
  const perRun = Number(env.REACT_PER_RUN) || 5;
  let sent = 0;
  for (const c of cands) {
    if (sent >= perRun) break;
    if (await env.BOT_KV.get(`react_done:${c.phone}`)) continue;
    if (await env.BOT_KV.get(`optout:${c.phone}`)) continue;
    let r = null;
    try { r = await mhSendByPhone(env, c.phone, reactivationText(c.name)); }
    catch (_) { r = null; }
    if (r && r.ok) {
      await env.BOT_KV.put(`react_done:${c.phone}`, '1', { expirationTtl: REACT_DONE_TTL });
      await bumpStat(env, 'react_sent');
      sent++;
      if (sent < perRun) await sleep(60000);   // спейсинг анти-бан
    }
  }
  console.log(`react: ${sent} sent of ${cands.length} cand`);
}

// Критический алерт «бот не отвечает клиентам» — в Telegram (группа управления).
// Дедуп per-kind (botdown_alert:{kind}) на 30 мин: при сбое алерт уходит ОДИН раз,
// а не на каждое входящее сообщение, пока проблема держится.
const BOTDOWN_ALERT_TTL = 1800;
async function alertBotDown(env, kind, detail) {
  try {
    if (!env.BOT_KV) return;
    const dk = `botdown_alert:${kind}`;
    if (await env.BOT_KV.get(dk)) return;
    await env.BOT_KV.put(dk, '1', { expirationTtl: BOTDOWN_ALERT_TTL });
    const map = {
      balance: 'Закончился баланс Anthropic API — бот Алия НЕ отвечает клиентам.\n'
        + 'Пополните: console.anthropic.com/settings/billing',
      apikey: 'Проблема с ключом Anthropic API (неверный/отозван) — бот Алия НЕ отвечает.\n'
        + 'Проверьте: console.anthropic.com/settings/keys',
      overload: 'Claude API перегружен или недоступен — бот Алия временно не отвечает (идут повторы).',
      http: 'Claude API вернул ошибку — бот Алия не отвечает клиентам.',
    };
    await sendTelegramAlert(env, `⚠️ БОТ АЛИЯ: СБОЙ\n\n${map[kind] || map.http}`
      + (detail ? `\n\nДетали: ${detail}` : ''));
  } catch (e) {
    console.error('alertBotDown:', e && e.message);
  }
}

// fetch с таймаутом (AbortController): зависший апстрим не съедает бюджет
// воркера. Таймаут → бросает (как сетевая ошибка), вызывающий ловит в catch и
// идёт по своей ветке ретрая/фоллбэка. ms по умолчанию 15с.
async function fetchWithTimeout(url, opts, ms) {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), ms || 15000);
  try {
    return await fetch(url, { ...(opts || {}), signal: ac.signal });
  } finally {
    clearTimeout(timer);
  }
}

// Срок действия зашитого блока акций. Просрочено → блок ВЫРЕЗАЕТСЯ из системного
// промпта КОДОМ (а не надеемся, что LLM сам промолчит по дате). Новую акцию
// добавлять между маркерами <!--PROMO-->…<!--/PROMO--> и обновлять дату.
const PROMO_END_YMD_DEFAULT = '2026-06-15';
function buildSystemPrompt(env) {
  const ymd = almatyNow().ymd;
  const end = (env && env.PROMO_END_YMD) || PROMO_END_YMD_DEFAULT;
  if (ymd > end) {
    return SYSTEM_PROMPT.replace(/<!--PROMO-->[\s\S]*?<!--\/PROMO-->\n?/g, '').replace(/\n{3,}/g, '\n\n');
  }
  return SYSTEM_PROMPT.replace(/<!--\/?PROMO-->\n?/g, '');
}

async function callClaude(env, history, serviceNote) {
  // Слоты в промпт НЕ подмешиваем — бот не показывает временные слоты.
  // НО подмешиваем ТЕКУЩУЮ ДАТУ (Almaty) в последнее user-сообщение —
  // нужна для логики «акция действует до 15.06.2026». Подмешиваем только
  // в последнее сообщение, чтобы системный префикс и старые ходы остались
  // стабильными для prompt cache.
  const apiMessages = history.map((m) => ({ role: m.role, content: m.content }));
  // Дата — для логики акций, время — для обещаний клиенту («администратор
  // свяжется в ближайшее время» днём vs «напишет утром» ночью), см. раздел
  // «ВРЕМЯ СУТОК» в SYSTEM_PROMPT.
  const nowA = almatyNow();
  // День недели подаём ГОТОВЫМ (LLM плохо считают календарь и путают дни) —
  // иначе бот пишет в карточку «суббота 13.06», когда это пятница.
  const WEEKDAYS = ['воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота'];
  const nowStr = `${nowA.ymd} (${WEEKDAYS[nowA.date.getUTCDay()]}), `
    + `${String(nowA.hour).padStart(2, '0')}:${String(nowA.minute).padStart(2, '0')}`;
  for (let i = apiMessages.length - 1; i >= 0; i--) {
    if (apiMessages[i].role === 'user') {
      apiMessages[i] = {
        role: 'user',
        content: `ТЕКУЩАЯ ДАТА И ВРЕМЯ (Алматы): ${nowStr}\n\n${apiMessages[i].content}`
          + (serviceNote ? `\n\n${serviceNote}` : ''),
      };
      break;
    }
  }

  const payload = {
    model: env.ANTHROPIC_MODEL || DEFAULT_MODEL,
    max_tokens: 1024,
    temperature: BOT_TEMPERATURE,
    system: [{ type: 'text', text: buildSystemPrompt(env), cache_control: { type: 'ephemeral' } }],
    messages: apiMessages,
  };

  for (let attempt = 0; attempt < 3; attempt++) {
    let res;
    try {
      res = await fetchWithTimeout(ANTHROPIC_URL, {
        method: 'POST',
        headers: {
          'x-api-key': env.ANTHROPIC_API_KEY,
          'anthropic-version': ANTHROPIC_VERSION,
          'content-type': 'application/json',
        },
        body: JSON.stringify(payload),
      }, 25000);
    } catch (e) {
      console.error('Claude fetch error:', e && e.message);
      await sleep(500 * (attempt + 1));
      continue;
    }

    if (res.ok) {
      const data = await res.json();
      const u = data.usage || {};
      console.log(`claude ok cache_read=${u.cache_read_input_tokens || 0} in=${u.input_tokens || 0} out=${u.output_tokens || 0}`);
      if (data.stop_reason === 'refusal') {
        console.error('Claude refusal — отдаём на менеджера');
        return '';
      }
      const textBlock = (data.content || []).find((b) => b.type === 'text');
      return textBlock ? textBlock.text.trim() : '';
    }

    // 429 / 5xx — ретраить; 4xx (кроме 429) — нет смысла
    if (res.status !== 429 && res.status < 500) {
      const body = (await res.text()).slice(0, 400);
      console.error(`Claude API ${res.status}:`, body.slice(0, 200));
      const low = body.toLowerCase();
      let kind = 'http';
      if (res.status === 401 || low.includes('authentication') || low.includes('invalid x-api-key') || low.includes('api key')) kind = 'apikey';
      else if (low.includes('credit') || low.includes('balance') || low.includes('billing') || low.includes('quota') || low.includes('insufficient')) kind = 'balance';
      await alertBotDown(env, kind, `HTTP ${res.status}`);
      return '';
    }
    const retryAfter = parseInt(res.headers.get('retry-after') || '0', 10);
    await sleep(retryAfter ? retryAfter * 1000 : 800 * (attempt + 1));
  }
  console.error('Claude API: retries exhausted');
  await alertBotDown(env, 'overload', 'повторы исчерпаны (429/5xx)');
  return '';
}

// ── Управляющие теги ────────────────────────────────────────────────────────
// [[BOOKING_JSON|{...}]] — КЭВ-карточка менеджеру (имя/процедура/день/интервал/…).
// [[OFFER_SLOTS|{...}]]  — запрос авто-записи: «клиент готов», система покажет слоты.
// [[BOOK_CONSULT|{...}]] — клиент выбрал слот (slot_ref — номер, НЕ время текстом).
// [[BOOKING|a|b|c|d|e]]  — легаси-формат КЭВ (обратная совместимость).
// [[HANDOFF|причина]]    — передать менеджеру.
// helper: типобезопасный JSON-объект тега или null.
function parseTagJson(raw) {
  try {
    const o = JSON.parse(raw);
    return (o && typeof o === 'object' && !Array.isArray(o)) ? o : null;
  } catch (_) { return null; }
}
const tagStr = (v) => (typeof v === 'string' ? v.trim() : '');

function parseControlTags(text) {
  let booking = null;
  let handoff = null;
  let offerSlots = null;
  let bookConsult = null;
  let cancelRequest = null;
  let rescheduleRequest = null;

  // [[BOOKING_JSON|{...}]]
  const jsonRe = /\[\[\s*BOOKING_JSON\s*\|\s*(\{[\s\S]*?\})\s*\]\]/gi;
  let jm;
  while ((jm = jsonRe.exec(text)) !== null) {
    const o = parseTagJson(jm[1]);
    if (!o) { console.error('BOOKING_JSON parse error'); continue; }
    booking = {
      name: tagStr(o.name),
      phone: tagStr(o.phone).replace(/\D/g, ''),
      service: tagStr(o.service),
      day: tagStr(o.day),
      interval: tagStr(o.interval),
      contraindications: tagStr(o.contra) || tagStr(o.contraindications),
      lang: (tagStr(o.lang).toLowerCase() === 'kz') ? 'kz' : 'ru',
      temp: (tagStr(o.temp).toLowerCase() === 'hot') ? 'hot' : 'warm',
    };
  }

  // [[OFFER_SLOTS|{...}]] — запрос слотов авто-записи.
  const offerRe = /\[\[\s*OFFER_SLOTS\s*\|\s*(\{[\s\S]*?\})\s*\]\]/gi;
  let om;
  while ((om = offerRe.exec(text)) !== null) {
    const o = parseTagJson(om[1]);
    if (!o) { console.error('OFFER_SLOTS parse error'); continue; }
    offerSlots = {
      name: tagStr(o.name),
      contra: tagStr(o.contra) || tagStr(o.contraindications),
      lang: (tagStr(o.lang).toLowerCase() === 'kz') ? 'kz' : 'ru',
      temp: (tagStr(o.temp).toLowerCase() === 'hot') ? 'hot' : 'warm',
      day_hint: tagStr(o.day_hint),
    };
  }

  // [[BOOK_CONSULT|{"slot_ref":"2"}]] — выбор слота. slot_ref ТОЛЬКО как строка/число.
  const bookRe = /\[\[\s*BOOK_CONSULT\s*\|\s*(\{[\s\S]*?\})\s*\]\]/gi;
  let bm;
  while ((bm = bookRe.exec(text)) !== null) {
    const o = parseTagJson(bm[1]);
    if (!o) { console.error('BOOK_CONSULT parse error'); continue; }
    const ref = (typeof o.slot_ref === 'string' || typeof o.slot_ref === 'number')
      ? String(o.slot_ref).trim() : '';
    bookConsult = { slot_ref: ref };
  }

  // [[CANCEL_REQUEST]] или [[CANCEL_REQUEST|{...}]] — клиент просит ОТМЕНИТЬ
  // запись. Само удаление делает код (после поиска записи и согласия клиента).
  const cancelRe = /\[\[\s*CANCEL_REQUEST\s*(?:\|[\s\S]*?)?\]\]/gi;
  if (cancelRe.test(text)) cancelRequest = true;

  // [[RESCHEDULE_REQUEST]] — клиент просит ПЕРЕНЕСТИ запись. Код находит запись и
  // переносит ЛЮБУЮ услугу сам (тот же мастер, реальные новые окна); нет окон/ошибка
  // — отдаёт администратору.
  const reschedRe = /\[\[\s*RESCHEDULE_REQUEST\s*(?:\|[\s\S]*?)?\]\]/gi;
  if (reschedRe.test(text)) rescheduleRequest = true;

  // Легаси [[BOOKING|...]] + [[HANDOFF|...]]
  const re = /\[\[\s*(BOOKING|HANDOFF)\s*\|([^\]]*)\]\]/gi;
  let match;
  while ((match = re.exec(text)) !== null) {
    const kind = match[1].toUpperCase();
    const payload = match[2].trim();
    if (kind === 'BOOKING') {
      if (!booking) {
        const p = payload.split('|').map((s) => s.trim());
        booking = { name: p[0] || '', phone: (p[1] || '').replace(/\D/g, ''),
          service: p[2] || '', day: p[3] || '', interval: '',
          contraindications: p[4] || '', lang: 'ru', temp: 'warm', legacy: true };
      }
    } else {
      handoff = payload || 'general';
    }
  }

  const cleanText = stripLeadingFiller(text
    .replace(jsonRe, '').replace(offerRe, '').replace(bookRe, '').replace(cancelRe, '').replace(reschedRe, '').replace(re, '')
    .replace(/\n{3,}/g, '\n\n').trim());
  return { cleanText, booking, handoff, offerSlots, bookConsult, cancelRequest, rescheduleRequest };
}

// Валидация карточки КЭВ. ok=false → тег не закрывает диалог, missing подмешается
// в следующий запрос Claude. Для легаси-формата day («слот») засчитывается как
// день+интервал. Телефон НЕ требуется (клиент пишет из WhatsApp, его номер у нас
// уже есть — handleBooking подставит из контакта). Возвращает нормализованный
// телефон, если клиент всё же его назвал (иначе '').
function validateBooking(b) {
  const missing = [];
  // Имя + фамилия: ждём минимум два слова (имя и фамилию). Одно слово — добираем
  // фамилию (мягко, как все недостающие поля), но НЕ блокируем намертво: если
  // клиент даёт только имя и больше ничего — это решает Claude по ходу диалога.
  const words = String(b.name || '').trim().split(/\s+/).filter(Boolean);
  if (!words.length) missing.push('имя и фамилия клиента');
  else if (words.length < 2) missing.push('фамилия клиента (есть только имя)');
  if (!b.service) missing.push('процедура/зона');
  if (b.legacy) {
    if (!b.day) missing.push('желаемый день и время');
  } else {
    if (!b.day) missing.push('желаемый день');
    if (!b.interval) missing.push('интервал времени (или пожелание клиента)');
  }
  if (!b.contraindications) missing.push('ответ по противопоказаниям (или «нет»)');
  return { ok: !missing.length, missing, phone: normalizePhone(b.phone) || '' };
}

// (УДАЛЕНО 05.06.2026) buildSlotsBlock / getAltegioSlots / buildTemplateSlots
// Бот больше не показывает свободные слоты — точное расписание клиенту не
// выдаёт. Функция бота: сбор заявки (имя/телефон/общее предпочтение) и
// передача менеджеру, который сам подберёт слот и оформит запись.

// ── Токен message.help (логин + кэш в KV) ──────────────────────────────────
// Токен живёт expires_in секунд; кэшируем с запасом 5 минут.
async function getMhToken(env, force) {
  if (!force) {
    const cached = await env.BOT_KV.get(TOKEN_KEY);
    if (cached) return cached;
  }
  let res;
  try {
    res = await fetch(`${MH_API}/app/user/login`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ login: env.MH_LOGIN, password: env.MH_PASSWORD }),
    });
  } catch (e) {
    console.error('mh login fetch error:', e && e.message);
    return null;
  }
  if (!res.ok) {
    console.error('mh login failed:', res.status);
    return null;
  }
  const data = await res.json().catch(() => null);
  const token = data && data.data && data.data.access_token;
  if (!token) {
    console.error('mh login: no access_token in response');
    return null;
  }
  const expires = (data.data.expires_in && parseInt(data.data.expires_in, 10)) || 3600;
  await env.BOT_KV.put(TOKEN_KEY, token, { expirationTtl: Math.max(60, expires - 300) });
  return token;
}

// ── Отправка ответа клиенту через message.help ─────────────────────────────
// send_message принимает multipart/form-data; destination=from_operator —
// сообщение уходит клиенту как ответ оператора.
// Возвращает true при успешной доставке, false — если доставить не удалось.
async function sendMessage(env, msg, text) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const token = await getMhToken(env, attempt > 0);  // на ретрае — свежий токен
    if (!token) {
      await sleep(500 * (attempt + 1));
      continue;
    }
    const url = `${MH_API}/app/projects/${env.MH_PROJECT_ID}`
      + `/channels/${msg.channelUuid}/send_message/${msg.userId}`;
    let res;
    try {
      const form = new FormData();
      form.append('text', text);
      form.append('destination', 'from_operator');
      res = await fetch(url, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: form,
      });
    } catch (e) {
      console.error('mh send error:', e && e.message);
      await sleep(500 * (attempt + 1));
      continue;
    }

    if (res.ok) {
      // Помечаем id своего сообщения — чтобы не среагировать на его эхо.
      const data = await res.json().catch(() => null);
      const sentId = data && data.data && data.data.id;
      if (sentId) {
        await env.BOT_KV.put(`sent:${sentId}`, '1', { expirationTtl: SENT_TTL });
      }
      return true;
    }
    if (res.status === 401) {
      // токен протух раньше TTL — сбросить кэш, на следующем attempt перелогин
      await env.BOT_KV.delete(TOKEN_KEY);
      continue;
    }
    if (res.status !== 429 && res.status < 500) {
      console.error(`mh send ${res.status}:`, (await res.text()).slice(0, 200));
      return false;
    }
    const retryAfter = parseInt(res.headers.get('retry-after') || '0', 10);
    await sleep(retryAfter ? retryAfter * 1000 : 600 * (attempt + 1));
  }
  console.error('mh send: retries exhausted');
  return false;
}

// ── Handoff и booking ──────────────────────────────────────────────────────
// Карточка сохраняется в KV, чат назначается менеджеру в message.help
// (updateOperator), бот в чате умолкает.

// Назначить чат закреплённому менеджеру в message.help (best-effort).
// Надёжная часть handoff (бот сказал «передаю», встал на паузу, карточка в KV)
// уже сделана — assignToManager лишь адресует чат конкретному оператору.
async function assignToManager(env, msg) {
  if (!env.MANAGER_OPERATOR_ID) return;
  try {
    const contactId = await getContactId(env, msg);
    if (!contactId) { console.error('assignToManager: contact_id не получен'); return; }
    const token = await getMhToken(env);
    if (!token) return;
    const res = await fetch(`${MH_API}/app/chat/updateOperator`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'content-type': 'application/json' },
      body: JSON.stringify({
        operator_id: Number(env.MANAGER_OPERATOR_ID),
        contact_id: contactId,
      }),
    });
    if (!res.ok) console.error('updateOperator:', res.status);
  } catch (e) {
    console.error('assignToManager error:', e && e.message);
  }
}

// contact_id message.help по user_id канала (через телефон + contact_by_phone).
async function getContactId(env, msg) {
  const phone = await getContactPhone(env, msg);
  if (!phone) return null;
  const token = await getMhToken(env);
  if (!token) return null;
  let res;
  try {
    res = await fetch(`${MH_API}/app/projects/${env.MH_PROJECT_ID}/contacts/contact_by_phone`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'content-type': 'application/json' },
      body: JSON.stringify({ phone, need_create: false }),
    });
  } catch (e) {
    console.error('contact_by_phone error:', e && e.message);
    return null;
  }
  if (!res.ok) { console.error('contact_by_phone:', res.status); return null; }
  const data = await res.json().catch(() => null);
  const c = (data && (data.data || data)) || {};
  const id = c.id || (c.contact && c.contact.id);
  return id ? Number(id) : null;
}

// Человекочитаемая причина handoff для карточки менеджеру.
function handoffReasonHuman(reason) {
  const map = {
    existing_client: 'действующий клиент (перенос/вопрос по визиту)',
    bot_unavailable: 'сбой ИИ — бот не смог ответить',
    'не клиентский запрос': 'не клиентский запрос (спам/партнёр/коллега)',
  };
  return map[reason] || reason || 'передача менеджеру';
}

async function handleHandoff(env, msg, reason) {
  const card = {
    type: 'handoff', reason,
    userId: msg.userId, channelId: msg.channelId,
    createdAt: new Date().toISOString(),
  };
  await env.BOT_KV.put(`handoff:${msg.userId}:${Date.now()}`, JSON.stringify(card),
    { expirationTtl: LEAD_TTL });
  // После handoff чат уходит человеку — бот в нём умолкает.
  if (msg.userId) {
    await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
  }
  await assignToManager(env, msg);

  // Мгновенная карточка менеджерам в Telegram (best-effort).
  let phone = null;
  try { phone = await getContactPhone(env, msg); } catch (_) { /* без телефона */ }
  await sendTelegramAlert(env, [
    `🟠 Бот передал диалог менеджеру · ${almatyHHMM()}`,
    `Клиент: ${phone ? fmtPhoneHuman(phone) : `чат №${msg.userId} (телефон не определился)`}`,
    `Причина: ${handoffReasonHuman(reason)}`,
    `Последнее сообщение: «${String(msg.text || '').slice(0, 160)}»`,
    'Подхватите диалог в message.help.',
  ].join('\n'));

  await bumpStat(env, 'handoff');                       // воронка: передача менеджеру
  console.log(`handoff saved u${msg.userId} reason=${reason}`);
}

async function handleBooking(env, msg, booking) {
  const nowMs = Date.now();
  const sla = kevSlaDeadline(env, nowMs);

  // Телефон у клиента НЕ спрашиваем (он пишет из WhatsApp — его номер уже у нас).
  // Берём wa_id из контакта message.help; если не достали, fallback на тот, что
  // клиент мог сам назвать в диалоге (booking.phone). Этот номер нужен менеджеру
  // в карточке и для сверки КЭВ↔Altegio в mm-pulse-bot.
  let phone = '';
  try { phone = normalizePhone(await getContactPhone(env, msg)) || ''; }
  catch (_) { /* без контакта */ }
  if (!phone && booking.phone) phone = normalizePhone(booking.phone) || '';
  booking.phone = phone;

  const card = {
    type: 'kev', ...booking,
    userId: msg.userId, channelId: msg.channelId,
    createdAt: new Date(nowMs).toISOString(),
    kevAt: nowMs,
    slaDeadline: sla.ms,
    slaLabel: sla.label,
    night: sla.night,
  };
  // lead: — старый контракт (читали отчёты), kev: — контракт для mm-pulse-bot
  // (сверка с Altegio по телефону, SLA-эскалации).
  await env.BOT_KV.put(`lead:${msg.userId}:${nowMs}`, JSON.stringify(card),
    { expirationTtl: LEAD_TTL });
  await env.BOT_KV.put(`kev:${msg.userId}:${nowMs}`, JSON.stringify(card),
    { expirationTtl: KEV_CARD_TTL });
  await bumpStat(env, 'kev');                           // воронка: договорённость о визите

  // КЭВ состоялся — но бот НЕ умолкает (раньше тут была op:-пауза на 7 дней, и
  // клиент, спросивший в 2 часа ночи «а парковка есть?», получал тишину).
  // kev_pending: бот отвечает на уточнения, повторных карточек не создаёт.
  // Полная op:-пауза — только при реальном входе человека (from_operator).
  await env.BOT_KV.put(`kev_pending:${msg.userId}`, JSON.stringify({
    kevAt: nowMs,
    service: booking.service, day: booking.day, interval: booking.interval,
  }), { expirationTtl: KEV_PENDING_TTL });
  await env.BOT_KV.delete(`kev_missing:${msg.userId}`);

  await assignToManager(env, msg);

  // Мгновенная карточка КЭВ менеджерам в Telegram + резюме диалога через Claude
  // (резюме best-effort: ИИ недоступен — карточка уходит без него).
  const summary = await buildKevSummary(env, msg.userId);
  const lines = [
    `🟢 КЭВ · ${sla.night ? 'ночной бот' : 'бот'} · ${almatyHHMM()}`,
    `${booking.name || '—'} · ${fmtPhoneHuman(booking.phone)}`,
    `${booking.service || '—'} · ${[booking.day, booking.interval].filter(Boolean).join(' ')}`,
    `Противопоказания: ${booking.contraindications || '—'} · язык: ${booking.lang || 'ru'}`
      + (booking.temp === 'hot' ? ' · 🔥 горячий' : ''),
  ];
  if (summary) lines.push(`📝 Резюме: ${summary}`);
  lines.push(`⏳ Оформить запись в Altegio ${sla.label}, в комментарий записи — маркер ${kevMarker(env)}`);
  await sendTelegramAlert(env, lines.join('\n'));

  console.log(`KEV saved u${msg.userId} name=${booking.name || '-'} temp=${booking.temp || '-'} night=${sla.night}`);
  // Бот в Altegio не пишет — запись оформляет менеджер по карточке КЭВ.
}

// ── ОТМЕНА ЗАПИСИ ПО ПРОСЬБЕ ──────────────────────────────────────────────────
// Шаг 1: клиент попросил отменить. Находим будущую запись, СЛОВАМИ предлагаем
// перенос или отмену, ставим cancel_pending (решение ловим на след. ходе кодом).
// НЕ отправляет сообщение сам — возвращает {clientText, handoff, found}; шлёт
// вызывающий (единый канал sendMessage + история).
async function handleCancelStart(env, msg, phone) {
  const tag = `u${msg.userId}`;
  phone = normalizePhone(phone) || String(phone || '').replace(/\D/g, '');
  if (!phone) {
    return { found: false, handoff: 'отмена: нет телефона',
      clientText: 'Поняла 🌷 Передаю администратору — он(а) поможет с вашей записью.' };
  }
  let rec = null;
  try { rec = await altegioFindCancelable(env, phone); }
  catch (e) { console.error('findCancelable:', e && e.message); }
  if (!rec) {
    console.log(`cancel: запись не найдена ${tag}`);
    return { found: false, handoff: 'отмена: запись не найдена',
      clientText: 'Не вижу активной записи на ваш номер 🌷 Передаю администратору — он(а) проверит и поможет.' };
  }
  const human = humanizeSlotDate(rec.ms, almatyNow());
  await env.BOT_KV.put(`cancel_pending:${msg.userId}`, JSON.stringify({
    recordId: rec.recordId, datetime: rec.datetime, ms: rec.ms,
    hhmm: rec.hhmm, human, service: rec.serviceTitle || '', phone, at: Date.now(),
    serviceId: rec.serviceId || '', staffId: rec.staffId || '', staffName: rec.staffName || '',
    clientName: rec.clientName || '',
  }), { expirationTtl: CANCEL_PENDING_TTL });
  await env.BOT_KV.delete(`cancel_reprompt:${msg.userId}`);
  await bumpStat(env, 'cancel_req');
  console.log(`cancel: предложен перенос/отмена ${tag} record=${rec.recordId}`);
  return { found: true,
    clientText: `Вижу вашу запись: ${human} в ${rec.hhmm}${rec.serviceTitle ? ` (${rec.serviceTitle})` : ''}. `
      + 'Жаль, если не получается 🌷 Перенести на другой удобный день — или всё-таки отменить?' };
}

// Шаг 2: клиент ответил «перенести / отменить / остаюсь». Удаление в Altegio —
// ТОЛЬКО при явном 'cancel'. Сам шлёт сообщения (вызывается из top-of-flow).
async function handleCancelDecision(env, msg, pending) {
  await env.BOT_KV.delete(`cancel_pending:${msg.userId}`);
  const decision = classifyCancelDecision(msg.text);

  if (decision === 'keep') {
    await env.BOT_KV.delete(`cancel_reprompt:${msg.userId}`);
    await sendMessage(env, msg, 'Отлично, ждём вас! 🌷');
    console.log(`cancel: клиент остаётся u${msg.userId}`);
    return;
  }

  if (decision === 'reschedule') {
    await env.BOT_KV.delete(`cancel_reprompt:${msg.userId}`);
    await bumpStat(env, 'reschedule_req');
    // Бот переносит САМ любую услугу (тот же мастер, реальные новые окна Altegio).
    // Нет окон / фича выключена → buildRescheduleStart вернёт handoff администратору.
    if (rescheduleByBotEnabled(env)) {
      const r = await buildRescheduleStart(env, msg, {
        oldRecordId: pending.recordId, phone: pending.phone, fullname: pending.clientName || '',
        serviceId: pending.serviceId, staffId: pending.staffId, staffName: pending.staffName,
        serviceTitle: pending.service,
        oldHuman: pending.human, oldHhmm: pending.hhmm, dayText: msg.text,
      });
      await sendMessage(env, msg, r.clientText);
      if (r.handoff && msg.userId) {
        await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
        await sendTelegramAlert(env, [
          `🔁 ПЕРЕНОС → администратору · ${almatyHHMM()}`,
          `${fmtPhoneHuman(pending.phone)} · запись ${pending.human} ${pending.hhmm}`,
          `Altegio record #${pending.recordId} · ${r.handoff}`,
        ].join('\n'));
      }
      console.log(`cancel→reschedule (бот) u${msg.userId} record=${pending.recordId}`);
      return;
    }
    await sendMessage(env, msg,
      'Хорошо 🌷 Передаю администратору — он(а) подберёт удобное время для переноса и свяжется с вами.');
    if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
    await sendTelegramAlert(env, [
      `🔁 ЗАПРОС ПЕРЕНОСА (бот выключен) · ${almatyHHMM()}`,
      `${fmtPhoneHuman(pending.phone)} · запись ${pending.human} ${pending.hhmm}`
        + `${pending.service ? ` · ${pending.service}` : ''}`,
      `Altegio record #${pending.recordId}`,
      'Клиент хочет ПЕРЕНОС — подберите время и переоформите в Altegio.',
    ].join('\n'));
    console.log(`cancel→reschedule handoff u${msg.userId} record=${pending.recordId}`);
    return;
  }

  if (decision === 'cancel') {
    await env.BOT_KV.delete(`cancel_reprompt:${msg.userId}`);
    let ok = false;
    try { ok = await altegioCancelRecord(env, pending.recordId, pending.phone); }
    catch (e) { console.error('cancelRecord:', e && e.message); }
    if (ok) {
      try { await env.BOT_KV.delete(`autobook_record:${pending.recordId}`); } catch (_) {}
      try { await env.BOT_KV.delete(`kev_pending:${msg.userId}`); } catch (_) {}
      await sendMessage(env, msg,
        'Запись отменена 🌷 Будем рады видеть вас снова — напишите, как будете готовы, подберём удобное время.');
      await sendTelegramAlert(env, [
        `🔴 АВТО-ОТМЕНА (бот) · ${almatyHHMM()}`,
        `${fmtPhoneHuman(pending.phone)} · была запись ${pending.human} ${pending.hhmm}`
          + `${pending.service ? ` · ${pending.service}` : ''}`,
        `Altegio record #${pending.recordId} отменён по просьбе клиента.`,
      ].join('\n'));
      await bumpStat(env, 'cancel_done');
      console.log(`CANCEL done u${msg.userId} record=${pending.recordId}`);
    } else {
      await sendMessage(env, msg,
        'Поняла 🌷 Передаю администратору — он(а) отменит запись и подтвердит.');
      if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
      await sendTelegramAlert(env, [
        `⚠️ ОТМЕНА не удалась — отмените вручную · ${almatyHHMM()}`,
        `${fmtPhoneHuman(pending.phone)} · запись ${pending.human} ${pending.hhmm}`,
        `Altegio record #${pending.recordId} — бот не смог удалить (проверьте).`,
      ].join('\n'));
      console.log(`CANCEL FAIL u${msg.userId} record=${pending.recordId}`);
    }
    return;
  }

  // Неоднозначно: один переспрос (re-arm pending), затем — менеджеру.
  if (await env.BOT_KV.get(`cancel_reprompt:${msg.userId}`)) {
    await env.BOT_KV.delete(`cancel_reprompt:${msg.userId}`);
    await sendMessage(env, msg, 'Передаю администратору — он(а) поможет с вашей записью 🌷');
    if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
    console.log(`cancel: неясно дважды → handoff u${msg.userId}`);
  } else {
    await env.BOT_KV.put(`cancel_reprompt:${msg.userId}`, '1', { expirationTtl: CANCEL_PENDING_TTL });
    await env.BOT_KV.put(`cancel_pending:${msg.userId}`, JSON.stringify(pending), { expirationTtl: CANCEL_PENDING_TTL });
    await sendMessage(env, msg, 'Подскажите, пожалуйста: перенести запись на другой день — или отменить?');
  }
}

// ── ПЕРЕНОС ЗАПИСИ ботом (только КОНСУЛЬТАЦИИ; процедуры → администратору) ──────
// Перенос = создать НОВУЮ запись на выбранный реальный слот + отменить старую.
// Транзакционно: сначала создаём новую, и ТОЛЬКО при успехе отменяем старую —
// иначе клиент не теряет запись. Время бот не выдумывает — только слоты Altegio.
function isConsultService(env, serviceId) {
  return String(serviceId || '') !== '' && String(serviceId) === String(env.ALTEGIO_CONSULT_SERVICE_ID || '');
}

// Парс выбора слота из ответа клиента: номер (1/2/3), словами (первый/второй…),
// или по названному времени («в 10:30»). Возвращает ref слота или null.
function parseSlotChoice(text, slots) {
  const t = String(text || '').toLowerCase();
  const has = (n) => slots.some((s) => String(s.ref) === String(n));
  const m = t.match(/\b([1-9])\b/);
  if (m && has(m[1])) return m[1];
  const words = [['перв', '1'], ['втор', '2'], ['трет', '3'], ['четверт', '4'], ['пят', '5']];
  for (const [w, n] of words) if (t.includes(w) && has(n)) return n;
  const tm = t.match(/\b(\d{1,2})[:.](\d{2})\b/);
  if (tm) {
    const hhmm = `${Number(tm[1])}:${tm[2]}`;
    const s = slots.find((x) => x.hhmm === hhmm);
    if (s) return s.ref;
  }
  return null;
}

// Старт переноса: день назван → показываем реальные окна (pending awaiting:'slot');
// не назван → спрашиваем день (awaiting:'day'); окон в горизонте нет → администратору.
// НЕ отправляет сам — возвращает {clientText, handoff}; шлёт вызывающий.
async function buildRescheduleStart(env, msg, ctx) {
  const now = almatyNow();
  const horizon = parseInt(env.AUTOBOOK_HORIZON_DAYS, 10) || AUTOBOOK_HORIZON_DEFAULT;
  const hasDay = resolveTargetDates(ctx.dayText, now, horizon).size > 0;
  if (!hasDay) {
    await env.BOT_KV.put(`reschedule_pending:${msg.userId}`,
      JSON.stringify({ ...ctx, awaiting: 'day', at: now.ms }), { expirationTtl: CANCEL_PENDING_TTL });
    return { clientText: 'На какой день удобно перенести? Подберу свободное время 🌷' };
  }
  // Окна ТОГО ЖЕ мастера по ТОЙ ЖЕ услуге, что в записи (для консультации
  // serviceId/staffId тоже из записи — поведение прежнее). Нет staffId → дефолт.
  const staffMap = ctx.staffId
    ? new Map([[String(ctx.staffId), ctx.staffName || `#${ctx.staffId}`]])
    : undefined;
  let slots = [];
  try { slots = await fetchConsultSlots(env, { dayHint: ctx.dayText, serviceId: ctx.serviceId, staffMap }); }
  catch (e) { console.error('reschedule slots:', e && e.message); }
  if (!slots.length) {
    await env.BOT_KV.delete(`reschedule_pending:${msg.userId}`);
    return { handoff: 'перенос: нет свободных окон',
      clientText: 'Свободных окон на ближайшие дни не нашла 🌷 Передаю администратору — подберёт время и перенесёт.' };
  }
  await env.BOT_KV.put(`reschedule_pending:${msg.userId}`,
    JSON.stringify({ ...ctx, awaiting: 'slot', slots, at: now.ms }), { expirationTtl: CANCEL_PENDING_TTL });
  const lines = slots.map((s) => `${s.ref}) ${s.humanDate} в ${s.hhmm}`);
  return { clientText: 'Вот свободное время для переноса:\n' + lines.join('\n')
    + `\n\nКакой вариант удобнее? Ответьте номером (${slots.map((s) => s.ref).join(', ')}).` };
}

// Перенос ботом активен? Токены Altegio есть + kill-switch (RESCHEDULE_BY_BOT≠0).
// 24/7 (в отличие от авто-записи): отвечаем на явную просьбу клиента в любое время.
function rescheduleByBotEnabled(env) {
  return String(env.RESCHEDULE_BY_BOT || '1') !== '0'
    && !!env.ALTEGIO_PARTNER_TOKEN && !!env.ALTEGIO_USER_TOKEN && !!env.ALTEGIO_COMPANY_ID;
}

// Вход по тегу [[RESCHEDULE_REQUEST]] / интенту переноса. Возвращает
// {clientText, handoff} — шлёт вызывающий. Бот переносит ЛЮБУЮ услугу сам
// (тот же мастер, реальные новые окна Altegio); нет окон/ошибка → администратору.
async function handleRescheduleStart(env, msg, phone) {
  phone = normalizePhone(phone) || String(phone || '').replace(/\D/g, '');
  if (!phone) {
    return { handoff: 'перенос: нет телефона',
      clientText: 'Поняла 🌷 Передаю администратору — поможет с переносом записи.' };
  }
  if (!rescheduleByBotEnabled(env)) {
    return { handoff: 'перенос записи (ручной)',
      clientText: 'Поняла 🌷 Передаю администратору — подберёт удобное время для переноса.' };
  }
  let rec = null;
  try { rec = await altegioFindCancelable(env, phone); }
  catch (e) { console.error('reschedule find:', e && e.message); }
  if (!rec) {
    return { handoff: 'перенос: запись не найдена',
      clientText: 'Не вижу активной записи на ваш номер 🌷 Передаю администратору — проверит и поможет.' };
  }
  await bumpStat(env, 'reschedule_req');
  // Переносим на ТУ ЖЕ услугу и к ТОМУ ЖЕ мастеру — берём окна именно его.
  return buildRescheduleStart(env, msg, {
    oldRecordId: rec.recordId, phone, fullname: rec.clientName || '',
    serviceId: rec.serviceId, staffId: rec.staffId, staffName: rec.staffName,
    serviceTitle: rec.serviceTitle,
    oldHuman: humanizeSlotDate(rec.ms, almatyNow()), oldHhmm: rec.hhmm, dayText: msg.text,
  });
}

// Ответ клиента в флоу переноса (день / номер слота). Шлёт свои сообщения сам.
async function handleRescheduleDecision(env, msg, pending) {
  const now = almatyNow();
  const horizon = parseInt(env.AUTOBOOK_HORIZON_DAYS, 10) || AUTOBOOK_HORIZON_DEFAULT;
  const reprompt = async (textMsg) => {
    if (await env.BOT_KV.get(`reschedule_reprompt:${msg.userId}`)) {
      await env.BOT_KV.delete(`reschedule_reprompt:${msg.userId}`);
      await env.BOT_KV.delete(`reschedule_pending:${msg.userId}`);
      await sendMessage(env, msg, 'Передаю администратору — поможет с переносом записи 🌷');
      if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
      return;
    }
    await env.BOT_KV.put(`reschedule_reprompt:${msg.userId}`, '1', { expirationTtl: CANCEL_PENDING_TTL });
    await sendMessage(env, msg, textMsg);
  };

  if (pending.awaiting === 'day') {
    if (!resolveTargetDates(msg.text, now, horizon).size) {
      await reprompt('Подскажите день — например «воскресенье», «завтра» или «28 июня» 🌷');
      return;
    }
    await env.BOT_KV.delete(`reschedule_reprompt:${msg.userId}`);
    const r = await buildRescheduleStart(env, msg, { ...pending, dayText: msg.text });
    await sendMessage(env, msg, r.clientText);
    if (r.handoff && msg.userId) {
      await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
      await sendTelegramAlert(env, [
        `🔁 ПЕРЕНОС → администратору · ${almatyHHMM()}`,
        `${fmtPhoneHuman(pending.phone)} · была запись ${pending.oldHuman} ${pending.oldHhmm}`,
        `Altegio record #${pending.oldRecordId} · ${r.handoff}`,
      ].join('\n'));
    }
    return;
  }

  // awaiting === 'slot'
  const slots = Array.isArray(pending.slots) ? pending.slots : [];
  const ref = parseSlotChoice(msg.text, slots);
  if (!ref) {
    const lines = slots.map((s) => `${s.ref}) ${s.humanDate} в ${s.hhmm}`);
    await reprompt('Уточните номер варианта:\n' + lines.join('\n'));
    return;
  }
  await env.BOT_KV.delete(`reschedule_reprompt:${msg.userId}`);
  await env.BOT_KV.delete(`reschedule_pending:${msg.userId}`);
  const slot = slots.find((s) => String(s.ref) === String(ref));
  await doReschedule(env, msg, pending, slot, now);
}

// Создаём новую запись на выбранный слот, при успехе отменяем старую.
async function doReschedule(env, msg, pending, slot, now) {
  const tag = `u${msg.userId}`;
  const phone = normalizePhone(pending.phone) || '';
  const ymd = ymdOfMs(slot.ms);
  const lockKey = `booking:${phone}:${ymd}`;
  if (phone && await env.BOT_KV.get(lockKey)) {
    await sendMessage(env, msg, 'Секунду, оформляю перенос… 🌷');
    return;
  }
  if (phone) await env.BOT_KV.put(lockKey, '1', { expirationTtl: AUTOBOOK_LOCK_TTL });

  // 1) Новая запись (приоритет — не потерять старую при сбое). Услуга/мастер — те
  // же, что в исходной записи (serviceId по умолчанию = консультация, если пусто).
  const recOpts = {
    phone, fullname: pending.fullname || '', datetime: slot.datetime,
    staffId: slot.staffId, userId: msg.userId, serviceId: pending.serviceId,
    comment: `Перенос записи через бота ${kevMarker(env)}`
      + (pending.serviceTitle ? ` · ${String(pending.serviceTitle).slice(0, 60)}` : ''),
  };
  let result = await createConsultRecord(env, recOpts);
  if (!result.ok && (result.networkError || (result.httpStatus >= 500))) {
    await sleep(1500);
    result = await createConsultRecord(env, recOpts);
  }
  if (!result.ok || !result.recordId) {
    if (phone) await env.BOT_KV.delete(lockKey);
    // СТАРУЮ запись НЕ трогаем — клиент не остаётся без записи.
    const rest = (Array.isArray(pending.slots) ? pending.slots : []).filter((s) => s.ref !== slot.ref);
    if (rest.length) {
      await env.BOT_KV.put(`reschedule_pending:${msg.userId}`,
        JSON.stringify({ ...pending, slots: rest, awaiting: 'slot', at: now.ms }), { expirationTtl: CANCEL_PENDING_TTL });
      const lines = rest.map((s) => `${s.ref}) ${s.humanDate} в ${s.hhmm}`);
      await sendMessage(env, msg, 'Это время только что заняли 🙈 Вот другие свободные:\n'
        + lines.join('\n') + '\n\nКакой подойдёт?');
      return;
    }
    await sendMessage(env, msg, 'Не получилось оформить перенос 🌷 Передаю администратору — '
      + 'подберёт время. Ваша текущая запись пока в силе.');
    if (msg.userId) await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
    await sendTelegramAlert(env, [
      `⚠️ ПЕРЕНОС не оформился · ${almatyHHMM()}`,
      `${fmtPhoneHuman(phone)} · СТАРАЯ запись #${pending.oldRecordId} (${pending.oldHuman} ${pending.oldHhmm}) В СИЛЕ`,
      'Бот не смог создать новую запись — подберите время вручную.',
    ].join('\n'));
    console.log(`RESCHEDULE create fail ${tag} old=${pending.oldRecordId}`);
    return;
  }

  // 2) Новая создана — отменяем СТАРУЮ.
  let cancelled = false;
  try { cancelled = await altegioCancelRecord(env, pending.oldRecordId, phone); }
  catch (e) { console.error('reschedule cancel old:', e && e.message); }
  try { await env.BOT_KV.delete(`autobook_record:${pending.oldRecordId}`); } catch (_) {}
  try { await env.BOT_KV.put(`autobook_record:${result.recordId}`, '1', { expirationTtl: 5 * 24 * 3600 }); } catch (_) {}
  if (phone) await env.BOT_KV.delete(lockKey);
  await bumpStat(env, 'reschedule_done');

  const newHuman = humanizeSlotDate(slot.ms, now);
  await sendMessage(env, msg, `Перенесла вашу запись на ${newHuman} в ${slot.hhmm} 🌷 Будем ждать!`);
  await sendTelegramAlert(env, [
    `🔁 ПЕРЕНОС (бот) · ${almatyHHMM()}`,
    `${fmtPhoneHuman(phone)} · было ${pending.oldHuman} ${pending.oldHhmm} → стало ${newHuman} ${slot.hhmm}`,
    `Altegio: новая #${result.recordId}`
      + (cancelled ? `, старая #${pending.oldRecordId} отменена`
        : `, ⚠️ старую #${pending.oldRecordId} НЕ удалось отменить — удалите вручную`),
  ].join('\n'));
  console.log(`RESCHEDULE done ${tag} old=${pending.oldRecordId} new=${result.recordId} cancelled=${cancelled}`);
}

// ════════════════════════════════════════════════════════════════════════════
// КЭВ: ИНФРАСТРУКТУРА — Telegram-карточки, SLA, резюме, утренний дайджест,
// дожим (WS-D), симуляция диалога (ops)
// ════════════════════════════════════════════════════════════════════════════

function kevMarker(env) {
  return String(env.KEV_MARKER || KEV_MARKER_DEFAULT);
}

// ── Telegram-уведомления менеджерам (группа «Отдел продаж М&М») ─────────────
// Best-effort: сбой Telegram НЕ должен ломать ответ клиенту или cron-джобу.
// Секреты TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID — те же, что у mm-pulse-bot.
async function sendTelegramAlert(env, text) {
  if (!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_CHAT_ID) {
    console.log('tg alert skipped: TELEGRAM_* не настроены');
    return false;
  }
  if (typeof text === 'string' && text.length > 4096) text = text.slice(0, 4090) + '…';
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch(
        `https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({
            chat_id: env.TELEGRAM_CHAT_ID,
            text,
            disable_web_page_preview: true,
          }),
        });
      if (res.ok) return true;
      console.error('tg alert:', res.status, (await res.text()).slice(0, 150));
      if (res.status !== 429 && res.status < 500) return false;
    } catch (e) {
      console.error('tg alert error:', e && e.message);
    }
    await sleep(700 * (attempt + 1));
  }
  return false;
}

// Личное сообщение управляющему (эскалация). chatId — Telegram ID из ADMIN_IDS.
async function sendTelegramDm(env, chatId, text) {
  if (!env.TELEGRAM_BOT_TOKEN || !chatId) return false;
  try {
    const res = await fetch(
      `https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ chat_id: chatId, text, disable_web_page_preview: true }),
      });
    return res.ok;
  } catch (e) {
    console.error('tg dm error:', e && e.message);
    return false;
  }
}

// +7 707 123-45-67 из 77071234567. В Telegram-карточках менеджерам телефон
// полный (рабочая необходимость); в ЛОГАХ — по-прежнему только maskPhone.
function fmtPhoneHuman(p) {
  const d = String(p || '').replace(/\D/g, '');
  if (d.length === 11 && d[0] === '7') {
    return `+7 ${d.slice(1, 4)} ${d.slice(4, 7)}-${d.slice(7, 9)}-${d.slice(9, 11)}`;
  }
  return d ? `+${d}` : '—';
}

function almatyHHMM() {
  const t = almatyNow();
  return `${String(t.hour).padStart(2, '0')}:${String(t.minute).padStart(2, '0')}`;
}

// Дедлайн SLA оформления записи по КЭВ.
// Ночь (KEV_NIGHT_START–KEV_NIGHT_END Almaty) → «до 10:30» ближайшего утра
// (env.KEV_NIGHT_DEADLINE); день → +KEV_SLA_DAY_MIN минут (env, по умолчанию 60).
// ВАЖНО: ночь считаем по KEV_NIGHT_*, а не по окну работы бота — бот с
// 12.06.2026 работает круглосуточно (BOT_HOUR_* = 0..24).
function kevSlaDeadline(env, kevMs) {
  const a = new Date(kevMs + ALMATY_UTC_OFFSET * 3600000);
  const hour = a.getUTCHours();
  const night = hour >= KEV_NIGHT_START || hour < KEV_NIGHT_END;
  if (night) {
    const m = String(env.KEV_NIGHT_DEADLINE || KEV_NIGHT_DEADLINE_DEFAULT)
      .match(/^(\d{1,2}):(\d{2})$/);
    const dh = m ? +m[1] : 10;
    const dm = m ? +m[2] : 30;
    // База — полночь Алматы дня КЭВ. После полуночи (00–07) дедлайн сегодня
    // утром; вечером (21–24) — завтра утром.
    const midnight = Date.UTC(a.getUTCFullYear(), a.getUTCMonth(), a.getUTCDate(), 0, 0, 0)
      - ALMATY_UTC_OFFSET * 3600000;
    const sameDay = midnight + (dh * 60 + dm) * 60000;
    const ms = hour < KEV_NIGHT_END ? sameDay : sameDay + 86400000;
    return { ms, label: `до ${String(dh).padStart(2, '0')}:${String(dm).padStart(2, '0')}`, night: true };
  }
  const slaMin = parseInt(env.KEV_SLA_DAY_MIN, 10) || KEV_SLA_DAY_MIN_DEFAULT;
  const ms = kevMs + slaMin * 60000;
  const dl = new Date(ms + ALMATY_UTC_OFFSET * 3600000);
  return {
    ms,
    label: `до ${String(dl.getUTCHours()).padStart(2, '0')}:${String(dl.getUTCMinutes()).padStart(2, '0')}`,
    night: false,
  };
}

// Лёгкий вызов Claude с произвольным системным промптом (резюме диалога и т.п.).
// 2 попытки, best-effort: при сбое возвращает '' — вызывающий обязан уметь без.
async function callClaudeLight(env, system, userText, maxTokens) {
  if (!env.ANTHROPIC_API_KEY) return '';
  const payload = {
    model: env.ANTHROPIC_MODEL || DEFAULT_MODEL,
    max_tokens: maxTokens || 300,
    temperature: 0.2,
    system,
    messages: [{ role: 'user', content: userText }],
  };
  for (let attempt = 0; attempt < 2; attempt++) {
    let res;
    try {
      res = await fetch(ANTHROPIC_URL, {
        method: 'POST',
        headers: {
          'x-api-key': env.ANTHROPIC_API_KEY,
          'anthropic-version': ANTHROPIC_VERSION,
          'content-type': 'application/json',
        },
        body: JSON.stringify(payload),
      });
    } catch (e) {
      console.error('claude light fetch:', e && e.message);
      await sleep(400 * (attempt + 1));
      continue;
    }
    if (res.ok) {
      const data = await res.json().catch(() => null);
      const block = data && (data.content || []).find((b) => b.type === 'text');
      return block ? block.text.trim() : '';
    }
    if (res.status !== 429 && res.status < 500) {
      console.error(`claude light ${res.status}`);
      return '';
    }
    await sleep(600 * (attempt + 1));
  }
  return '';
}

// Резюме диалога для карточки КЭВ: 2–4 строки «что хочет, что важно».
async function buildKevSummary(env, userId) {
  try {
    const hist = (await env.BOT_KV.get(`hist:${userId}`, { type: 'json' })) || [];
    if (!hist.length) return '';
    const transcript = hist.slice(-14).map((m) =>
      `${m.role === 'user' ? 'Клиент' : 'Алия'}: ${String(m.content).slice(0, 280)}`).join('\n');
    return await callClaudeLight(env,
      'Сожми диалог отдела продаж бьюти-студии в резюме для менеджера: 2-4 КОРОТКИЕ '
      + 'строки — что клиент хочет, что важно (срочность, сомнения, вопросы, нюансы). '
      + 'Без приветствий, без воды, без markdown. Только факты из диалога.',
      transcript, 250);
  } catch (e) {
    console.error('kev summary error:', e && e.message);
    return '';
  }
}

// ── Утренний дайджест ночных КЭВ (~08:30 Almaty) ────────────────────────────
// Одно сообщение в группу менеджеров: сколько КЭВ собрал бот за ночь и какие
// ещё не оформлены в Altegio. Окно 08:30–09:30 (Cloudflare cron не гарантирует
// минуту запуска — инцидент «48ч без подтверждений»), дедуп — KV-флаг дня.
async function runKevMorningDigest(env) {
  if (!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_CHAT_ID) return;
  const now = almatyNow();
  const inWindow = (now.hour === 8 && now.minute >= 30) || (now.hour === 9 && now.minute < 30);
  if (!inWindow) return;
  const guardKey = `kev_digest:${now.ymd}`;
  if (await env.BOT_KV.get(guardKey)) return;

  // «За ночь» = последние 13 часов (с ~19:30 вчера) — захватывает всё ночное
  // окно бота 21:00–07:00 плюс поздний вечер.
  const kevs = await listKevCards(env, now.ms - 13 * 3600000);
  if (!kevs.length) {
    console.log('kev digest: 0 КЭВ за ночь — молчим');
    await env.BOT_KV.put(guardKey, '1', { expirationTtl: 90000 });
    return;
  }

  // Сверка с Altegio: записи, СОЗДАННЫЕ вчера-сегодня, матчинг по телефону.
  let createdRecs = null;
  if (env.ALTEGIO_PARTNER_TOKEN && env.ALTEGIO_USER_TOKEN && env.ALTEGIO_COMPANY_ID) {
    try {
      createdRecs = await altegioFetchRecordsCreated(env, ymdDaysAhead(now, -1), now.ymd);
    } catch (e) {
      console.error('kev digest altegio:', e && e.message);
    }
  }
  const createdByPhone = new Map(); // phone → самый ранний create ts
  for (const r of createdRecs || []) {
    if (!r || r.deleted) continue;
    const ph = normalizePhone((r.client && r.client.phone) || '');
    if (!ph) continue;
    const p = parseAltegioParts(r.create_date);
    const ms = p ? partsToAlmatyMs(p) : null;
    if (ms == null) continue;
    if (!createdByPhone.has(ph) || ms < createdByPhone.get(ph)) createdByPhone.set(ph, ms);
  }

  const dd = `${now.ymd.slice(8, 10)}.${now.ymd.slice(5, 7)}`;
  const items = [];
  let waiting = 0;
  for (const k of kevs) {
    // Оформлен, если запись создана не раньше чем за 30 мин ДО КЭВ (допуск на
    // менеджера, успевшего оформить параллельно с диалогом).
    const done = createdRecs != null && createdByPhone.has(k.phone)
      && createdByPhone.get(k.phone) >= ((k.kevAt || 0) - 1800000);
    if (!done) waiting++;
    items.push(`${done ? '✅' : '⏳'} ${k.name || '—'} · ${fmtPhoneHuman(k.phone)} · `
      + `${k.service || '—'} · ${[k.day, k.interval].filter(Boolean).join(' ') || '—'}`);
  }

  const lines = [`🌅 Ночные КЭВ · ${dd}`];
  lines.push(createdRecs == null
    ? `За ночь ${kevs.length} КЭВ (Altegio недоступен — статус оформления не проверен):`
    : `За ночь ${kevs.length} КЭВ, ${waiting ? `${waiting} ждут оформления:` : 'все уже оформлены ✅'}`);
  lines.push(...items.slice(0, 15));
  if (items.length > 15) lines.push(`…и ещё ${items.length - 15}`);
  if (waiting) {
    lines.push('', `⏳ SLA: оформить до ${env.KEV_NIGHT_DEADLINE || KEV_NIGHT_DEADLINE_DEFAULT}`
      + ` с маркером ${kevMarker(env)} в комментарии записи.`);
  }
  // Гард дня — только ПОСЛЕ успешной отправки: при сбое Telegram следующий
  // тик окна (через 10 мин) попробует ещё раз.
  const sent = await sendTelegramAlert(env, lines.join('\n'));
  if (sent) await env.BOT_KV.put(guardKey, '1', { expirationTtl: 90000 });
  console.log(`kev digest ${sent ? 'sent' : 'FAILED'}: ${kevs.length} kev, ${waiting} waiting`);
}

// Карточки КЭВ из KV новее sinceMs. Ключ kev:{userId}:{ts} — ts фильтруем до
// чтения значения (дёшево). Курсор до 5 страниц по 1000 ключей.
async function listKevCards(env, sinceMs) {
  const out = [];
  let cursor;
  for (let i = 0; i < 5; i++) {
    const page = await env.BOT_KV.list({ prefix: 'kev:', limit: 1000, cursor });
    for (const k of page.keys) {
      const ts = Number(String(k.name).split(':')[2]);
      if (!Number.isFinite(ts) || ts < sinceMs) continue;
      const card = await env.BOT_KV.get(k.name, { type: 'json' });
      if (card && card.phone) out.push({ ...card, kevKey: k.name });
    }
    if (page.list_complete) break;
    cursor = page.cursor;
  }
  out.sort((a, b) => (a.kevAt || 0) - (b.kevAt || 0));
  return out;
}

// Записи Altegio, СОЗДАННЫЕ в диапазоне дат (c_start_date/c_end_date — по дате
// оформления, не визита). Для проверки «КЭВ → запись оформлена». Одна страница
// 200 записей: за 2 дня студия столько не оформляет.
async function altegioFetchRecordsCreated(env, startDate, endDate) {
  const url = `${ALTEGIO_API}/records/${env.ALTEGIO_COMPANY_ID}`
    + `?c_start_date=${startDate}&c_end_date=${endDate}&count=200`;
  const res = await fetch(url, { headers: altegioHeaders(env) });
  if (!res.ok) {
    console.error('altegio created records:', res.status);
    return null;
  }
  const data = await res.json().catch(() => null);
  return (data && data.data) || [];
}

// ── WS-D: дожим незавершённого КЭВ (фичефлаг env.KEV_NUDGE, по умолчанию ВЫКЛ) ──
// Клиент дошёл до согласия, но пропал, не дав часть данных (kev_missing висит,
// последний ход — бота). ОДНО касание через 3+ ч, только в «вежливые» часы
// (клиента не будим среди ночи). Только reply в существующий диалог через
// анти-бан конвейер mhSendByPhone (need_create=false, cold-фильтр, потолки
// канала) + отдельный потолок KEV_NUDGE_HOUR_MAX/час. Нет ответа — стоп.
async function runKevNudgeJob(env) {
  if (env.KEV_NUDGE !== '1') return;
  const now = almatyNow();
  // Вежливое окно дожима: 10:00–21:59 Almaty.
  if (now.hour < 10 || now.hour >= 22) return;

  const hourKey = `kev_nudge_hour:${now.ymdh}`;
  let sentThisHour = Number(await env.BOT_KV.get(hourKey)) || 0;
  if (sentThisHour >= KEV_NUDGE_HOUR_MAX) return;

  const page = await env.BOT_KV.list({ prefix: 'kev_missing:', limit: 100 });
  for (const k of page.keys) {
    if (sentThisHour >= KEV_NUDGE_HOUR_MAX) break;
    const userId = k.name.slice('kev_missing:'.length);
    if (!userId || userId.startsWith('sim_')) continue; // симуляции не дожимаем
    const data = await env.BOT_KV.get(k.name, { type: 'json' });
    if (!data || !data.at) continue;
    const ageH = (now.ms - data.at) / 3600000;
    if (ageH < KEV_NUDGE_MIN_AGE_H || ageH > KEV_NUDGE_MAX_AGE_H) continue;
    if (await env.BOT_KV.get(`kev_nudged:${userId}`)) continue;        // одно касание
    if (await env.BOT_KV.get(`op:${userId}`)) continue;                // чат у человека
    if (await env.BOT_KV.get(`kev_pending:${userId}`)) continue;       // КЭВ уже состоялся
    if (await env.BOT_KV.get(`confirm_pending:user:${userId}`)) continue;
    // Последний ход в истории — клиента? Значит диалог жив, бот ему ещё ответит.
    const hist = (await env.BOT_KV.get(`hist:${userId}`, { type: 'json' })) || [];
    if (!hist.length || hist[hist.length - 1].role === 'user') continue;

    const phone = await getContactPhone(env, {
      userId,
      channelUuid: data.channelUuid || resolveChannelUuid(env, data.channelId),
    });
    if (!phone) {
      await env.BOT_KV.put(`kev_nudged:${userId}`, 'no_phone', { expirationTtl: 604800 });
      continue;
    }

    const text = 'Я на связи 🌷 Если ещё актуально — напишите, когда вам удобнее '
      + '(день и время), и я передам заявку администратору: он подтвердит запись '
      + 'и пришлёт детали.';
    let sent = null;
    try {
      sent = await mhSendByPhone(env, normalizePhone(phone), text);
    } catch (e) {
      console.error('kev nudge send:', e && e.message);
    }
    if (sent && sent.ok) {
      sentThisHour++;
      await env.BOT_KV.put(hourKey, String(sentThisHour), { expirationTtl: 7200 });
      await env.BOT_KV.put(`kev_nudged:${userId}`, '1', { expirationTtl: 604800 });
      if (sent.channelId != null) {
        await incChannelHourCount(env, sent.channelId);
        await incChannelDayCount(env, sent.channelId);
      }
      console.log(`kev nudge sent u${userId}`);
      await sleep(5000);
    } else if (sent && (sent.reason === 'no_contact' || sent.reason === 'cold')) {
      // Перманентные отказы — больше не пробуем. Потолки (hour/day cap) —
      // транзиентные, попробуем в следующий тик.
      await env.BOT_KV.put(`kev_nudged:${userId}`, sent.reason, { expirationTtl: 604800 });
    }
  }
}

// ── Ops: симуляция диалога (golden-тесты промпта) ────────────────────────────
// Полный Claude-флоу на синтетическом пользователе sim_{id}: история в KV,
// служебные заметки, валидация BOOKING, kev_pending. НИЧЕГО не шлёт ни клиенту,
// ни в Telegram, карточек kev:/lead: не создаёт.
async function simulateDialog(env, simId, text, reset, forceAutobook) {
  const userId = `sim_${String(simId).replace(/[^\w-]/g, '')}`;
  const histKey = `hist:${userId}`;
  if (reset) {
    await env.BOT_KV.delete(histKey);
    await env.BOT_KV.delete(`kev_missing:${userId}`);
    await env.BOT_KV.delete(`kev_pending:${userId}`);
    if (!text) return { ok: true, reset: true, userId };
  }
  if (!text) return { ok: false, error: 'no_text' };

  let kevPending = null;
  const kevPendingRaw = await env.BOT_KV.get(`kev_pending:${userId}`);
  if (kevPendingRaw) { try { kevPending = JSON.parse(kevPendingRaw); } catch (_) { kevPending = {}; } }
  let kevMissing = null;
  if (!kevPending) {
    const kevMissingRaw = await env.BOT_KV.get(`kev_missing:${userId}`);
    if (kevMissingRaw) { try { kevMissing = JSON.parse(kevMissingRaw); } catch (_) { kevMissing = null; } }
  }

  const histBefore = (await env.BOT_KV.get(histKey, { type: 'json' })) || [];
  const contextHistory = appendTurn(histBefore, 'user', text);
  // forceAutobook (&ab=1) — для golden-теста эмиссии OFFER_SLOTS, когда allowlist
  // ещё пуст (в реале флаг = autobookEnabled).
  const abAvail = forceAutobook || autobookEnabled(env, almatyNow());
  const note = buildServiceNote(kevPending, kevMissing, abAvail, cancelEnabled(env),
    histBefore.length === 0);
  const reply = await callClaude(env, contextHistory, note);
  const parsed = reply ? parseControlTags(reply)
    : { cleanText: '', booking: null, handoff: null, offerSlots: null, bookConsult: null };

  // Авто-запись в симуляции НЕ исполняем (никаких записей в Altegio) — только
  // показываем, какие теги эмитил Claude (golden-тест промпта).
  let autobookSim = null;
  if (parsed.offerSlots || parsed.bookConsult) {
    autobookSim = {
      offerSlots: parsed.offerSlots || null,
      bookConsult: parsed.bookConsult || null,
      enabled: autobookEnabled(env, almatyNow()),
    };
  }

  let validation = null;
  let kevAccepted = false;
  let suppressed = false;
  if (parsed.booking && kevPending) {
    suppressed = true;
  } else if (parsed.booking) {
    validation = validateBooking(parsed.booking);
    if (validation.ok) {
      kevAccepted = true;
      await env.BOT_KV.put(`kev_pending:${userId}`, JSON.stringify({
        kevAt: Date.now(), service: parsed.booking.service,
        day: parsed.booking.day, interval: parsed.booking.interval,
      }), { expirationTtl: 1800 }); // в симуляции — короткий TTL
      await env.BOT_KV.delete(`kev_missing:${userId}`);
    } else {
      await env.BOT_KV.put(`kev_missing:${userId}`, JSON.stringify({
        missing: validation.missing, at: Date.now(),
      }), { expirationTtl: 1800 });
    }
  }

  let merged = appendTurn(histBefore, 'user', text);
  merged = appendTurn(merged, 'assistant', parsed.cleanText || reply || '(пусто)');
  await env.BOT_KV.put(histKey, JSON.stringify(merged.slice(-HISTORY_LIMIT)),
    { expirationTtl: 3600 });

  return {
    ok: true, userId,
    reply: parsed.cleanText || reply || '',
    booking: parsed.booking || null,
    handoff: parsed.handoff || null,
    autobook: autobookSim,
    cancelRequest: parsed.cancelRequest || false,
    rescheduleRequest: parsed.rescheduleRequest || false,
    validation, kevAccepted, suppressed,
    serviceNote: note || undefined,
  };
}

// ════════════════════════════════════════════════════════════════════════════
// НОЧНАЯ АВТО-ЗАПИСЬ НА КОНСУЛЬТАЦИЮ (Altegio book_record)
// LLM НИКОГДА не называет время — слоты из book_times, код фильтрует окно
// 10:00–20:00, предлагает реальные, клиент выбирает, код создаёт запись,
// подтверждение печатает реальное время из ответа Altegio.
// ════════════════════════════════════════════════════════════════════════════

// Ops: сырой список мастеров под услугу-консультацию из Altegio (book_staff) —
// владелец сверяет id/bookable, чтобы заполнить ALTEGIO_CONSULT_STAFF_IDS.
async function staffDump(env) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_COMPANY_ID
    || !env.ALTEGIO_CONSULT_SERVICE_ID) {
    return { ok: false, error: 'altegio not configured' };
  }
  const co = env.ALTEGIO_COMPANY_ID;
  const sid = encodeURIComponent(env.ALTEGIO_CONSULT_SERVICE_ID);
  let svcTitle = null;
  try {
    const sRes = await fetch(`${ALTEGIO_API}/company/${co}/services/${sid}`,
      { headers: altegioHeaders(env) });
    if (sRes.ok) { const j = await sRes.json().catch(() => null); svcTitle = j && j.data && j.data.title; }
  } catch (_) { /* best-effort */ }
  let staff = [];
  try {
    const res = await fetch(`${ALTEGIO_API}/book_staff/${co}?service_ids[]=${sid}`,
      { headers: { Authorization: `Bearer ${env.ALTEGIO_PARTNER_TOKEN}`, Accept: 'application/vnd.api.v2+json' } });
    if (res.ok) {
      const j = await res.json().catch(() => null);
      const arr = (j && j.data) || [];
      staff = (Array.isArray(arr) ? arr : []).map((s) => ({
        id: s.id, name: s.name, bookable: s.bookable,
      }));
    } else {
      return { ok: false, error: `book_staff ${res.status}` };
    }
  } catch (e) {
    return { ok: false, error: e && e.message };
  }
  return {
    ok: true,
    serviceId: env.ALTEGIO_CONSULT_SERVICE_ID,
    serviceTitle: svcTitle,
    staff,
    hint: 'Заполнить ALTEGIO_CONSULT_STAFF_IDS = {"<id>":"<имя>"} из bookable:true',
  };
}

// Allowlist мастеров-консультантов: Map staffId(String)→name. Пусто → авто-запись
// в фоллбэке (гейт). env.ALTEGIO_CONSULT_STAFF_IDS = JSON {"<id>":"Имя"}.
function parseConsultStaff(env) {
  const map = new Map();
  if (!env.ALTEGIO_CONSULT_STAFF_IDS) return map;
  try {
    const obj = JSON.parse(env.ALTEGIO_CONSULT_STAFF_IDS);
    for (const [id, name] of Object.entries(obj)) {
      const sid = String(id).replace(/\D/g, '');
      if (sid) map.set(sid, String(name || `#${sid}`));
    }
  } catch (e) {
    console.error('ALTEGIO_CONSULT_STAFF_IDS parse:', e && e.message);
  }
  return map;
}

// «Ночь» авто-записи (Almaty 21:00–08:59) — ЕДИНСТВЕННАЯ функция (блокер #8).
function isAutobookNight(now) {
  const h = (now || almatyNow()).hour;
  return h >= AUTOBOOK_NIGHT_START || h < AUTOBOOK_NIGHT_END;
}

// Авто-запись активна сейчас? kill-switch + конфигурация + время суток
// (ночь всегда; день — только при AUTOBOOK_DAY_MODE=on) + непустой allowlist.
function autobookEnabled(env, now) {
  if (env.NIGHT_AUTOBOOK !== '1') return false;
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_COMPANY_ID
    || !env.ALTEGIO_CONSULT_SERVICE_ID) return false;
  if (!parseConsultStaff(env).size) return false;
  if (env.AUTOBOOK_DAY_MODE === 'on') return true;
  return isAutobookNight(now || almatyNow());
}

// hh:mm → минуты от полуночи (null при ошибке).
function hmToMin(hm) {
  const m = String(hm || '').match(/^(\d{1,2}):(\d{2})$/);
  return m ? (+m[1]) * 60 + (+m[2]) : null;
}

// ymd (Almaty) по таймстампу.
function ymdOfMs(ms) {
  const d = new Date(ms + ALMATY_UTC_OFFSET * 3600000);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-`
    + `${String(d.getUTCDate()).padStart(2, '0')}`;
}

// ЕДИНСТВЕННЫЙ фильтр окна слота (блокер #8). datetime — ISO с +05:00 (локальное
// Almaty). Валиден, если HH:mm ∈ [START,END] И ∉ [FORBID_START,FORBID_END) И в
// будущем (> now+60с). Возвращает {ok, ms}.
function slotInWindow(env, datetimeISO, nowMs) {
  const parts = parseAltegioParts(datetimeISO);
  if (!parts) return { ok: false };
  const ms = partsToAlmatyMs(parts);
  if (!ms || ms < (nowMs || Date.now()) + 60000) return { ok: false }; // прошлое
  const min = parts.hour * 60 + parts.minute;
  const start = hmToMin(env.AUTOBOOK_START || AUTOBOOK_START_DEFAULT) ?? 600;
  const end = hmToMin(env.AUTOBOOK_END || AUTOBOOK_END_DEFAULT) ?? 1230;
  const fStart = hmToMin(env.AUTOBOOK_FORBID_START || AUTOBOOK_FORBID_START_DEFAULT) ?? 480;
  const fEnd = hmToMin(env.AUTOBOOK_FORBID_END || AUTOBOOK_FORBID_END_DEFAULT) ?? 600;
  if (min < start || min > end) return { ok: false };
  if (min >= fStart && min < fEnd) return { ok: false };
  return { ok: true, ms };
}

// Человеческая дата слота: «сегодня (пт 13.06)» / «завтра (сб 14.06)» / «(вс 15.06)».
function humanizeSlotDate(ms, now) {
  const d = new Date(ms + ALMATY_UTC_OFFSET * 3600000);
  const WD = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const ymd = ymdOfMs(ms);
  let prefix = '';
  if (ymd === now.ymd) prefix = 'сегодня ';
  else if (ymd === ymdDaysAhead(now, 1)) prefix = 'завтра ';
  return `${prefix}(${WD[d.getUTCDay()]} ${dd}.${mm})`;
}

// Реальные свободные слоты консультации по мастерам allowlist, отфильтрованные
// в окно. Возвращает [{ref, datetime, ms, staffId, staffName, hhmm, humanDate}]
// Разбор «дня» из пожелания клиента (day_hint): названия дней недели, сегодня/
// завтра/послезавтра, выходные, «28 июня»/«28.06» → набор ymd В ГОРИЗОНТЕ. Пусто —
// конкретный день не назван. Нужно, чтобы показать окна именно на запрошенный день.
function resolveTargetDates(dayHint, now, horizon) {
  const out = new Set();
  const h = String(dayHint || '').toLowerCase();
  if (!h) return out;
  const WD_STEM = ['воскрес', 'понедельник', 'вторник', 'сред', 'четверг', 'пятниц', 'суббот'];
  const MON_STEM = ['январ', 'феврал', 'март', 'апрел', 'мая', 'июн', 'июл', 'август', 'сентяб', 'октяб', 'нояб', 'декаб'];
  const baseWd = now.date.getUTCDay();
  for (let i = 0; i <= horizon; i++) {
    const ymd = ymdDaysAhead(now, i);
    const wd = (baseWd + i) % 7;
    const dd = Number(ymd.slice(8, 10));
    const mm = Number(ymd.slice(5, 7));
    let hit = false;
    if (i === 0 && /сегодня/.test(h)) hit = true;
    if (i === 1 && /завтра/.test(h) && !/послезавтра/.test(h)) hit = true;
    if (i === 2 && /послезавтра/.test(h)) hit = true;
    if (/выходн/.test(h) && (wd === 0 || wd === 6)) hit = true;
    if (h.includes(WD_STEM[wd])) hit = true;
    // «28 июня» или «28.06»
    if (new RegExp(`(^|\\D)${dd}(\\D|$)`).test(h)
      && (h.includes(MON_STEM[mm - 1]) || new RegExp(`\\b${dd}[.\\/]0?${mm}\\b`).test(h))) hit = true;
    if (hit) out.add(ymd);
  }
  return out;
}

// Окно ВРЕМЕНИ из пожелания клиента (day_hint): «после 15:00», «до 12», «вечером»,
// «утром», «днём/после обеда», «в 16:00» → {minMin, maxMin} в минутах от полуночи.
// null — ограничения по времени нет. Нужно, чтобы НЕ показывать утренние окна на
// «после 15:00» и уходить на другой день, если в это время на сегодня пусто.
function parseTimeWindow(dayHint) {
  const h = String(dayHint || '').toLowerCase();
  if (!h) return null;
  let minMin = null;
  let maxMin = null;
  let m = h.match(/(?:после|начиная\s*с|с)\s*(\d{1,2})(?:[:.](\d{2}))?\s*(?:ч|час|:00)?/);
  if (m && Number(m[1]) <= 23) minMin = Number(m[1]) * 60 + Number(m[2] || 0);
  m = h.match(/(?:до|раньше|пораньше|не\s*позже)\s*(\d{1,2})(?:[:.](\d{2}))?/);
  if (m && Number(m[1]) <= 23) maxMin = Number(m[1]) * 60 + Number(m[2] || 0);
  if (/вечер/.test(h)) minMin = Math.max(minMin == null ? 0 : minMin, 17 * 60);
  if (/утр|до\s*обед/.test(h)) maxMin = Math.min(maxMin == null ? 1440 : maxMin, 12 * 60);
  else if (/после\s*обед/.test(h)) minMin = Math.max(minMin == null ? 0 : minMin, 13 * 60);
  else if (/обед|днём|днем|\bдень\b/.test(h)) {
    if (minMin == null) minMin = 12 * 60;
    if (maxMin == null) maxMin = 17 * 60;
  }
  // явное «в 16:00» / «16:00» — окно того часа. ТОЛЬКО через двоеточие (16:00),
  // чтобы не спутать с датой через точку (16.06 = 16 июня, это день, не время).
  if (minMin == null && maxMin == null) {
    const me = h.match(/(\d{1,2}):(\d{2})/);
    if (me && Number(me[1]) <= 23) { const t = Number(me[1]) * 60 + Number(me[2]); minMin = t; maxMin = t + 60; }
  }
  if (minMin == null && maxMin == null) return null;
  return { minMin: minMin == null ? 0 : minMin, maxMin: maxMin == null ? 1440 : maxMin };
}

// (до maxOffers, сортировка по времени). dayHint: жёсткий фильтр по ВРЕМЕНИ
// (parseTimeWindow) + жёсткий приоритет конкретного ДНЯ (resolveTargetDates).
async function fetchConsultSlots(env, opts = {}) {
  // staffMap/serviceId переданы при ПЕРЕНОСЕ (мастер+услуга записи); по умолчанию —
  // консультанты + услуга «Консультация» (авто-запись КЭВ).
  const staff = opts.staffMap instanceof Map ? opts.staffMap : parseConsultStaff(env);
  if (!staff.size) return [];
  const co = env.ALTEGIO_COMPANY_ID;
  const sid = encodeURIComponent(opts.serviceId || env.ALTEGIO_CONSULT_SERVICE_ID);
  const horizon = parseInt(env.AUTOBOOK_HORIZON_DAYS, 10) || AUTOBOOK_HORIZON_DEFAULT;
  const maxOffers = parseInt(env.AUTOBOOK_MAX_OFFERS, 10) || AUTOBOOK_MAX_OFFERS_DEFAULT;
  const now = almatyNow();
  const allowedDates = new Set();
  for (let i = 0; i <= horizon; i++) allowedDates.add(ymdDaysAhead(now, i));

  const byDatetime = new Map(); // datetimeISO → {datetime, ms, staffId, hour}
  for (const [staffId] of staff) {
    let dates = [];
    try {
      const dRes = await fetch(
        `${ALTEGIO_API}/book_dates/${co}?service_ids[]=${sid}&staff_id=${staffId}`,
        { headers: altegioHeaders(env) });
      if (dRes.ok) {
        const dJson = await dRes.json().catch(() => null);
        const d = dJson && dJson.data;
        dates = (d && (d.booking_dates || d.working_dates)) || [];
      }
    } catch (e) { console.error('book_dates:', e && e.message); }
    if (!Array.isArray(dates)) dates = [];
    for (const date of dates) {
      if (!allowedDates.has(date)) continue;
      let times = [];
      try {
        const tRes = await fetch(
          `${ALTEGIO_API}/book_times/${co}/${staffId}/${date}?service_ids[]=${sid}`,
          { headers: altegioHeaders(env) });
        if (tRes.ok) {
          const tJson = await tRes.json().catch(() => null);
          times = (tJson && tJson.data) || [];
        }
      } catch (e) { console.error('book_times:', e && e.message); }
      for (const t of (Array.isArray(times) ? times : [])) {
        const dtISO = t && t.datetime;
        if (!dtISO || byDatetime.has(dtISO)) continue;
        const w = slotInWindow(env, dtISO, now.ms);
        if (!w.ok) continue;
        const p = parseAltegioParts(dtISO);
        byDatetime.set(dtISO, { datetime: dtISO, ms: w.ms, staffId, hour: p.hour });
      }
    }
  }

  let list = [...byDatetime.values()].sort((a, b) => a.ms - b.ms);
  // 1) ВРЕМЯ суток из day_hint («после 15:00», «вечером», «до обеда», «в 16:00») —
  // ЖЁСТКИЙ фильтр (а не мягкий буст, как было). Если в нужное время в горизонте
  // окон нет — list пустеет → handleOfferSlots уйдёт в фоллбэк; «не то время» не
  // показываем (клиент не получит снова утренние слоты на «после 15:00»).
  const tw = parseTimeWindow(opts.dayHint);
  if (tw) {
    list = list.filter((s) => {
      const p = parseAltegioParts(s.datetime) || { hour: s.hour, minute: 0 };
      const mm = p.hour * 60 + (p.minute || 0);
      return mm >= tw.minMin && mm < tw.maxMin;
    });
  }
  // 2) Конкретный ДЕНЬ из day_hint — приоритет: на запрошенный день в нужное время
  // ЕСТЬ окна → показываем ТОЛЬКО их; пусто → остаются слоты ДРУГИХ дней в это же
  // время (предложим другой свободный день — humanDate покажет дату).
  const targetDates = resolveTargetDates(opts.dayHint, now, horizon);
  if (targetDates.size) {
    const matched = list.filter((s) => targetDates.has(ymdOfMs(s.ms)));
    if (matched.length) list = matched;
  }
  return list.slice(0, maxOffers).map((s, i) => {
    const p = parseAltegioParts(s.datetime) || { hour: s.hour, minute: 0 };
    return {
      ref: String(i + 1),
      datetime: s.datetime,
      ms: s.ms,
      staffId: s.staffId,
      staffName: staff.get(s.staffId) || `#${s.staffId}`,
      hhmm: `${p.hour}:${String(p.minute).padStart(2, '0')}`,
      humanDate: humanizeSlotDate(s.ms, now),
    };
  });
}

// Создание записи на консультацию через book_record (только partner-токен).
// Возвращает {ok, recordId, recordHash} | {ok:false, errCode, httpStatus} |
// {ok:false, networkError:true}.
async function createConsultRecord(env, opts) {
  const co = env.ALTEGIO_COMPANY_ID;
  // serviceId по умолчанию — консультация (авто-запись КЭВ); при переносе
  // передаётся реальная услуга записи (любая процедура).
  const serviceId = Number(opts.serviceId || env.ALTEGIO_CONSULT_SERVICE_ID);
  const comment = opts.comment || `Запись через бота (КЭВ-консультация) ${kevMarker(env)}`;
  const body = {
    phone: opts.phone,
    fullname: opts.fullname,
    comment,
    api_id: `kev-${opts.userId}-${Date.now()}`,
    appointments: [{
      id: 1,
      staff_id: Number(opts.staffId),
      services: [serviceId],
      datetime: opts.datetime,
    }],
  };
  let res;
  try {
    res = await fetchWithTimeout(`${ALTEGIO_API}/book_record/${co}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${env.ALTEGIO_PARTNER_TOKEN}`,
        Accept: 'application/vnd.api.v2+json',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    }, 12000);
  } catch (e) {
    console.error('book_record network:', e && e.message);
    return { ok: false, networkError: true };
  }
  const data = await res.json().catch(() => null);
  if (res.ok) {
    const arr = (data && data.data) || [];
    const rec = Array.isArray(arr) ? arr[0] : arr;
    const recordId = rec && (rec.record_id || rec.id);
    if (recordId) return { ok: true, recordId, recordHash: rec.record_hash || rec.hash };
    console.error('book_record ok но без record_id:', JSON.stringify(data).slice(0, 200));
    return { ok: false, httpStatus: res.status, errCode: 0 };
  }
  const meta = (data && data.meta) || {};
  const errCode = Number(meta.code || (meta.errors && meta.errors.code)) || 0;
  console.error(`book_record ${res.status} code=${errCode}:`,
    JSON.stringify(meta).slice(0, 200));
  return { ok: false, httpStatus: res.status, errCode };
}

// Предпроверка дублей по ТЕЛЕФОНУ (блокер #2): есть ли активная запись на
// консультацию на дату ymd. Возвращает record (есть) | false (нет) | null (не
// смогли проверить — KV-lock остаётся основным щитом).
async function altegioHasConsultToday(env, phone, ymd) {
  try {
    const recs = await altegioFetchRecords(env, ymd, ymd);
    if (!Array.isArray(recs)) return null;
    const want = normalizePhone(phone);
    const svc = Number(env.ALTEGIO_CONSULT_SERVICE_ID);
    for (const r of recs) {
      if (!r || r.deleted || Number(r.attendance) === -1) continue;
      if (normalizePhone((r.client && r.client.phone) || '') !== want) continue;
      const ids = (r.services || []).map((s) => Number(s.id));
      if (ids.includes(svc)) return r;
    }
    return false;
  } catch (e) { console.error('hasConsultToday:', e && e.message); return null; }
}

// Вырезать паттерны времени из текста Claude (анти-галлюцинация, блокер #4.6):
// в ветке авто-записи время печатает ТОЛЬКО код.
function stripTimePatterns(text) {
  return String(text || '')
    .replace(/\b\d{1,2}[:.]\d{2}\b/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Срез слова-наполнителя в самом начале ответа («Понимаю —», «Конечно!», «Я понимаю,
// …») — детерминированная страховка к правилу БЕЗ ВОДЫ в промпте (LLM иногда
// проскакивает, особенно на возражениях). Режем ТОЛЬКО когда наполнитель стоит первым
// и отделён тире/точкой/!/…/двоеточием — или запятой, но НЕ перед придаточным
// «что/как/…» (там это цельное предложение, не наполнитель). Остаток капитализируем.
const LEADING_FILLERS = [
  'понимаю вас', 'понимаю тебя', 'я вас понимаю', 'я понимаю вас', 'я понимаю', 'понимаю',
  'конечно же', 'конечно', 'разумеется', 'безусловно', 'замечательно', 'прекрасно',
  'прекрасный выбор', 'отличный выбор', 'отлично', 'хорошо', 'понятно', 'согласна',
  'сейчас разберёмся', 'сейчас разберемся',
];
const FILLER_SUBORDINATE = /^(что|чтобы|как|какой|какая|какие|когда|где|кто|почему|зачем|насколько|если|раз|чем)(?![а-яёa-z])/i;
function stripLeadingFiller(text) {
  const t = String(text || '');
  const head = t.replace(/^\s+/, '');
  for (const f of LEADING_FILLERS) {
    const esc = f.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = head.match(new RegExp('^' + esc + '\\s*([—–\\-.!:…,]+)\\s*', 'i'));
    if (!m) continue;
    const sep = m[1];
    let rest = head.slice(m[0].length);
    // запятая перед придаточным — цельное предложение, не трогаем
    if (sep.indexOf(',') !== -1 && FILLER_SUBORDINATE.test(rest)) return text;
    if (rest.replace(/\s+/g, '').length < 3) return text; // нечего оставить
    return rest.charAt(0).toUpperCase() + rest.slice(1);
  }
  return text;
}

// Диспетчер авто-записи. Возвращает {handled, clientText, handoff, kevCard}.
// handled=false → теги были (но авто-запись недоступна), идём обычным КЭВ.
async function handleAutoBook(env, msg, parsed, kevPending, baseText) {
  const now = almatyNow();
  // BOOK_CONSULT приоритетнее (клиент выбрал) и НЕ гасится при kev_pending (#7).
  if (parsed.bookConsult) {
    return handleBookConsult(env, msg, parsed.bookConsult, baseText, now);
  }
  if (parsed.offerSlots) {
    if (!autobookEnabled(env, now)) return { handled: false };
    return handleOfferSlots(env, msg, parsed.offerSlots, baseText, now);
  }
  return { handled: false };
}

// ШАГ 1–4: гейты → слоты → предложение клиенту.
async function handleOfferSlots(env, msg, offer, baseText, now) {
  const tag = `u${msg.userId}`;
  // Имя+фамилия (≥2 слова): нет → не бронируем, добор обычным флоу.
  const words = String((offer && offer.name) || '').trim().split(/\s+/).filter(Boolean);
  if (words.length < 2) {
    console.log(`autobook: имя неполное, добор ${tag}`);
    return { handled: false };
  }
  // Телефон обязателен для book_record.
  let phone = '';
  try { phone = normalizePhone(await getContactPhone(env, msg)) || ''; }
  catch (_) { phone = ''; }
  if (!phone) {
    await sendTelegramAlert(env, [
      `⚠️ КЭВ БЕЗ ТЕЛЕФОНА — оформить вручную · ${almatyHHMM()}`,
      `${(offer && offer.name) || '—'} · чат №${msg.userId}`,
      'Клиент готов на консультацию, но телефон не определился — авто-запись невозможна.',
    ].join('\n'));
    return {
      handled: true,
      clientText: stripTimePatterns(baseText)
        || 'Готова записать вас на консультацию 🌷 Передаю администратору — он(а) свяжется и подберёт удобное время.',
      handoff: 'autobook: нет телефона',
    };
  }

  let slots = [];
  try { slots = await fetchConsultSlots(env, { dayHint: offer && offer.day_hint }); }
  catch (e) { console.error('fetchConsultSlots:', e && e.message); slots = []; }

  if (!slots.length) {
    console.log(`autobook: 0 слотов, фоллбэк ${tag}`);
    return {
      handled: true,
      clientText: stripTimePatterns(baseText)
        || 'Готова записать на консультацию 🌷 Администратор подберёт удобное время и подтвердит.',
      handoff: 'autobook: нет свободных слотов',
    };
  }

  await env.BOT_KV.put(`autobook_offer:${msg.userId}`, JSON.stringify({
    slots, name: offer.name, phone, at: now.ms,
  }), { expirationTtl: AUTOBOOK_OFFER_TTL });

  const lines = slots.map((s) => `${s.ref}) ${s.humanDate} в ${s.hhmm}`);
  const podvodka = stripTimePatterns(baseText);
  const offerText = (podvodka ? podvodka + '\n\n' : '')
    + 'Подобрала свободное время на бесплатную консультацию:\n'
    + lines.join('\n')
    + `\n\nКакой вариант удобнее? Ответьте номером (${slots.map((s) => s.ref).join(', ')}).`;
  console.log(`autobook: offered ${slots.length} ${tag}`);
  return { handled: true, clientText: offerText };
}

// ШАГ 5–9: бронь выбранного слота + подтверждение реальным временем + карточки.
async function handleBookConsult(env, msg, book, baseText, now) {
  const tag = `u${msg.userId}`;
  const offerRaw = await env.BOT_KV.get(`autobook_offer:${msg.userId}`);
  let offer = null;
  try { offer = offerRaw ? JSON.parse(offerRaw) : null; } catch (_) { offer = null; }

  // Offer истёк/пуст: если авто-запись активна — мягко переспрашиваем день/время
  // (на следующий ход Claude по истории заново эмитит OFFER_SLOTS с именем).
  if (!offer || !Array.isArray(offer.slots) || !offer.slots.length) {
    if (autobookEnabled(env, now)) {
      return {
        handled: true,
        clientText: 'Подскажите ещё раз, какой день и время вам удобны — '
          + 'и я подберу свободное окно для записи 🌷',
      };
    }
    return { handled: false };
  }

  const ref = String((book && book.slot_ref) || '').trim();
  let slot = offer.slots.find((s) => String(s.ref) === ref);
  // slot_ref не индекс (Claude вписал время текстом) → переспрос.
  if (!slot) {
    const lines = offer.slots.map((s) => `${s.ref}) ${s.humanDate} в ${s.hhmm}`);
    return {
      handled: true,
      clientText: 'Уточните, какой вариант — ответьте номером:\n' + lines.join('\n'),
    };
  }

  // Анти-повтор: этот клиент уже авто-записан ботом (autobook_done) — НЕ создаём
  // вторую бронь (фикс: ранее ключ писался, но не читался). Мягко подтверждаем.
  try {
    const done = await env.BOT_KV.list({ prefix: `autobook_done:${msg.userId}:`, limit: 1 });
    if (done && Array.isArray(done.keys) && done.keys.length) {
      console.log(`autobook: уже записан ранее (autobook_done) ${tag}`);
      return {
        handled: true,
        clientText: 'Вы уже записаны к нам на консультацию 🌷 Если нужно изменить день или время — напишите, передам администратору.',
      };
    }
  } catch (_) { /* list недоступен — ниже сработает altegioHasConsultToday */ }

  const phone = normalizePhone(offer.phone) || '';
  if (!phone) return { handled: false }; // не должно случиться (offer хранит phone)
  const fullname = String(offer.name || '').trim();
  const ymd = ymdOfMs(slot.ms);

  // Идемпотентность: KV-lock по телефону+дате (read-then-write).
  const lockKey = `booking:${phone}:${ymd}`;
  if (await env.BOT_KV.get(lockKey)) {
    console.log(`autobook: lock active ${tag}`);
    return { handled: true, clientText: 'Секунду, оформляю запись… 🌷' };
  }
  await env.BOT_KV.put(lockKey, '1', { expirationTtl: AUTOBOOK_LOCK_TTL });

  // Предпроверка дублей по телефону (блокер #2).
  const existing = await altegioHasConsultToday(env, phone, ymd);
  if (existing && existing.id) {
    console.log(`autobook: уже записан ${tag} record=${existing.id}`);
    return finalizeAutoBook(env, msg, {
      recordId: existing.id, staffId: slot.staffId, staffName: slot.staffName,
      datetime: existing.date || slot.datetime, ms: slot.ms, phone, fullname,
      reused: true, now,
    });
  }

  // Создание (ретрай только при network/5xx, перед ретраем — проверка дубля #6).
  let result = await createConsultRecord(env, {
    phone, fullname, datetime: slot.datetime, staffId: slot.staffId, userId: msg.userId,
  });
  if (!result.ok && (result.networkError || (result.httpStatus >= 500))) {
    const recheck = await altegioHasConsultToday(env, phone, ymd);
    if (recheck && recheck.id) {
      result = { ok: true, recordId: recheck.id };
    } else {
      await sleep(1500);
      result = await createConsultRecord(env, {
        phone, fullname, datetime: slot.datetime, staffId: slot.staffId, userId: msg.userId,
      });
    }
  }

  if (result.ok && result.recordId) {
    return finalizeAutoBook(env, msg, {
      recordId: result.recordId, staffId: slot.staffId, staffName: slot.staffName,
      datetime: slot.datetime, ms: slot.ms, phone, fullname, now,
    });
  }

  // Слот увели между показом и бронью (422 / 433 / 436) → переспрос из остатка.
  const slotTaken = result.httpStatus === 422
    || result.errCode === 433 || result.errCode === 436;
  await env.BOT_KV.delete(lockKey);
  if (slotTaken) {
    const rest = offer.slots.filter((s) => s.ref !== slot.ref);
    if (rest.length) {
      await env.BOT_KV.put(`autobook_offer:${msg.userId}`,
        JSON.stringify({ ...offer, slots: rest }), { expirationTtl: AUTOBOOK_OFFER_TTL });
      const lines = rest.map((s) => `${s.ref}) ${s.humanDate} в ${s.hhmm}`);
      return {
        handled: true,
        clientText: 'Это время только что заняли 🙈 Вот другие свободные:\n'
          + lines.join('\n') + '\n\nКакой подойдёт?',
      };
    }
    return {
      handled: true,
      clientText: 'Это время только что заняли 🙈 Передаю администратору — '
        + 'подберёт ближайшее свободное и подтвердит.',
      handoff: 'autobook: слот занят, нет альтернатив',
    };
  }

  // network/5xx исчерпаны → возможна повисшая запись (блокер #6): НЕ говорить
  // «записала», предупредить менеджера.
  if (result.networkError || result.httpStatus >= 500) {
    await sendTelegramAlert(env, [
      `⚠️ Возможна повисшая авто-запись — ПРОВЕРИТЬ ЖУРНАЛ · ${almatyHHMM()}`,
      `${fullname} · ${fmtPhoneHuman(phone)}`,
      `Консультация ${slot.humanDate} ${slot.hhmm}, мастер ${slot.staffName}`,
      'book_record не ответил после ретрая — запись могла создаться или нет. Сверьте Altegio.',
    ].join('\n'));
    return {
      handled: true,
      clientText: 'Передаю администратору — он(а) подтвердит запись утром 🌷',
      handoff: 'autobook: API не ответил, проверить журнал',
    };
  }

  // Прочие ошибки (438 услуга/434 ЧС/прочее) → фоллбэк на КЭВ + алерт.
  await sendTelegramAlert(env, [
    `⚠️ Авто-запись не удалась (код ${result.errCode || result.httpStatus}) · ${almatyHHMM()}`,
    `${fullname} · ${fmtPhoneHuman(phone)} · ${slot.humanDate} ${slot.hhmm}`,
    'Оформите запись вручную.',
  ].join('\n'));
  return {
    handled: true,
    clientText: 'Передаю администратору — он(а) подберёт время и подтвердит 🌷',
    handoff: `autobook: ошибка ${result.errCode || result.httpStatus}`,
  };
}

// ШАГ 8–9: запись создана → подтверждение клиенту реальным временем + карточки.
async function finalizeAutoBook(env, msg, d) {
  const ts = Date.now();
  // Реальное время из созданной записи (или из выбранного слота, что совпадает).
  const parts = parseAltegioParts(d.datetime) || {};
  const hhmm = `${parts.hour}:${String(parts.minute || 0).padStart(2, '0')}`;
  const human = humanizeSlotDate(d.ms, almatyNow());

  // Карточка КЭВ (контракт для pulse): source=autobook, услуга «Консультация».
  const card = {
    type: 'kev', source: 'autobook', status: 'auto-booked',
    name: d.fullname, phone: d.phone, service: 'Консультация',
    day: human, interval: hhmm,
    contraindications: '', lang: 'ru', temp: 'warm',
    recordId: d.recordId, staffId: d.staffId, staffName: d.staffName,
    datetimeISO: d.datetime,
    userId: msg.userId, channelId: msg.channelId,
    createdAt: new Date(ts).toISOString(), kevAt: ts,
  };
  await env.BOT_KV.put(`kev:${msg.userId}:${ts}`, JSON.stringify(card),
    { expirationTtl: KEV_CARD_TTL });
  await env.BOT_KV.put(`lead:${msg.userId}:${ts}`, JSON.stringify(card),
    { expirationTtl: LEAD_TTL });
  // Исключение из confirm-крона (блокер #1): бот сам подтвердил при записи.
  await env.BOT_KV.put(`autobook_record:${d.recordId}`, JSON.stringify({
    userId: msg.userId, phone: d.phone, at: ts,
  }), { expirationTtl: AUTOBOOK_RECORD_TTL });
  // Анти-повтор + kev_pending (бот не умолкает, повторно не записывает).
  await env.BOT_KV.put(`autobook_done:${msg.userId}:${d.recordId}`, '1',
    { expirationTtl: AUTOBOOK_DONE_TTL });
  await bumpStat(env, d.reused ? 'autobook_reused' : 'autobook_done');  // воронка: бот записал на консультацию
  await env.BOT_KV.put(`kev_pending:${msg.userId}`, JSON.stringify({
    kevAt: ts, service: 'Консультация', day: human, interval: hhmm, autobooked: true,
  }), { expirationTtl: KEV_PENDING_TTL });
  await env.BOT_KV.delete(`kev_missing:${msg.userId}`);
  await env.BOT_KV.delete(`autobook_offer:${msg.userId}`);

  // Telegram-карточка менеджерам (информирование, без действий).
  await sendTelegramAlert(env, [
    `🤖 АВТО-ЗАПИСЬ (бот) · ${almatyHHMM()}`,
    `${d.fullname} · ${fmtPhoneHuman(d.phone)}`,
    `Консультация · ${human} ${hhmm} · мастер ${d.staffName}`,
    `Altegio record #${d.recordId} · маркер ${kevMarker(env)}`,
  ].join('\n'));

  console.log(`autobook DONE u${msg.userId} record=${d.recordId} `
    + `staff=${d.staffId} ${human} ${hhmm}${d.reused ? ' (reused)' : ''}`);

  return {
    handled: true,
    clientText: `Записала вас на бесплатную консультацию: ${human} в ${hhmm}, `
      + `мастер ${d.staffName}.\nАдрес: Ауэзова 175Б, угол Габдуллина. `
      + 'Если планы изменятся — напишите, перенесём 🌷',
    autobooked: true,
  };
}

// ════════════════════════════════════════════════════════════════════════════
// ПОДТВЕРЖДЕНИЕ ЗАПИСЕЙ ЗА 24 ЧАСА
// Дневная функция: запускается cron'ом раз в 30 мин, в окне 09:00–20:59
// Almaty читает Altegio, шлёт клиенту скрипт-напоминание, ловит ответ
// «Да/Нет», ставит attendance=2 в Altegio (единственная write-операция).
// При «Нет» / уточняющем вопросе — передаёт менеджеру. Дедуп по record_id
// защищает от повторов даже если мастер перекинул клиента (id записи
// не меняется).
// ════════════════════════════════════════════════════════════════════════════

// Cron-job (вызывается каждые 30 минут из scheduled). Тонкий orchestrator —
// вся логика разнесена по helper'ам ниже для читаемости. Поток:
//   1. preflight — токены/секреты есть?
//   2. часовое окно (09:00–20:59 Almaty)?
//   3. fetch Altegio записей на завтра
//   4. collectConfirmCandidates — фильтры (attendance, окно 24-32ч, slot ≤ now…)
//   5. groupCandidatesByPhone — один клиент = одно сообщение со всеми слотами
//   6. processConfirmGroups — фактическая отправка с темпом, лимитами, дедупом
async function runConfirmationJob(env) {
  if (!confirmPreflightOk(env)) return;

  const now = almatyNow();
  if (now.hour < CONFIRM_HOUR_START || now.hour >= CONFIRM_HOUR_END) {
    console.log(`confirm: outside window (h=${now.hour}), skip`);
    return;
  }
  // Раньше тут был фильтр `now.minute !== 0 && now.minute !== 30 → return`
  // (для разнесения с broadcast'ом). Сломал работу: Cloudflare scheduled
  // не гарантирует точную минуту — приходит на :01 или :31, фильтр отбрасывал
  // всё подряд → 48 часов без единого confirmation. Удалён. Защита от
  // перерасхода идёт через hour-cap (4/час, для WA1 override 2/час).

  // Job-lock: один тик шлёт с паузами и живёт до ~9 мин. Не даём следующему
  // тику (или дублю запуска Cloudflare) наложиться и отправить напоминания
  // дважды (спам клиенту + риск бана). Лок самоистекает за 10 мин на случай
  // падения воркера; в норме снимаем в finally.
  const lockKey = 'confirm_tick_lock';
  if (await env.BOT_KV.get(lockKey)) {
    console.log('confirm: tick already running, skip');
    return;
  }
  await env.BOT_KV.put(lockKey, `${now.hour}:${now.minute}`, { expirationTtl: 600 });
  try {
    const tomorrowStr = ymdDaysAhead(now, 1);
    const records = await fetchTomorrowRecordsSafe(env, tomorrowStr);
    if (records === null) return;
    if (!records.length) {
      console.log(`confirm: no records for ${tomorrowStr}`);
      return;
    }

    const candidates = await collectConfirmCandidates(env, records, now);
    if (!candidates.length) {
      console.log(`confirm: ${records.length} tomorrow, 0 ready in this tick`);
      return;
    }

    const groups = groupCandidatesByPhone(candidates);
    shuffleInPlace(groups);

    const stats = await processConfirmGroups(env, groups, now.ymd);
    console.log(`confirm tick: ${records.length} tomorrow, ${candidates.length} cand, `
      + `${groups.length} groups, ${stats.ok} sent ${JSON.stringify(stats.channels)}, `
      + `${stats.dedup} dedup, ${stats.phoneDup} phone-day-dup, `
      + `${stats.cold} cold, ${stats.cap} cap`);
    // Метка «только что слали авто-подтверждения» — рассылка разнесётся по времени
    // (runBroadcastJob пропускает тик, если метка свежее 2 мин).
    if (stats.ok > 0) {
      try { await env.BOT_KV.put('last_confirm_send', String(Date.now()), { expirationTtl: 900 }); }
      catch (_) { /* не критично */ }
    }
  } finally {
    try { await env.BOT_KV.delete(lockKey); } catch (_) { /* истечёт по TTL */ }
  }
}

// ── FOLLOW-UP ПОСЛЕ КОНСУЛЬТАЦИИ (две ветки) ─────────────────────────────────
// Кто СЕГОДНЯ пришёл на консультацию (Altegio attendance==1 у услуги
// ALTEGIO_CONSULT_SERVICE_ID) делится на ДВЕ непересекающиеся группы по тому,
// взял ли клиент процедуру:
//   • НЕ взял («ушёл думать») → в ТОТ ЖЕ день в CONSULT_FU_THINK_HOUR (20:00)
//     тёплый дожим, средний тон (забота + мягкий CTA подобрать время).
//   • ВЗЯЛ процедуру (сделал в тот же день ИЛИ записался на будущее) →
//     на СЛЕДУЮЩИЙ день в CONSULT_FU_CARE_HOUR (12:00): сделал → «как
//     самочувствие?»; записался → «спасибо, ждём вас <дата>».
// Конверсия определяется по записям клиента в Altegio (рабочий records-запрос,
// НЕ сломанный clients/search). Анти-бан — общий mhSendByPhone (cold + потолки).
// Дедуп per-record: consult_fu_think:{id} / consult_fu_care:{id} (взаимоисключающие).
// Kill-switch CONSULT_FOLLOWUP_ACTIVE='1'.
const CONSULT_FU_DEDUP_TTL = 3 * 24 * 3600;  // 3 дня — не слать повторно
const CONSULT_FU_TICK_MAX = 6;               // потолок отправок за один tick
const CONSULT_FU_PROC_HORIZON_DEFAULT = 14;  // на сколько дней вперёд искать запись на процедуру

const RU_MONTHS = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
  'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
// «2026-06-15» → «15 июня» (для фразы «ждём вас …»).
function humanDateRu(ymd) {
  const m = String(ymd || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return '';
  return `${Number(m[3])} ${RU_MONTHS[Number(m[2]) - 1] || ''}`.trim();
}
// Название процедуры (первый НЕ-консультационный сервис записи) — опц. для текста.
function procName(services, consultSvcId) {
  const svc = String(consultSvcId || '');
  for (const s of services || []) {
    if (String(s.id) !== svc && s.title) return String(s.title);
  }
  return '';
}

// Имя для обращения: обычно первое слово, но если оно похоже на фамилию
// («Арсланова Сабина») — берём второе.
function firstName(full) {
  const p = String(full || '').trim().split(/\s+/).filter(Boolean);
  if (!p.length) return '';
  if (p.length >= 2 && /(ова|ева|ёва|ина|ына|ская|цкая|ов|ёв|ев|ин|ын|ский|цкий|енко|ко|швили|дзе|оглы|кызы|улы)$/i.test(p[0])) return p[1];
  return p[0];
}

// Постранично собрать записи окна (records count=200, до maxPages страниц) —
// окно follow-up шире одного дня (день консультации + горизонт процедур).
async function altegioFetchRecordsPaged(env, start, end, maxPages = 5) {
  const out = [];
  for (let page = 1; page <= maxPages; page++) {
    const url = `${ALTEGIO_API}/records/${env.ALTEGIO_COMPANY_ID}`
      + `?start_date=${start}&end_date=${end}&count=200&page=${page}`;
    let res;
    try { res = await fetch(url, { headers: altegioHeaders(env) }); }
    catch (e) { console.error('records paged fetch:', e && e.message); break; }
    if (!res.ok) { console.error('records paged:', res.status); break; }
    const data = await res.json().catch(() => null);
    const list = (data && data.data) || [];
    if (!Array.isArray(list) || !list.length) break;
    out.push(...list);
    if (list.length < 200) break;
  }
  return out;
}

// Пришедшие на консультацию (att==1) за конкретный день ymd. Один телефон —
// один кандидат. Возвращает [{recordId, phone, phoneTail, name}].
function collectConsultAttendees(env, records, ymd) {
  const svc = String(env.ALTEGIO_CONSULT_SERVICE_ID || '');
  const seen = new Set();
  const out = [];
  for (const r of records || []) {
    if (!r || r.deleted) continue;
    if (Number(r.attendance) !== 1) continue;            // 1 = пришёл (−1 = не пришёл, 2 = подтвердил)
    if (String(r.date || r.datetime || '').slice(0, 10) !== ymd) continue;
    if (!(r.services || []).some((s) => String(s.id) === svc)) continue;
    const c = r.client || {};
    const phone = normalizePhone(c.phone || c.surname_with_phone || r.client_phone || '');
    if (!phone) continue;
    const tail = phone.replace(/\D/g, '').slice(-10);
    if (seen.has(tail)) continue;
    seen.add(tail);
    out.push({ recordId: r.id, phone, phoneTail: tail, name: firstName(c.name) });
  }
  return out;
}

// Взял ли клиент процедуру (НЕ консультацию) на/после дня консультации.
//   null                              — не взял («ушёл думать»)
//   {mode:'done', serviceName}        — сделал процедуру в день консультации
//   {mode:'booked', day, serviceName} — записан на процедуру (сегодня позже/вперёд)
function clientProcedureStatus(env, windowRecords, phoneTail, consultYmd) {
  const svc = String(env.ALTEGIO_CONSULT_SERVICE_ID || '');
  let done = null, booked = null;
  for (const r of windowRecords || []) {
    if (!r || r.deleted) continue;
    const cph = String((r.client && r.client.phone) || '').replace(/\D/g, '').slice(-10);
    if (cph !== phoneTail) continue;
    const services = r.services || [];
    if (!services.length) continue;
    if (!services.some((s) => String(s.id) !== svc)) continue;   // только консультация — не процедура
    const att = Number(r.attendance);
    if (att === -1) continue;                                    // не пришёл — не считаем
    const day = String(r.date || r.datetime || '').slice(0, 10);
    if (!day) continue;
    if (day === consultYmd && att === 1) {
      if (!done) done = { mode: 'done', serviceName: procName(services, svc) };
    } else if (day >= consultYmd) {
      if (!booked || day < booked.day) booked = { mode: 'booked', day, serviceName: procName(services, svc) };
    }
  }
  return done || booked || null;
}

// ── Тексты follow-up ─────────────────────────────────────────────────────────
// A) Ушёл думать — забота + мягкий CTA подобрать время (текст владельца).
// На консультации мастер всегда составляет индивидуальный план — упоминание
// плана корректно для каждого пришедшего на консультацию.
function buildThinkFollowupText(name) {
  const hi = name ? `${name}, спасибо` : 'Спасибо';
  return `${hi}, что были сегодня у нас на консультации в Фабрике красивых тел M&M 🌸\n\n`
    + 'Мастер составил для вас индивидуальный план под вашу цель. Если остались вопросы по '
    + 'программе или стоимости — с радостью отвечу. Хотите, подберу удобное время для первой '
    + 'процедуры? 🤍';
}
// B1) Сделал процедуру в день консультации — пост-уход.
function buildPostCareText(name) {
  const hi = name ? `${name}, здравствуйте` : 'Здравствуйте';
  return `${hi}! 🌸 Как ваше самочувствие после вчерашней процедуры в Фабрике красивых тел M&M? `
    + 'Если есть вопросы по уходу или ощущениям — пишите, подскажу. Будем рады видеть вас снова 🤍';
}
// B2) Записался на процедуру вперёд — благодарность + ждём.
function buildBookedThanksText(name, dayYmd) {
  const hi = name ? `${name}, спасибо` : 'Спасибо';
  const d = humanDateRu(dayYmd);
  const when = d ? ` Будем рады видеть вас ${d}.` : ' Будем рады видеть вас снова.';
  return `${hi}, что выбрали Фабрику красивых тел M&M! 🌸${when} `
    + 'Если появятся вопросы по подготовке к процедуре — просто напишите, всё подскажу 🤍';
}

// Отправка одного follow-up с дедупом и учётом потолков канала.
async function consultFuSend(env, cand, text, dedupKey, counters) {
  if (await env.BOT_KV.get(dedupKey)) { counters.dedup++; return; }
  let res = null;
  try { res = await mhSendByPhone(env, cand.phone, text); }
  catch (e) { console.error('consultfu send:', e && e.message); }
  if (res && res.ok) {
    await env.BOT_KV.put(dedupKey, new Date().toISOString(), { expirationTtl: CONSULT_FU_DEDUP_TTL });
    if (res.channelId != null) {
      await incChannelHourCount(env, res.channelId);
      await incChannelDayCount(env, res.channelId);
    }
    counters.sent++;
  } else {
    // cold / нет WA-контакта — повтор не поможет, гасим дедупом; cap — оставим на след. tick
    if (res && (res.reason === 'cold' || res.reason === 'no_contact')) {
      await env.BOT_KV.put(dedupKey, `skip:${res.reason}`, { expirationTtl: CONSULT_FU_DEDUP_TTL });
    }
    counters.skip++;
  }
}

async function runConsultFollowupJob(env) {
  if (env.CONSULT_FOLLOWUP_ACTIVE !== '1') return;
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN
    || !env.ALTEGIO_COMPANY_ID || !env.ALTEGIO_CONSULT_SERVICE_ID) return;
  const now = almatyNow();
  const thinkHour = Number(env.CONSULT_FU_THINK_HOUR) || 20;
  const careHour = Number(env.CONSULT_FU_CARE_HOUR) || 12;
  if (now.hour === thinkHour) await runConsultThinkTrack(env, now);
  else if (now.hour === careHour) await runConsultCareTrack(env, now);
}

// Ветка A — тот же день: пришёл на консультацию сегодня и НЕ взял процедуру.
async function runConsultThinkTrack(env, now) {
  const horizon = Number(env.CONSULT_FU_PROC_HORIZON_DAYS) || CONSULT_FU_PROC_HORIZON_DEFAULT;
  const win = await altegioFetchRecordsPaged(env, now.ymd, ymdDaysAhead(now, horizon));
  if (!win.length) return;
  const attendees = collectConsultAttendees(env, win, now.ymd);
  if (!attendees.length) { console.log('consultfu/think: 0 пришедших'); return; }
  const c8 = { sent: 0, dedup: 0, skip: 0, proc: 0 };
  for (const c of attendees) {
    if (c8.sent >= CONSULT_FU_TICK_MAX) break;
    if (clientProcedureStatus(env, win, c.phoneTail, now.ymd)) { c8.proc++; continue; }  // взял процедуру → ветка B завтра
    await consultFuSend(env, c, buildThinkFollowupText(c.name), `consult_fu_think:${c.recordId}`, c8);
  }
  console.log(`consultfu/think: ${attendees.length} att, ${c8.proc} с процедурой, `
    + `${c8.sent} sent, ${c8.dedup} dedup, ${c8.skip} skip`);
}

// Ветка B — следующий день: был на консультации вчера и ВЗЯЛ процедуру.
async function runConsultCareTrack(env, now) {
  const horizon = Number(env.CONSULT_FU_PROC_HORIZON_DAYS) || CONSULT_FU_PROC_HORIZON_DEFAULT;
  const yYmd = ymdDaysAhead(now, -1);
  const win = await altegioFetchRecordsPaged(env, yYmd, ymdDaysAhead(now, horizon));
  if (!win.length) return;
  const attendees = collectConsultAttendees(env, win, yYmd);
  if (!attendees.length) { console.log('consultfu/care: 0 вчерашних'); return; }
  const c8 = { sent: 0, dedup: 0, skip: 0, think: 0, none: 0 };
  for (const c of attendees) {
    if (c8.sent >= CONSULT_FU_TICK_MAX) break;
    // Уже получил вчерашний дожим (поздно записался) — второй раз не трогаем.
    if (await env.BOT_KV.get(`consult_fu_think:${c.recordId}`)) { c8.think++; continue; }
    const st = clientProcedureStatus(env, win, c.phoneTail, yYmd);
    if (!st) { c8.none++; continue; }                                // не взял процедуру — это была ветка A
    const text = st.mode === 'done' ? buildPostCareText(c.name) : buildBookedThanksText(c.name, st.day);
    await consultFuSend(env, c, text, `consult_fu_care:${c.recordId}`, c8);
  }
  console.log(`consultfu/care: ${attendees.length} att, ${c8.sent} sent, ${c8.dedup} dedup, `
    + `${c8.think} think-skip, ${c8.none} no-proc, ${c8.skip} skip`);
}

// Dry-run для ops-эндпоинта ?consultfutest — кто в какую ветку попадёт + тексты,
// БЕЗ отправки. Телефоны маскируются.
async function consultFollowupDryRun(env) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN
    || !env.ALTEGIO_COMPANY_ID || !env.ALTEGIO_CONSULT_SERVICE_ID) {
    return { ok: false, error: 'altegio_not_configured' };
  }
  const now = almatyNow();
  const horizon = Number(env.CONSULT_FU_PROC_HORIZON_DAYS) || CONSULT_FU_PROC_HORIZON_DEFAULT;
  const thinkHour = Number(env.CONSULT_FU_THINK_HOUR) || 20;
  const careHour = Number(env.CONSULT_FU_CARE_HOUR) || 12;
  const yYmd = ymdDaysAhead(now, -1);
  const winA = await altegioFetchRecordsPaged(env, now.ymd, ymdDaysAhead(now, horizon));
  const todayThink = collectConsultAttendees(env, winA, now.ymd).map((c) => {
    const st = clientProcedureStatus(env, winA, c.phoneTail, now.ymd);
    return st
      ? { name: c.name, phone: maskPhone(c.phone), bucket: 'процедура→ветка B (молчим сегодня)', mode: st.mode, when: st.day || now.ymd }
      : { name: c.name, phone: maskPhone(c.phone), bucket: 'дожим «ушёл думать»', text: buildThinkFollowupText(c.name) };
  });
  const winB = await altegioFetchRecordsPaged(env, yYmd, ymdDaysAhead(now, horizon));
  const yesterdayCare = collectConsultAttendees(env, winB, yYmd).map((c) => {
    const st = clientProcedureStatus(env, winB, c.phoneTail, yYmd);
    if (!st) return { name: c.name, phone: maskPhone(c.phone), bucket: 'без процедуры (дожим был вчера)' };
    const text = st.mode === 'done' ? buildPostCareText(c.name) : buildBookedThanksText(c.name, st.day);
    return { name: c.name, phone: maskPhone(c.phone), bucket: st.mode === 'done' ? 'пост-уход' : 'спасибо/ждём', when: st.day || yYmd, text };
  });
  return {
    ok: true,
    active: env.CONSULT_FOLLOWUP_ACTIVE === '1',
    now: `${now.ymd} ${String(now.hour).padStart(2, '0')}:${String(now.minute).padStart(2, '0')}`,
    schedule: { think: `${thinkHour}:00 в день консультации`, care: `${careHour}:00 на следующий день` },
    today_think: todayThink,
    yesterday_care: yesterdayCare,
  };
}

// Pre-flight проверки конфигурации для confirmation job.
function confirmPreflightOk(env) {
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN
    || !env.ALTEGIO_COMPANY_ID) {
    console.log('confirm: altegio not configured, skip');
    return false;
  }
  if (!env.MH_LOGIN || !env.MH_PASSWORD || !env.MH_PROJECT_ID) {
    console.log('confirm: message.help not configured, skip');
    return false;
  }
  return true;
}

// YYYY-MM-DD в Almaty через N дней от текущей даты.
function ymdDaysAhead(now, days) {
  const t = new Date(now.date.getTime() + days * 86400000);
  return `${t.getUTCFullYear()}-`
    + `${String(t.getUTCMonth() + 1).padStart(2, '0')}-`
    + `${String(t.getUTCDate()).padStart(2, '0')}`;
}

// Обёртка над altegioFetchRecords с дружелюбной обработкой ошибки.
// Возвращает массив записей или null (при ошибке fetch).
async function fetchTomorrowRecordsSafe(env, tomorrowStr) {
  try {
    const recs = await altegioFetchRecords(env, tomorrowStr, tomorrowStr);
    return Array.isArray(recs) ? recs : [];
  } catch (e) {
    console.error('confirm: altegio fetch failed:', e && e.message);
    return null;
  }
}

// Фильтры по записям. Возвращает массив {record, phone, parts, dedupKey, slotMs}
// готовых к отправке. Сбрасывает записи в прошлом, без телефона, со статусом
// уже отработанным, вне окна 18-30ч до визита, со слотом в будущем.
async function collectConfirmCandidates(env, records, now) {
  // Сегодняшние границы Almaty для clamp слота: 09:00 и CONFIRM_LATE_FALLBACK_H
  const todayCalUtcMs = Date.UTC(now.year, now.month - 1, now.day, 0, 0, 0)
    - ALMATY_UTC_OFFSET * 3600000;
  const today09Ms = todayCalUtcMs + CONFIRM_HOUR_START * 3600000;
  const todayLateMs = todayCalUtcMs + CONFIRM_LATE_FALLBACK_H * 3600000;

  const out = [];
  for (const r of records) {
    if (Number(r.attendance) !== 0) continue; // уже отработана
    if (r.deleted) continue;
    // Блокер #1: авто-запись бота создаётся с attendance=0 и бот уже отправил
    // клиенту подтверждение при записи. confirm-крон НЕ должен слать повторное
    // «Вы записаны» — пропускаем записи с пометкой autobook_record:{id}.
    if (await env.BOT_KV.get(`autobook_record:${r.id}`)) {
      continue;
    }
    // Поле `confirmed` в этом кабинете Altegio проставляется автоматически у
    // ВСЕХ записей при создании — не используем как сигнал. Признак ответа
    // клиента — только attendance=2.

    const rawPhone = (r.client && (r.client.phone || r.client.surname_with_phone))
      || r.client_phone || '';
    const phone = normalizePhone(rawPhone);
    if (!phone) continue;
    if (isInternalPhone(env, phone)) continue;   // внутренний номер (менеджер) — не напоминаем

    const parts = parseAltegioParts(r.date || r.datetime);
    if (!parts) continue;
    const apptMs = partsToAlmatyMs(parts);
    if (!apptMs || apptMs < now.ms + 60000) continue; // запись в прошлом — мимо

    // ОКНО ОТПРАВКИ: 30ч ≥ время-до-визита ≥ 18ч.
    // Расширено по запросу владельца (16.06.2026: нижняя 20→18ч) — гибкое 18–30ч окно.
    // < 18ч — слишком близко к визиту, помечаем late_notice (менеджер вручную).
    // > 30ч — ещё рано, ждём следующих cron-тиков.
    const apptToNow = apptMs - now.ms;
    if (apptToNow > 30 * 3600000) continue;
    if (apptToNow < 18 * 3600000) {
      const noticeKey = `confirm_late_notice:${r.id}`;
      if (!(await env.BOT_KV.get(noticeKey))) {
        console.log(`confirm: skip rec ${r.id} — appt ${r.date} осталось `
          + `<18h до визита, менеджер обзвонит вручную`);
        await env.BOT_KV.put(noticeKey, '1', { expirationTtl: CONFIRM_DEDUP_TTL });
        // Карточка менеджерам: бот напоминание уже не отправит (политика
        // «отмена за 24ч» не успевает) — подтвердить запись нужно вручную.
        await sendTelegramAlert(env, [
          `⏰ Запись без авто-напоминания · ${almatyHHMM()}`,
          `${(r.client && r.client.name) ? r.client.name + ' · ' : ''}${fmtPhoneHuman(phone)}`,
          `Визит: ${r.date} (осталось ~${Math.round(apptToNow / 3600000)} ч)`,
          'Бот напоминание не отправит (<18ч до визита) — подтвердите запись звонком.',
        ].join('\n'));
      }
      continue;
    }

    // Идеальный слот = appt-25ч (на 1ч раньше политики), ограничен [09:00, 20:00].
    // 25ч вместо 24ч: cron `*/10` срабатывает с задержкой 0-10 мин, а при
    // slot=appt-24h slotMs совпадает с временем суток визита и фактически
    // никогда не «созревал» к нужному тику — 0 отправок за 14 дней.
    // -25h даёт 1h буфер: slot созревает на час раньше, фактический gap
    // send→appt остаётся ≥ 24ч (политика отмены студии не нарушается).
    const idealMs = apptMs - 25 * 3600000;
    let slotMs;
    if (idealMs < today09Ms) slotMs = today09Ms;
    else if (idealMs > todayLateMs) slotMs = todayLateMs;
    else slotMs = idealMs;

    if (slotMs > now.ms + 60000) continue; // слот ещё впереди — следующий tick

    out.push({
      record: r, phone, parts,
      dedupKey: `confirm_sent:${r.id}`,
      slotMs,
    });
  }
  return out;
}

// Группировка кандидатов: один клиент → одно сообщение со всеми слотами дня.
// `slotMs` группы = минимум по входящим (раньше всех «созревает»). Записи
// внутри группы сортируются по времени визита для красивого отображения.
function groupCandidatesByPhone(candidates) {
  const byPhone = new Map();
  for (const c of candidates) {
    if (!byPhone.has(c.phone)) byPhone.set(c.phone, []);
    byPhone.get(c.phone).push(c);
  }
  const groups = [];
  for (const [phone, list] of byPhone.entries()) {
    list.sort((a, b) => partsToAlmatyMs(a.parts) - partsToAlmatyMs(b.parts));
    groups.push({
      phone,
      partsList: list.map((c) => c.parts),
      recordIds: list.map((c) => c.record.id),
      dedupKeys: list.map((c) => c.dedupKey),
      slotMs: Math.min(...list.map((c) => c.slotMs)),
      firstRecord: list[0].record,
    });
  }
  return groups;
}

// Основной цикл отправки. Идёт по перетасованным группам, проверяет каждый
// слой защиты (per-record дедуп, per-phone-day, часовой/дневной потолок,
// холодные), шлёт и инкрементит счётчики. Возвращает агрегированную
// статистику для общего лога tick.
async function processConfirmGroups(env, groups, todayStr) {
  const stats = {
    ok: 0, dedup: 0, phoneDup: 0, cold: 0, cap: 0,
    channels: [],
  };

  for (const g of groups) {
    if (stats.ok >= CONFIRM_TICK_MAX) break;

    // Per-record дедуп — если хотя бы одна запись группы уже шла, skip всей
    if (await anyKeyExists(env, g.dedupKeys)) { stats.dedup++; continue; }

    // Per-phone-per-day дедуп — один номер не получает > 1 сообщения в сутки
    const phoneDayKey = `confirm_phone_day:${g.phone}:${todayStr}`;
    if (await env.BOT_KV.get(phoneDayKey)) { stats.phoneDup++; continue; }

    const r = g.firstRecord;
    // 3 шаблона текста с ротацией record_id mod 3 — точно по правилу
    // message.help «1–3 шаблона текста на рассылку».
    const variant = Math.abs(Number(r.id) || 0) % 3;
    const text = buildConfirmationText(g.partsList, variant);

    let sent = null;
    try {
      sent = await mhSendByPhone(env, g.phone, text);
    } catch (e) {
      console.error('confirm send error:', e && e.message);
    }

    if (!sent || !sent.ok) {
      if (sent && sent.reason === 'cold') stats.cold++;
      else if (sent && (sent.reason === 'hour_cap'
        || sent.reason === 'day_cap')) stats.cap++;
      continue;
    }

    stats.ok++;
    stats.channels.push(sent.channelId || '?');
    await markGroupSent(env, g, phoneDayKey, sent);
    await persistPending(env, g, r, sent);

    // Темп 90..150 сек между сообщениями
    if (stats.ok < CONFIRM_TICK_MAX) {
      await sleep(CONFIRM_TICK_PAUSE_MIN
        + Math.floor(Math.random()
          * (CONFIRM_TICK_PAUSE_MAX - CONFIRM_TICK_PAUSE_MIN)));
    }
  }

  return stats;
}

// True, если хотя бы один ключ из массива есть в KV.
async function anyKeyExists(env, keys) {
  for (const k of keys) {
    if (await env.BOT_KV.get(k)) return true;
  }
  return false;
}

// Помечает в KV ВСЕ записи группы как «отправлено» + per-phone-day отметку.
// Инкрементит часовой и дневной счётчики канала.
async function markGroupSent(env, g, phoneDayKey, sent) {
  const payload = JSON.stringify({
    recordIds: g.recordIds, phone: g.phone,
    sentAt: new Date().toISOString(), channelId: sent.channelId,
  });
  for (const k of g.dedupKeys) {
    await env.BOT_KV.put(k, payload, { expirationTtl: CONFIRM_DEDUP_TTL });
  }
  await env.BOT_KV.put(phoneDayKey, payload,
    { expirationTtl: CONFIRM_DEDUP_TTL });
  if (sent.channelId != null) {
    await incChannelHourCount(env, sent.channelId);
    await incChannelDayCount(env, sent.channelId);
  }
}

// Сохраняет pending для ответа клиента «Да/Нет/уточняющий вопрос». Бот
// перехватит следующее входящее сообщение пользователя и направит в
// handleConfirmationResponse / handleConfirmationFollowUp.
async function persistPending(env, g, firstRecord, sent) {
  if (!sent.userId) return;
  const ap = parseAltegioParts(firstRecord.date || firstRecord.datetime);
  await env.BOT_KV.put(`confirm_pending:user:${sent.userId}`, JSON.stringify({
    recordId: firstRecord.id,
    recordIds: g.recordIds,
    phone: g.phone,
    channelUuid: sent.channelUuid,
    apptMin: ap ? ap.hour * 60 + ap.minute : null, // время брони (мин от полуночи) — для допуска опоздания
    apptDate: firstRecord.date || firstRecord.datetime, // день брони — для сравнения с названным днём (перенос vs «завтра же»)
  }), { expirationTtl: CONFIRM_PENDING_TTL });
}

// Часовой счётчик исходящих на канал — для CONFIRM_PER_CHANNEL_HOURLY_MAX.
function channelHourKey(channelId) {
  return `confirm_hour:${channelId}:${almatyNow().ymdh}`;
}

async function getChannelHourCount(env, channelId) {
  const v = await env.BOT_KV.get(channelHourKey(channelId));
  return Number(v) || 0;
}

async function incChannelHourCount(env, channelId) {
  const key = channelHourKey(channelId);
  const cur = Number(await env.BOT_KV.get(key)) || 0;
  await env.BOT_KV.put(key, String(cur + 1),
    { expirationTtl: CONFIRM_HOUR_COUNTER_TTL });
}

// Дневной счётчик исходящих на канал — глобальная страховка под лимит
// message.help «не более 300/день на номер».
function channelDayKey(channelId) {
  return `confirm_day:${channelId}:${almatyNow().ymd}`;
}

async function getChannelDayCount(env, channelId) {
  const v = await env.BOT_KV.get(channelDayKey(channelId));
  return Number(v) || 0;
}

async function incChannelDayCount(env, channelId) {
  const key = channelDayKey(channelId);
  const cur = Number(await env.BOT_KV.get(key)) || 0;
  await env.BOT_KV.put(key, String(cur + 1),
    { expirationTtl: CONFIRM_DAY_COUNTER_TTL });
}

// Эффективный часовой потолок для канала: дефолт CONFIRM_PER_CHANNEL_HOURLY_MAX,
// но env.MH_CHANNEL_HOURLY_OVERRIDE (JSON {"channelId": N}) может задать
// меньшее значение для конкретного канала (например для свежеподключенного
// номера, на который Meta смотрит особенно строго).
function resolveChannelHourCap(env, channelId) {
  if (env.MH_CHANNEL_HOURLY_OVERRIDE) {
    try {
      const map = JSON.parse(env.MH_CHANNEL_HOURLY_OVERRIDE);
      const v = map[String(channelId)] || map[channelId];
      if (Number.isFinite(Number(v))) {
        return Math.min(CONFIRM_PER_CHANNEL_HOURLY_MAX, Number(v));
      }
    } catch (e) {
      console.error('MH_CHANNEL_HOURLY_OVERRIDE parse error:', e && e.message);
    }
  }
  return CONFIRM_PER_CHANNEL_HOURLY_MAX;
}

// ── Altegio: чтение записей и обновление attendance ────────────────────────

async function altegioFetchRecords(env, startDate, endDate) {
  const url = `${ALTEGIO_API}/records/${env.ALTEGIO_COMPANY_ID}`
    + `?start_date=${startDate}&end_date=${endDate}&count=200`;
  const res = await fetch(url, { headers: altegioHeaders(env) });
  if (!res.ok) {
    console.error('altegio records:', res.status, (await res.text()).slice(0, 200));
    return null;
  }
  const data = await res.json().catch(() => null);
  return (data && data.data) || [];
}

async function altegioFetchRecord(env, recordId) {
  const url = `${ALTEGIO_API}/record/${env.ALTEGIO_COMPANY_ID}/${recordId}`;
  const res = await fetch(url, { headers: altegioHeaders(env) });
  if (!res.ok) {
    console.error('altegio record get:', res.status);
    return null;
  }
  const data = await res.json().catch(() => null);
  return (data && data.data) || null;
}

// Бот в Altegio пишет ТОЛЬКО одно поле — attendance=2 (клиент подтвердил).
// Безопасно: читаем запись, ставим attendance=2 и шлём PUT с полями, которые
// API требует обязательными.
async function markAttendanceConfirmed(env, recordId) {
  const rec = await altegioFetchRecord(env, recordId);
  if (!rec) return false;
  // Идемпотентность + НЕ затираем действие человека: уже подтверждён (2) или
  // клиент пришёл (1) → ничего не пишем; «не пришёл» (-1) или запись удалена →
  // не перезаписываем вслепую (мог поставить менеджер), отдаём как неуспех.
  if (rec.deleted) { console.log(`attendance skip: record ${recordId} deleted`); return false; }
  const curAtt = Number(rec.attendance);
  if (curAtt === 2 || curAtt === 1) { console.log(`attendance noop: record ${recordId} att=${curAtt}`); return true; }
  if (curAtt === -1) { console.log(`attendance skip: record ${recordId} no-show by human`); return false; }
  const body = {
    staff_id: rec.staff_id || (rec.staff && rec.staff.id) || null,
    datetime: rec.date || rec.datetime,
    seance_length: rec.length || rec.seance_length || 3600,
    services: Array.isArray(rec.services) ? rec.services.map((s) => ({
      id: s.id,
      cost: s.cost,
      first_cost: s.first_cost,
      discount: s.discount,
    })) : [],
    client: rec.client ? {
      id: rec.client.id,
      phone: rec.client.phone,
      name: rec.client.name,
    } : null,
    attendance: 2,
    comment: rec.comment || '',
  };
  const url = `${ALTEGIO_API}/record/${env.ALTEGIO_COMPANY_ID}/${recordId}`;
  const res = await fetchWithTimeout(url, {
    method: 'PUT', headers: altegioHeaders(env), body: JSON.stringify(body),
  }, 12000);
  if (!res.ok) {
    console.error('altegio attendance PUT:', res.status,
      (await res.text()).slice(0, 300));
    return false;
  }
  return true;
}

// ── message.help: отправка по телефону ─────────────────────────────────────
// Резолвит контакт в message.help по номеру и шлёт сообщение СТРОГО через
// тот канал, через который клиент уже писал нам. Возвращает
// {ok, channelUuid, userId}.
// Важно — не наводим шума:
//   • НЕ создаём нового контакта в message.help (need_create=false);
//   • НЕ открываем новый канал клиенту, который никогда нам не писал;
//   • НЕ шлём через канал, которого нет в MH_CHANNELS (например в DM
//     Instagram, если клиент когда-то писал туда). Чужие каналы — мимо.

async function mhSendByPhone(env, phone, text) {
  const token = await getMhToken(env);
  if (!token) return { ok: false };

  // Map id→uuid наших обслуживаемых каналов (WhatsApp 1, WhatsApp 2, …)
  const channelMap = parseKnownChannelMap(env);
  if (!channelMap.size) {
    console.error('confirm: MH_CHANNELS empty, cannot resolve known channels');
    return { ok: false };
  }

  // Резолв БЕЗ создания. Если контакта нет ИЛИ ни одна связка не на наших
  // каналах (только Instagram, например) — шлём в никуда нельзя, пропускаем.
  const resolved = await mhResolveContact(env, token, phone, false, channelMap);
  if (!resolved) {
    console.log(`confirm: no usable WA contact for ${maskPhone(phone)}, skip`);
    return { ok: false, reason: 'no_contact' };
  }

  // Анти-бан #1: «холодные» контакты — клиент не писал нам ≥ CONFIRM_COLD_DAYS.
  // Шлём первым автомат-сообщением «с того света» = риск спам-сигнала и плохой
  // клиентский опыт. Пропускаем — лучше менеджер позвонит.
  if (resolved.lastMessageAt) {
    const last = parseAltegioParts(resolved.lastMessageAt);
    const lastMs = last ? partsToAlmatyMs(last) : null;
    if (lastMs && (Date.now() - lastMs) > CONFIRM_COLD_DAYS * 86400000) {
      console.log(`confirm: cold contact ${maskPhone(phone)} `
        + `(last ${resolved.lastMessageAt}, ch ${resolved.channelId}), skip`);
      return { ok: false, reason: 'cold' };
    }
  }

  // Анти-бан #2: жёсткий часовой потолок на канал. По умолчанию
  // CONFIRM_PER_CHANNEL_HOURLY_MAX, но для конкретного канала можно задать
  // более строгий лимит через env-переменную MH_CHANNEL_HOURLY_OVERRIDE
  // (например {"17222": 2} — спец-режим на 24ч после реактивации номера).
  if (resolved.channelId != null) {
    const used = await getChannelHourCount(env, resolved.channelId);
    const cap = resolveChannelHourCap(env, resolved.channelId);
    if (used >= cap) {
      console.log(`confirm: hour-cap ${resolved.channelId} (${used}/${cap}), `
        + `skip ${maskPhone(phone)}`);
      return { ok: false, reason: 'hour_cap' };
    }
  }

  // Анти-бан #3: ДНЕВНОЙ потолок на канал. Глобальная страховка под
  // официальную рекомендацию message.help «не более 300 в день на номер»;
  // у нас лимит CONFIRM_PER_CHANNEL_DAILY_MAX (=200). По текущим часовым
  // лимитам реально достижимо 24–48/день, дневной потолок защищает на
  // случай ошибки в логике или ручной правки часовых лимитов.
  if (resolved.channelId != null) {
    const dayUsed = await getChannelDayCount(env, resolved.channelId);
    if (dayUsed >= CONFIRM_PER_CHANNEL_DAILY_MAX) {
      console.log(`confirm: day-cap ${resolved.channelId} `
        + `(${dayUsed}/${CONFIRM_PER_CHANNEL_DAILY_MAX}), skip ${maskPhone(phone)}`);
      return { ok: false, reason: 'day_cap' };
    }
  }

  const url = `${MH_API}/app/projects/${env.MH_PROJECT_ID}`
    + `/channels/${resolved.channelUuid}/send_message/${resolved.userId}`;
  for (let attempt = 0; attempt < 3; attempt++) {
    let res;
    try {
      const form = new FormData();
      form.append('text', text);
      form.append('destination', 'from_operator');
      res = await fetch(url, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: form,
      });
    } catch (e) {
      console.error('confirm send fetch:', e && e.message);
      await sleep(500 * (attempt + 1));
      continue;
    }
    if (res.ok) {
      const data = await res.json().catch(() => null);
      const sentId = data && data.data && data.data.id;
      if (sentId) {
        await env.BOT_KV.put(`sent:${sentId}`, '1', { expirationTtl: SENT_TTL });
      }
      return {
        ok: true,
        channelUuid: resolved.channelUuid,
        channelId: resolved.channelId,
        userId: resolved.userId,
      };
    }
    if (res.status !== 429 && res.status < 500) {
      console.error(`confirm send ${res.status}:`,
        (await res.text()).slice(0, 200));
      return { ok: false };
    }
    const retryAfter = parseInt(res.headers.get('retry-after') || '0', 10);
    await sleep(retryAfter ? retryAfter * 1000 : 600 * (attempt + 1));
  }
  return { ok: false };
}

// Резолв контакта в message.help по телефону. Возвращает {channelUuid, userId}
// или null. extractContactChannel матчит channel_id связки против channelMap
// (id→uuid из MH_CHANNELS) и отдаёт пару, на которой клиент реально с нами.
async function mhResolveContact(env, token, phone, needCreate, channelMap) {
  const body = { phone, need_create: !!needCreate };
  let res;
  try {
    res = await fetch(
      `${MH_API}/app/projects/${env.MH_PROJECT_ID}/contacts/contact_by_phone`,
      {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: JSON.stringify(body),
      });
  } catch (e) {
    console.error('confirm contact_by_phone:', e && e.message);
    return null;
  }
  if (!res.ok) {
    if (res.status === 404 && !needCreate) return null; // не существует — нормально
    console.error(`confirm contact_by_phone ${res.status}:`,
      (await res.text()).slice(0, 200));
    return null;
  }
  const data = await res.json().catch(() => null);
  return extractContactChannel(data, channelMap);
}

// Достаёт пару (channelUuid, userId) из ответа contact_by_phone.
// message.help отдаёт связки вида {id, channel_id, uid (телефон), ...} в
// data.users[]. channel_id — числовой id канала; uuid берём из knownChannels
// (Map id→uuid, наша MH_CHANNELS). Если ни одна связка не попадает в наши
// каналы — возвращаем null (контакт у клиента есть, но писать ему нам некуда).
function extractContactChannel(data, channelMap) {
  if (!data) return null;
  const c = data.data || data;
  if (!c) return null;
  const map = (channelMap instanceof Map) ? channelMap : new Map();

  const candidates = [];
  // Плоский объект
  if (c.user_id || c.id) {
    candidates.push({
      cid: c.channel_id, cuuid: c.channel_uuid || c.uuid,
      uid: c.user_id || c.id,
      blocked: !!c.blocked,
      lastMessageAt: c.last_message || null,
    });
  }
  // Массивы связок (приоритет — users, оно реально отдаётся message.help)
  for (const list of [c.users, c.channels, c.channel_links, c.contact_channels]) {
    if (!Array.isArray(list)) continue;
    for (const x of list) {
      if (!x) continue;
      candidates.push({
        cid: x.channel_id,
        cuuid: x.channel_uuid || x.uuid,
        uid: x.user_id || x.id,
        blocked: !!x.blocked,
        lastMessageAt: x.last_message || null,
      });
    }
  }

  // Прекомпилируем Set наших uuid для O(1) lookup по cuuid.
  const knownUuids = new Set(map.values());

  // Сначала ищем связку на нашем канале (по channel_id из MH_CHANNELS).
  for (const x of candidates) {
    if (!x.uid || x.blocked) continue;
    if (x.cid != null) {
      const uuid = map.get(String(x.cid));
      if (uuid) return {
        channelUuid: uuid, channelId: Number(x.cid),
        userId: x.uid, lastMessageAt: x.lastMessageAt,
      };
    }
    if (x.cuuid && knownUuids.has(String(x.cuuid))) {
      return {
        channelUuid: String(x.cuuid), channelId: x.cid != null ? Number(x.cid) : null,
        userId: x.uid, lastMessageAt: x.lastMessageAt,
      };
    }
  }

  // Связки есть, но НИ ОДНА не из MH_CHANNELS (например только Instagram).
  // Это «контакт на чужом канале» — null, в mhSendByPhone отметится в логе.
  return null;
}

// Map id→uuid наших обслуживаемых каналов (MH_CHANNELS).
function parseKnownChannelMap(env) {
  const map = new Map();
  if (env.MH_CHANNELS) {
    try {
      const obj = JSON.parse(env.MH_CHANNELS);
      for (const [id, uuid] of Object.entries(obj)) {
        if (uuid) map.set(String(id), String(uuid));
      }
    } catch (e) {
      console.error('parseKnownChannelMap:', e && e.message);
    }
  }
  return map;
}

// ── Скрипт сообщения подтверждения ─────────────────────────────────────────

// Текст подтверждения. partsList — список записей клиента на «завтра»
// (если у него несколько процедур подряд, шлём ОДНО сообщение со всеми
// временами). 3 микро-варианта приветствия/интро/CTA — точно по правилу
// message.help «1–3 шаблона текста на рассылку». Вариант детерминирован
// по record_id mod 3.
function buildConfirmationText(partsList, variant) {
  const v = ((Number(variant) || 0) % 3 + 3) % 3;
  // Совместимость: можно передать одну parts вместо массива
  const list = Array.isArray(partsList) ? partsList : [partsList];

  const fmt = (p) => ({
    date: `${String(p.day).padStart(2, '0')}.`
      + `${String(p.month).padStart(2, '0')}.${p.year}`,
    time: `${p.hour}:${String(p.minute).padStart(2, '0')}`,
  });

  const greet = [
    'Добрый день 🌷',
    'Здравствуйте 🌷',
    'Добрый день, M&M на связи ✨',
  ][v];

  const intro = [
    'Это автоматическое напоминание о вашей записи. Если в данных будут неточности — ответьте, и менеджер всё уточнит.',
    'Напоминаем о вашей записи. Если в деталях что-то не так — просто напишите, исправим.',
    'Это напоминание о записи. Если детали не совпадают — ответьте сообщением, поправим.',
  ][v];

  const ask = [
    'Подтвердите, пожалуйста, запись ❤️',
    'Подтвердите, пожалуйста, что придёте ❤️',
    'Подтвердите запись, пожалуйста',
  ][v];

  const lines = [greet, '', intro, ''];

  if (list.length === 1) {
    const f = fmt(list[0]);
    lines.push(
      'Вы записаны в M&M:',
      '',
      `🗓 Дата: ${f.date}`,
      `🕒 Время: ${f.time}`,
      '📍 Ауэзова 175 Б',
    );
  } else {
    // Несколько записей у одного клиента — группируем времена под общей датой
    // (если все в один день) или показываем дата+время построчно.
    const dates = new Set(list.map((p) => fmt(p).date));
    if (dates.size === 1) {
      const oneDate = list[0] ? fmt(list[0]).date : '';
      lines.push(
        `У вас в M&M ${list.length} записи на ${oneDate}:`,
        '',
      );
      for (const p of list) {
        lines.push(`🕒 ${fmt(p).time}`);
      }
      lines.push('📍 Ауэзова 175 Б');
    } else {
      lines.push('У вас в M&M несколько записей:', '');
      for (const p of list) {
        const f = fmt(p);
        lines.push(`🗓 ${f.date} в ${f.time}`);
      }
      lines.push('📍 Ауэзова 175 Б');
    }
  }

  lines.push('', ask, '', '❗ Отмена записи — минимум за 24 часа.',
    'При отмене менее чем за 24 часа предоплата/посещение сгорает.',
    '', 'M & M');

  // Ссылка 2gis — только в 1 из 3 вариантов (~33%). Длинная URL в каждом
  // сообщении читается Meta как маркетинг и повышает шанс спам-флага. Адрес
  // и так есть в тексте — клиент найдёт по нему.
  if (v === 0) {
    lines.push('', 'https://2gis.kz/almaty/geo/70000001060407110');
  }

  return lines.join('\n');
}

// ── Ответ клиента на подтверждение: Да / Нет ───────────────────────────────

// ════════════════════════════════════════════════════════════════════════════
// РАСПОЗНАВАНИЕ ИНТЕНТА ответа на напоминание (перенос/болезнь/отмена/подтвержд.)
// Валидировано на корпусе из 153 реальных формулировок (ru+kz+латиница, опечатки).
// ВАЖНО: \b и \w в JS НЕ работают с кириллицей — границы делаем через классы
// (?:^|[^а-яёa-zі]) … (?![а-яёa-zі]). Не использовать \b/\w вокруг кириллицы!
// ════════════════════════════════════════════════════════════════════════════
const INTENT_NB = '[^а-яёa-zі0-9]';

// Явные слова переноса (устойчивость к опечаткам корня «перенес-»).
function hasRescheduleWord(t) {
  return /(перен[еио]с|перенест|перенисит|перинес|перезапи|сдвин|передвин|подвин|поменя[а-яё]*\s*(?:врем|день|дат|запис|час)|поменя[йт]|измен[а-яё]*\s*(?:врем|день|дат)|на\s+друг[а-яё]*\s+(?:день|врем|дат|раз)|в\s+друг[а-яё]*\s+(?:день|врем|раз)|друг[а-яё]*\s+день|запиш[а-яё]*\s+(?:меня\s+)?на\s+друг|ауыстыр|кейінге\s?қалдыр|кейинге\s?калдыр|басқа\s?(?:күн|уақыт|кезге)|баска\s?(?:кун|уакыт)|baska\s?(?:kun|kún|uaqyt|uakyt))/i.test(t);
}

// Называет КОНКРЕТНЫЙ день/период/сдвиг времени (не «сейчас придёт на запись»).
function namesDayOrPeriod(t) {
  t = String(t || '').toLowerCase();
  if (new RegExp(`(?:^|${INTENT_NB})(?:понедельник[а-яё]*|вторник[а-яё]*|сред[ауыео](?![а-яё])|четверг[а-яё]*|пятниц[а-яё]*|суббот[а-яё]*|воскрес[а-яё]*)`, 'i').test(t)) return true;
  if (new RegExp(`(?:^|${INTENT_NB})(пн|вт|ср|чт|пт|сб|вс)(?![а-яёa-z])`, 'i').test(t)) return true;
  if (/(послезавтра|завтра|сегодня)/i.test(t)) return true;
  if (/(выходн|будни|будн[ия])/i.test(t)) return true;
  if (/(след(?:ующ[а-яё]*|\.)?\s*недел|на\s+той\s+недел|через\s+недел|через\s+\d+\s*(?:дн|недел)|на\s+этой\s+недел|попозже\s+на\s+недел|в\s+начале\s+(?:недел|месяц|июл|июн|август|сентяб)|в\s+конце\s+недел|ближе\s+к\s+выходн|после\s+праздник|в\s+следующий\s+раз|в\s+друг[а-яё]*\s+раз|как-?нибудь|следующ[а-яё]*\s+сеанс|после\s+возвращени|как\s+верн|когда\s+выздоров|как\s+поправл|через\s+недельк)/i.test(t)) return true;
  if (/((?:перв|втор)[а-яё]*\s+половин|во\s+второй\s+половин|ближе\s+к\s+вечер|на\s+\d+\s*час[а-яё]*\s+(?:позже|раньше)|на\s+час\s+(?:позже|раньше)|часом\s+(?:позже|раньше)|к\s+вечеру\s+передвин)/i.test(t)) return true;
  if (/(\d{1,2}\s*-?\s*го(?![а-яё])|\d{1,2}\s*числ|числ[а-яё]*\s*\d{1,2}|\d{1,2}\s*(?:январ|феврал|март|апрел|ма[йя]|июн|июл|август|сентяб|октяб|нояб|декаб)|\b\d{1,2}[.\/]\d{1,2}\b)/i.test(t)) return true;
  if (/(дүйсенбі|сейсенбі|сәрсенбі|бейсенбі|жұма|сенбі|жексенбі|келесі\s?апта|ертең|кейін|сауығып|сауығ|кейінірек)/i.test(t)) return true;
  if (new RegExp(`(?:^|${INTENT_NB})(duisenbi|seisenbi|sarsenbi|beisenbi|juma|jeksenbi|erten|keler|keyin)`, 'i').test(t)) return true;
  return false;
}

function isIllnessReason(t) {
  return /(боле[юе]|заболе|приболе|простыл|простуж|простуд|температур|темпратур|температурю|грипп|ковид|covid|недомог|плохо\s+себя\s+чувств|нездоров|сляг|сл[её]г|ауыр|сырқат|сркат)/i.test(t);
}

function isForceMajeureReason(t) {
  return /(командировк|в\s+отъезд|уехал|уезжаю|аврал|не\s+отпуска|дела\s+навал|не\s+успева|форс-?мажор|машина\s+сломал|реб[её]нок\s+заболе|срочно\s+вызвал|вызвали\s+на\s+работ|никак\s+не\s+вырват)/i.test(t);
}

// Хочет прийти ПОЗЖЕ (намерение визита сохраняется).
function wantsToComeLater(t) {
  return /(прид[уёе]|прийд|приед|приех|(?:^|[^а-яёa-z])буду(?![а-яё])|подойд|подъед|запиш|жазыл|жазсам|жазайы|боламын|барамын|kel(?:em|ip|edi)?)/i.test(t);
}

// НЕ придёт совсем.
function wontComeAtAll(t) {
  return /(не\s+смогу|не\s+получ(?:ится|у)?(?:\s+(?:прийти|подойти|быть|приехать))?|не\s+приду|не\s+буду\s+приход|никак\s+не\s+доберусь|не\s+доберусь|не\s+выйдет|бара\s?алмай|келе\s?алмай|жаза\s?алмай|kele\s?almai|bara\s?almai)/i.test(t);
}

function hasCancelWordIntent(t) {
  return /(отмен(?:и|ить|ите|яю|ю|а|у|её|ее)|отказ(?:ать|аться|ыва|ываюсь|усь)?|удал(?:и|ите|ить)\s+запис|снять\s+запис|\bcancel\b|otmena|бас\s?тарт|болдырма)/i.test(t);
}

// Мягкий отказ ИМЕННО от записанного дня (без нового дня и без «отмена») = перенос.
function rejectsBookedDay(t) {
  return /((?:не\s+(?:получ|могу|выйдет|сложит|удобн)[а-яё]*|никак)[^.!?]{0,18}(?:этот\s+день|в\s+этот\s+день|сегодня|в\s+назначенн|в\s+это\s+время)|не\s+в\s+этот\s+день|в\s+этот\s+раз\s+не|не\s+успе[юе][^.!?]{0,12}(?:к\s+\d|вовремя|к\s+начал))/i.test(t);
}

// Вопрос (нужен человек) — ru+kz, в т.ч. без «?».
function isQuestionIntent(t) {
  if (String(t).indexOf('?') !== -1) return true;
  return /(во\s?сколько|во\s?скока|сколько\s+стоит|цена|стоит|можно\s+ли|с\s+подруг|с\s+ребёнк|перезвон|позвони|можете\s+позвон|қанша|неше(?:де|ге)?|қашан|неге|қай\s?(?:күн|жер|маст)|бола\s?ма|болады\s?ма|qansha|qashan|qai\s?kun|qai\s?kuni|nese)/i.test(t);
}

// Опоздание (тот же день, позже) — без переноса/отмены/другого дня.
function isLateButComingIntent(t) {
  t = String(t || '').toLowerCase();
  if (t.length > 90) return false;
  return /(опозда|задерж|чуть\s+позже|немного\s+позже|по-?позже|буд[уе]\s+позже|приед[уе][^.!?]{0,18}позже|приду\s+позже|позже\s+чем\s+договар|на\s+\d+\s*мин(?:ут[а-яё]*)?\s*позже|минут[а-яё]*\s+на\s+\d+|позже\s+на\s+\d+|кешіг|кешік|keship|keshik|пробк)/i.test(t)
    && !hasRescheduleWord(t) && !hasCancelWordIntent(t) && !namesDayOrPeriod(t) && !rejectsBookedDay(t);
}

// Короткое подтверждение (без знания дня) — да/ок/приду/эмодзи 👍.
function isPlainConfirmIntent(t) {
  let s = String(t || '').trim().toLowerCase();
  if (!s || s.length > 120) return false;
  if (s.indexOf('?') !== -1) return false;
  if (/[👎❌✖✗]/u.test(s)) return false;
  if (/[👍✅☑✔❤🌷👌🙏🤍]/u.test(s)) return true;
  const words = s.split(/[^a-zа-яёі]+/i).filter(Boolean);
  const wset = new Set(words);
  const exact = (arr) => arr.some((x) => wset.has(x));
  const prefix = (arr) => words.some((w) => arr.some((p) => w.startsWith(p)));
  if (exact(['да', 'ия', 'иа', 'иә', 'плюс', 'ок', 'окей', 'оке', 'хорошо', 'харош', 'харошо',
    'конечно', 'приду', 'прийду', 'буду', 'ага', 'угу', 'yes', 'ok', 'еду', 'иду', 'пути',
    'месте', 'рядом', 'обязательно', 'договорились', 'договорилис', 'бегу', 'подъезжаю', 'выезжаю',
    'выезжаем', 'барамын', 'боламын', 'келемін', 'келемин', 'келемыз', 'келем', 'келе', 'жатырмын',
    'жолдамын', 'келеді', 'jane', 'keled', 'keledi', 'kelemin', 'bolamyn', 'baramyn'])
    || prefix(['подтвержд', 'приед', 'подойд', 'подъед', 'подъезж', 'выезж', 'выех', 'доед', 'добира'])
    || s === '1' || s === '+' || /(?:^|\s)\+(?:\s|$)/.test(s)) {
    return true;
  }
  return false;
}

// Оркестратор интента ответа на напоминание о записи.
// Возвращает {intent: 'confirm'|'reschedule'|'cancel'|'late'|'question'|'other', reason?, dayText?}.
// ctx (опц.): { sameBookedDay: bool } — клиент ссылается ТОЛЬКО на день записи
// («завтра же, да?» когда завтра = день брони) → не считать переносом.
function classifyReminderIntent(text, ctx = {}) {
  const t = String(text || '').trim();
  if (!t) return { intent: 'other' };
  const low = t.toLowerCase();
  const day = namesDayOrPeriod(low) && !ctx.sameBookedDay;
  const ill = isIllnessReason(low) || isForceMajeureReason(low);
  const wont = wontComeAtAll(low);
  const later = wantsToComeLater(low) && !wont;
  const exResched = hasRescheduleWord(low);
  const exCancel = hasCancelWordIntent(low);
  if (exResched || rejectsBookedDay(low)) {
    return { intent: 'reschedule', reason: ill ? 'болезнь/форс-мажор' : '', dayText: t };
  }
  if (exCancel) {
    if (later) return { intent: 'reschedule', reason: ill ? 'болезнь/форс-мажор' : '', dayText: t };
    return { intent: 'cancel', reason: ill ? 'болезнь/форс-мажор' : '' };
  }
  if (day) return { intent: 'reschedule', reason: ill ? 'болезнь/форс-мажор' : '', dayText: t };
  if (isLateButComingIntent(low)) return { intent: 'late' };
  if (ill) {
    if (wont) return { intent: 'cancel', reason: 'болезнь/форс-мажор' };
    if (later) return { intent: 'confirm' };
    return { intent: 'reschedule', reason: 'болезнь/форс-мажор', dayText: t };
  }
  if (wont) return { intent: 'cancel' };
  if (isQuestionIntent(low)) return { intent: 'question' };
  if (isPlainConfirmIntent(low)) return { intent: 'confirm' };
  return { intent: 'other' };
}

function classifyConfirmationResponse(rawText) {
  if (!rawText) return null;
  let t = String(rawText).trim().toLowerCase();
  // Очень длинные / вопросительные ответы не считаем коротким Да/Нет — пусть
  // Claude разбирает (либо менеджер). Лимит 120: вежливое подтверждение с
  // приветствием и благодарностью («Здравствуйте, спасибо за напоминание,
  // завтра буду 👍») должно распознаваться как «да», а не уходить менеджеру.
  if (t.length > 120) return null;
  if (t.indexOf('?') !== -1) return null;

  // Эмодзи-сигналы (в любом месте текста). «Нет» проверяем раньше «да».
  if (/[👎❌✖✗]/u.test(t)) return 'no';

  // Разбиваем на слова (только буквы). КОРОТКИЕ маркеры матчим ТОЧНО по слову
  // (иначе «да» ловит «даже», «ок» — «около», «буду» — «забуду»: в JS \W матчит
  // кириллицу, и старый regex давал ложные срабатывания). Основы
  // (подтвержд…, отмен…, перенес…) — по префиксу слова; «нет приду» — «не»+глагол.
  const words = t.split(/[^a-zа-яёі]+/i).filter(Boolean);
  const wset = new Set(words);
  const exact = (arr) => arr.some((x) => wset.has(x));
  const prefix = (arr) => words.some((w) => arr.some((p) => w.startsWith(p)));

  const negVerb = ['приду', 'прийду', 'буду', 'смог', 'получ', 'прид', 'приед', 'дойд',
    'еду', 'иду', 'выезж', 'выех', 'доед', 'подъед'];
  if (exact(['нет', 'нету', 'жок', 'joq', 'no', 'отказ'])
    || prefix(['отмен', 'перенес', 'отказыва'])
    || (wset.has('не') && words.some((w) => negVerb.some((v) => w.startsWith(v))))) {
    return 'no';
  }

  if (/[👍✅☑✔❤🌷👌]/u.test(t)) return 'yes';
  // «Да/приду» + живые ответы про дорогу: «еду», «в пути», «на месте», «иду»,
  // «подъезжаю/выезжаю», «скоро буду», «обязательно», «договорились» (рус+каз).
  if (exact(['да', 'ия', 'иә', 'плюс', 'ок', 'окей', 'хорошо', 'конечно', 'приду', 'прийду',
    'буду', 'ага', 'угу', 'yes', 'еду', 'иду', 'пути', 'месте', 'рядом', 'обязательно',
    'договорились', 'бегу', 'подъезжаю', 'выезжаю', 'выезжаем',
    'барамын', 'келемін', 'келемыз', 'келем', 'келе', 'жатырмын', 'жолдамын'])
    || prefix(['подтвержд', 'приед', 'подойд', 'подъед', 'подъезж', 'выезж', 'выех', 'доед', 'добира'])
    || t === '1' || t === '+' || /(?:^|\s)\+(?:\s|$)/.test(t)) {
    return 'yes';
  }
  return null;
}

// Клиент в ответ на напоминание назвал ВРЕМЯ прихода без явного «да/нет»
// («буду к 10:05», «в 10.20 думаю»). Если названное время в пределах допуска
// опоздания (tolMin) от времени брони (apptMin — минуты от полуночи) — считаем
// запись подтверждённой. Берём МАКСИМАЛЬНОЕ из названных времён (худший случай:
// «10:20, даже 10:30» → 30 мин). Длинные/вопросительные сообщения не трогаем
// (там может быть реальный вопрос) — пусть идут к менеджеру.
// Короткое вежливое закрытие диалога: «спасибо», «договорились», 🙏 — это НЕ
// вопрос, НЕ отказ и НЕ просьба. Записанному клиенту на такое менеджера дёргать
// НЕ нужно — достаточно тёплого «будем рады видеть вас».
function isPoliteClosing(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t || t.length > 60 || t.indexOf('?') !== -1) return false;
  const grat = /(спасиб|спс|благодар|пожалуйст|договорил|понятн|поняла|ясно|хорошо|отличн|супер|класс)/i.test(t);
  const emojiClose = /^[\s🙏🌷❤❤️👍🤍✨😊🙂👌🌸💐🙌]+$/u.test(t);
  if (!grat && !emojiClose) return false;
  // …но НЕ если это вопрос/просьба/перенос/отмена.
  if (/(перенес|отмен|нельзя|можно ли|во сколько|когда|почему|вопрос|поменя|измен|верн|деньг|оплат|не\s)/i.test(t)) return false;
  return true;
}

// Реальный вопрос или просьба, на которые нужен ЧЕЛОВЕК (перенос, отмена,
// «во сколько?», сомнение, перезвон). ТОЛЬКО это эскалируем менеджеру —
// приветствие и прочее benign к человеку не отправляем.
function isQuestionOrRequest(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t) return false;
  if (t.indexOf('?') !== -1) return true;
  return /(перенес|перенест|отмен|можно ли|во ?сколько|когда|почему|поменя|измен|деньг|оплат|перезвон|позвон|не получ|не увер|не знаю|подума|посмотр|болею|заболе|приболе|плохо себя|месячн|менструац|критическ|температур|простыл|простуд|недомог|друг(ой|ое) (день|врем)|опозда|вопрос|уточн|пробле|сомнева|қанша|неге|қашан|ауыстыр|бас\s?тарт|келе\s?алмай)/i.test(t);
}

// Клиент опаздывает, но ВСЁ РАВНО придёт («опоздаю», «задержусь», «буду позже»).
// Это подтверждение визита, а не отказ — менеджера не дёргаем.
function isLateButComing(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t || t.length > 80) return false;
  return /(опозда|задерж|чуть\s+позже|немного\s+позже|буду\s+позже|приеду\s+позже|приду\s+позже|кешіг|кешік)/i.test(t)
    && !/(перенес|отмен|не\s+смогу|не\s+приду|друг(?:ой|ое)\s+(?:день|врем))/i.test(t);
}

// Простой вопрос про адрес/как доехать — бот отвечает сам (адрес у него есть),
// менеджера не дёргает. Исключаем отмену/перенос/цену (это к человеку).
const STUDIO_ADDRESS_LINE = 'Наш адрес: г. Алматы, ул. Ауэзова 175Б, угол ул. Габдуллина 🌷 Будем рады видеть вас!';
function isAddressQuestion(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t || t.length > 80) return false;
  return /(адрес|где вы наход|где находит|где вы\b|где это|доехать|проехать|добра(?:ть|ться)|как найти|куда (?:ехать|идти|подъ)|локац|геолокац|мекенжай|қай жер)/i.test(t)
    && !/(отмен|перенес|сколько|цена|стоит|оплат)/i.test(t);
}

// Фича отмены включена и есть доступ к Altegio (иначе бот не может найти/удалить).
function cancelEnabled(env) {
  return String(env.CANCEL_BY_REQUEST) === '1'
    && !!env.ALTEGIO_PARTNER_TOKEN && !!env.ALTEGIO_USER_TOKEN && !!env.ALTEGIO_COMPANY_ID;
}

// Клиент просит ОТМЕНИТЬ запись (а не перенести).
function isCancelRequest(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t) return false;
  return /(отмен(?:и|ить|ите|яю|ю|а|у)|отказ(?:ать|аться|ыва)|удал(?:и|ите|ить)\s+запис|снять\s+запис|не\s+смогу\s+(?:прийти|подойти|быть|приехать)|не\s+получ(?:ится|у)\s+(?:прийти|подойти)|не\s+приду|не\s+буду\s+приход|cancel|бас\s?тарт|болдырма|келе\s?алмай|бара\s?алмай|жаза\s?алмай)/i.test(t);
}

// Клиент просит ПЕРЕНЕСТИ (бот сам не переносит — отдаёт менеджеру).
function isRescheduleRequest(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t || isCancelRequest(t)) return false;
  return /(перенес|перенест|перенос|сдвин|перезапиш|поменя(?:ть|йте|ем)?\s*(?:врем|день|дату|запис)|на\s+друг(?:ой|ое|ую)\s+(?:день|врем|дату)|в\s+друг(?:ой|ое)\s+(?:день|врем)|ауыстыр|баск(?:а|ы)\s?(?:күн|кун|уақыт|уакыт|кезге)|кейінге\s?қалдыр|кешіктір)/i.test(t);
}

// Решение клиента в флоу отмены: 'keep' (передумал) | 'reschedule' | 'cancel' | null.
// Инвариант: удаление в Altegio — ТОЛЬКО при 'cancel'. Неоднозначность → null.
function classifyCancelDecision(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t) return null;
  if (/не\s+(?:надо\s+|нужно\s+)?(?:отмен|переноси)/i.test(t)) return 'keep'; // «не отменяйте», «не надо переносить»
  const hasCancel = /(отмен|отказ|удал|снять\s+запис|cancel|не\s+приду|не\s+буду\s+приход|бас\s?тарт|болдырма|келе\s?алмай|бара\s?алмай)/i.test(t);
  const hasResched = /(перенес|перенест|перенос|сдвин|перезапиш|поменя|друг(?:ой|ое|ую)\s+(?:день|врем|дату)|ауыстыр|баск(?:а|ы)\s?(?:күн|кун|уақыт|уакыт))/i.test(t);
  const hasKeep = /(переду|остав(?:ь|ьте|им|ляю|ляем)|остаюсь|оста[её]мся|в\s+силе|приду|приеду|подойду|буду\s+приход|келемін|келем|қаламын|боламын)/i.test(t);
  if (hasKeep && !hasCancel && !hasResched) return 'keep';
  if (hasCancel) return 'cancel';
  if (hasResched) return 'reschedule';
  return null;
}

function arrivalWithinTolerance(text, apptMin, tolMin) {
  if (apptMin == null) return false;
  const t = String(text || '');
  if (t.length > 60 || t.indexOf('?') !== -1) return false;
  const re = /(\d{1,2})[:.](\d{2})/g;
  let m, maxDev = -1;
  while ((m = re.exec(t)) !== null) {
    const h = Number(m[1]), mi = Number(m[2]);
    if (h > 23 || mi > 59) continue;
    const dev = Math.abs(h * 60 + mi - apptMin);
    if (dev > maxDev) maxDev = dev;
  }
  if (maxDev < 0) return false;          // время не названо
  return maxDev <= (Number(tolMin) || 10);
}

async function handleConfirmationResponse(env, msg, kind, pending) {
  // Сбрасываем pending в любом случае — повторно не реагируем.
  await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);

  if (kind === 'yes') {
    let altOk = false;
    if (pending && pending.recordId) {
      try { altOk = await markAttendanceConfirmed(env, pending.recordId); }
      catch (e) { console.error('attendance set error:', e && e.message); }
    }
    await sendMessage(env, msg, 'Спасибо! Ждём вас 🌷');
    await bumpStat(env, 'confirm_yes');
    // Локальная отметка на случай если Altegio не дался — менеджер увидит лог
    await env.BOT_KV.put(`confirm_done:${pending && pending.recordId}`, JSON.stringify({
      kind: 'confirmed', altegio: altOk, at: new Date().toISOString(),
      userId: msg.userId,
    }), { expirationTtl: LEAD_TTL });
    console.log(`confirm reply YES u${msg.userId} record=${pending && pending.recordId} altegio=${altOk}`);
    return;
  }

  if (kind === 'no') {
    await sendMessage(env, msg, 'Поняла, передаю менеджеру — он(а) свяжется и поможет 🤍');
    await bumpStat(env, 'confirm_no');
    if (msg.userId) {
      await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
    }
    await env.BOT_KV.put(`confirm_done:${pending && pending.recordId}`, JSON.stringify({
      kind: 'cancel_requested', at: new Date().toISOString(),
      userId: msg.userId,
    }), { expirationTtl: LEAD_TTL });
    await assignToManager(env, msg);

    // Мгновенная карточка менеджерам: клиент отказался от записи — успеть
    // спасти (перенос) или освободить слот в журнале.
    await sendTelegramAlert(env, [
      `🔴 Клиент ответил «НЕТ» на подтверждение записи · ${almatyHHMM()}`,
      `${pending && pending.phone ? fmtPhoneHuman(pending.phone) : `Чат №${msg.userId}`}`
        + ` · запись Altegio №${(pending && pending.recordId) || '—'}`,
      `Ответ клиента: «${String(msg.text || '').slice(0, 120)}»`,
      'Свяжитесь с клиентом: перенос или отмена записи.',
    ].join('\n'));

    console.log(`confirm reply NO u${msg.userId} record=${pending && pending.recordId}`);
  }
}

// Клиент ответил на подтверждение НЕ короткое «Да/Нет», а вопросом или
// просьбой («можно перенести?», «во сколько было?», «не уверена пока»,
// «у меня плохое самочувствие»). Бот сам не отвечает — это не его уровень
// компетенции; нужно довести до менеджера. Работает в ЛЮБОЕ время суток.
async function handleConfirmationFollowUp(env, msg, pending) {
  await env.BOT_KV.delete(`confirm_pending:user:${msg.userId}`);

  await sendMessage(env, msg,
    'Поняла вас 🌷 Передаю менеджеру — он(а) свяжется в ближайшее время и поможет с записью.');

  if (msg.userId) {
    await env.BOT_KV.put(`op:${msg.userId}`, '1',
      { expirationTtl: OPERATOR_PAUSE_TTL });
  }

  await env.BOT_KV.put(`confirm_done:${pending && pending.recordId}`,
    JSON.stringify({
      kind: 'followup_to_manager',
      recordId: pending && pending.recordId,
      clientText: String(msg.text || '').slice(0, 300),
      at: new Date().toISOString(),
      userId: msg.userId,
    }), { expirationTtl: LEAD_TTL });

  await assignToManager(env, msg);

  // Карточка менеджерам: клиент ответил на напоминание вопросом/просьбой —
  // бот сам не отвечает, диалог ждёт человека.
  await sendTelegramAlert(env, [
    `🟡 Вопрос по записи вместо «Да/Нет» · ${almatyHHMM()}`,
    `${pending && pending.phone ? fmtPhoneHuman(pending.phone) : `Чат №${msg.userId}`}`
      + ` · запись Altegio №${(pending && pending.recordId) || '—'}`,
    `Клиент: «${String(msg.text || '').slice(0, 160)}»`,
    'Ответьте клиенту в message.help.',
  ].join('\n'));

  console.log(`confirm reply FOLLOWUP u${msg.userId} `
    + `record=${pending && pending.recordId} `
    + `text="${String(msg.text || '').slice(0, 60)}"`);
}

// Клиент УЖЕ записан (нашли запись в Altegio) и первым сообщением отвечает на
// напоминание (внешнее — наше прошло бы через confirm_pending). «Да/Приду» →
// тёплое подтверждение БЕЗ опроса; «Нет/не приду» → передаём менеджеру
// (перенос/отмена). Имя/противопоказания НЕ спрашиваем — собраны при записи.
async function handleBookedReminderReply(env, msg, kind, booking, phone) {
  if (kind === 'yes') {
    if (booking && booking.recordId) {
      try { await markAttendanceConfirmed(env, booking.recordId); }
      catch (e) { console.error('booked-reply attendance:', e && e.message); }
    }
    await sendMessage(env, msg, 'Спасибо! Будем рады видеть вас 🌷');
    console.log(`booked-reminder YES u${msg.userId} record=${booking && booking.recordId}`);
    return;
  }
  await sendMessage(env, msg, 'Поняла, передаю менеджеру — он(а) свяжется и поможет с записью 🤍');
  if (msg.userId) {
    await env.BOT_KV.put(`op:${msg.userId}`, '1', { expirationTtl: OPERATOR_PAUSE_TTL });
  }
  await assignToManager(env, msg);
  await sendTelegramAlert(env, [
    `🔴 «${String(msg.text || '').slice(0, 30)}» на напоминание о записи · ${almatyHHMM()}`,
    `${phone ? fmtPhoneHuman(phone) : `Чат №${msg.userId}`} · запись Altegio №${(booking && booking.recordId) || '—'}`,
    'Клиент, похоже, не придёт или хочет перенести. Свяжитесь — перенос или отмена.',
  ].join('\n'));
  console.log(`booked-reminder NO u${msg.userId} record=${booking && booking.recordId}`);
}

// ── Ответы клиента на engage-сообщение рассылки ────────────────────────────
// engage: {phone, templateIdx, sentAt}. На «Да» → отправляем FULL шаблон,
// «Нет» → ставим opt-out на 365 дней, иначе → передаём менеджеру.

async function handleBroadcastEngageYes(env, msg, engage) {
  // Удаляем pending в любом случае
  await env.BOT_KV.delete(`broadcast_engage_pending:user:${msg.userId}`);

  // Берём вариант FULL шаблона тот же что был у engage — для согласованности
  const variant = engage && Number.isFinite(Number(engage.templateIdx))
    ? Number(engage.templateIdx) : 0;
  const fullText = BROADCAST_FULL_TEMPLATES[variant % 3];

  // Краткое приветствие + полный текст (одним сообщением для целостности)
  const text = `Отлично! ✨ Рассказываю:\n\n${fullText}\n\nЕсли захотите выбрать программу — просто напишите, передам менеджеру для записи.`;
  await sendMessage(env, msg, text);

  // Помечаем как «прошёл шаг 2» для аналитики
  await env.BOT_KV.put(`broadcast_engage_yes:${msg.userId}`, JSON.stringify({
    at: new Date().toISOString(),
    phone: engage && engage.phone,
    variant,
  }), { expirationTtl: LEAD_TTL });

  console.log(`broadcast engage YES u${msg.userId} → отправлен FULL вариант ${variant + 1}`);
}

async function handleBroadcastEngageNo(env, msg, engage) {
  await env.BOT_KV.delete(`broadcast_engage_pending:user:${msg.userId}`);

  // Opt-out на 365 дней по телефону — больше не дёргаем НИКАКОЙ рассылкой
  if (engage && engage.phone) {
    await env.BOT_KV.put(`broadcast_optout:${engage.phone}`,
      JSON.stringify({ at: new Date().toISOString(), via: 'engage_no' }),
      { expirationTtl: BROADCAST_OPTOUT_TTL });
  }

  await sendMessage(env, msg,
    'Поняла, не буду беспокоить 🌷 Если что-то понадобится — пишите, всегда рады!');

  console.log(`broadcast engage NO u${msg.userId} → opt-out для ${engage && engage.phone}`);
}

async function handleBroadcastEngageOther(env, msg, engage) {
  await env.BOT_KV.delete(`broadcast_engage_pending:user:${msg.userId}`);

  // Любой длинный/непонятный ответ — передаём менеджеру.
  await sendMessage(env, msg,
    'Поняла вас 🌷 Передаю менеджеру — он(а) свяжется в ближайшее время и подробно расскажет.');

  if (msg.userId) {
    await env.BOT_KV.put(`op:${msg.userId}`, '1',
      { expirationTtl: OPERATOR_PAUSE_TTL });
  }

  await env.BOT_KV.put(`broadcast_engage_handoff:${msg.userId}`, JSON.stringify({
    at: new Date().toISOString(),
    phone: engage && engage.phone,
    clientText: String(msg.text || '').slice(0, 300),
  }), { expirationTtl: LEAD_TTL });

  await assignToManager(env, msg);
  console.log(`broadcast engage OTHER u${msg.userId} → handoff, text="${String(msg.text || '').slice(0, 60)}"`);
}

// ── Парсеры даты Altegio (локальное время Almaty) ──────────────────────────

function parseAltegioParts(s) {
  if (!s) return null;
  const m = String(s).match(
    /^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (!m) return null;
  return {
    year: +m[1], month: +m[2], day: +m[3],
    hour: +m[4], minute: +m[5], second: +(m[6] || 0),
  };
}

function partsToAlmatyMs(p) {
  // Altegio отдаёт datetime в локальном времени филиала (Almaty, UTC+5)
  // без таймзоны. Чтобы получить корректный ms-таймстамп, вычитаем смещение.
  return Date.UTC(p.year, p.month - 1, p.day,
    p.hour - ALMATY_UTC_OFFSET, p.minute, p.second);
}

// ── Утилиты телефонов и анти-бан ───────────────────────────────────────────

function normalizePhone(raw) {
  if (!raw) return null;
  const d = String(raw).replace(/\D/g, '');
  if (d.length < 10) return null;
  // 87xxxxxxxxx (Каз.) → 77xxxxxxxxx
  if (d.length === 11 && d[0] === '8') return '7' + d.slice(1);
  if (d.length === 11 && d[0] === '7') return d;
  if (d.length === 10) return '7' + d;
  return d;
}

// Внутренние номера (менеджеры/сотрудники) из секрета INTERNAL_PHONES (CSV).
// Бот их НЕ ведёт как лидов и НЕ шлёт им напоминаний. Сверка по последним 10 цифрам.
function internalPhoneSet(env) {
  const set = new Set();
  for (const p of String(env.INTERNAL_PHONES || '').split(/[,\s]+/)) {
    const tail = p.replace(/\D/g, '').slice(-10);
    if (tail.length === 10) set.add(tail);
  }
  return set;
}
function isInternalPhone(env, phone) {
  const tail = String(phone || '').replace(/\D/g, '').slice(-10);
  if (tail.length < 10) return false;
  return internalPhoneSet(env).has(tail);
}

function maskPhone(p) {
  if (!p) return '<none>';
  return String(p).slice(0, 4) + '***' + String(p).slice(-3);
}

function shuffleInPlace(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
  }
  return arr;
}

// ════════════════════════════════════════════════════════════════════════════
// РАССЫЛКА (BROADCAST)
// Активируется через env.BROADCAST_ACTIVE='1'. Шлёт акции по базе активных
// клиентов Altegio строго через WA2 (channel 20916). Темплейты ротируются
// по часу. Полностью отдельный поток от confirmation: свой dedup, свой
// часовой счётчик, свой sleep.
// ════════════════════════════════════════════════════════════════════════════

async function runBroadcastJob(env) {
  if (env.BROADCAST_ACTIVE !== '1') return;
  // Предохранитель mm-pulse-bot (WS-1): при всплеске жалоб pulse ставит флаг
  // broadcast_pause в этот KV. Стоит — пропускаем тик целиком (снимается кнопкой
  // «Возобновить» у владельца). Сбой чтения флага рассылку НЕ блокирует.
  try {
    if (await env.BOT_KV.get('broadcast_pause')) { console.log('broadcast: на паузе (broadcast_pause), пропуск тика'); return; }
  } catch (e) { console.error('broadcast: чтение broadcast_pause упало:', e && e.message); }
  // Анти-совпадение с авто-подтверждениями записей (у подтверждений приоритет —
  // это записи клиентов). Если подтверждения слали недавно (<2 мин) — рассылку
  // в этот тик НЕ запускаем, чтобы рассылка и авто-уведомление не ушли клиентам
  // в одну минуту. Метку last_confirm_send ставит runConfirmationJob; scheduled()
  // ждёт подтверждения ПЕРЕД рассылкой, поэтому метка здесь актуальна.
  try {
    const lastConfirmMs = Number(await env.BOT_KV.get('last_confirm_send')) || 0;
    if (lastConfirmMs && (Date.now() - lastConfirmMs) < 120000) {
      console.log('broadcast: недавно были авто-подтверждения (<2мин) — пропуск тика');
      return;
    }
  } catch (_) { /* сбой чтения метки рассылку не блокирует */ }
  if (!env.MH_LOGIN || !env.MH_PASSWORD || !env.MH_PROJECT_ID) {
    console.log('broadcast: message.help not configured, skip');
    return;
  }
  if (!env.ALTEGIO_PARTNER_TOKEN || !env.ALTEGIO_USER_TOKEN
    || !env.ALTEGIO_COMPANY_ID) {
    console.log('broadcast: altegio not configured, skip');
    return;
  }

  const now = almatyNow();
  if (now.hour >= BROADCAST_END_HOUR) {
    console.log(`broadcast: ended (h=${now.hour} >= ${BROADCAST_END_HOUR})`);
    return;
  }
  if (now.hour < CONFIRM_HOUR_START) {
    console.log(`broadcast: before start (h=${now.hour})`);
    return;
  }

  // startedAt — записываем в KV при первом tick'е дня
  const startedKey = `broadcast:started:${now.ymd}`;
  let startedAt = await env.BOT_KV.get(startedKey);
  if (!startedAt) {
    startedAt = new Date(now.ms).toISOString();
    await env.BOT_KV.put(startedKey, startedAt, { expirationTtl: 90000 });
    console.log(`broadcast: started at ${startedAt} (Almaty ${now.ymd} ${now.hour}:${String(now.minute).padStart(2,'0')})`);
  }
  const startedMs = new Date(startedAt).getTime();
  const hoursSinceStart = Math.floor((now.ms - startedMs) / 3600000);
  const templateIdx = ((hoursSinceStart % 3) + 3) % 3;

  // Дневной потолок — страховка под правило message.help «не более 300/день»
  const dayKey = `broadcast_day:${now.ymd}`;
  const dayUsed = Number(await env.BOT_KV.get(dayKey)) || 0;
  if (dayUsed >= BROADCAST_PER_DAY) {
    console.log(`broadcast: day cap reached (${dayUsed}/${BROADCAST_PER_DAY}) — стоп до завтра`);
    return;
  }
  // Часовой потолок 30/час
  const hourKey = `broadcast_hour:${now.ymdh}`;
  const hourUsed = Number(await env.BOT_KV.get(hourKey)) || 0;
  if (hourUsed >= BROADCAST_PER_HOUR) {
    console.log(`broadcast: hour cap reached (${hourUsed}/${BROADCAST_PER_HOUR}) at h=${now.hour}`);
    return;
  }
  const remainingThisHour = BROADCAST_PER_HOUR - hourUsed;
  const remainingToday = BROADCAST_PER_DAY - dayUsed;
  const tickQuota = Math.min(BROADCAST_TICK_MAX, remainingThisHour, remainingToday);

  // База клиентов Altegio (кеш в KV на 6ч)
  const base = await fetchBroadcastBase(env);
  if (!base || !base.length) {
    console.log('broadcast: empty base, skip');
    return;
  }

  const token = await getMhToken(env);
  if (!token) {
    console.error('broadcast: no MH token');
    return;
  }

  shuffleInPlace(base);
  // Шаг 1 (engage): короткий вопрос с открытием нового чата на WA2.
  const text = BROADCAST_ENGAGE_TEMPLATES[templateIdx];

  let sent = 0;
  let dedupSkip = 0;
  let optoutSkip = 0;
  let noContactSkip = 0;
  let pendingSkip = 0;
  let opSkip = 0;
  const blacklist = broadcastBlacklistSet(env);  // ЧС из секрета env.BROADCAST_BLACKLIST_PHONES

  for (const client of base) {
    if (sent >= tickQuota) break;

    const phone = normalizePhone(client.phone);
    if (!phone) continue;

    // Чёрный список из Altegio (секрет BROADCAST_BLACKLIST_PHONES, сверка по 10 цифрам)
    if (blacklist.has(String(phone).slice(-10))) { optoutSkip++; continue; }
    // Уже шла рассылка этому телефону
    if (await env.BOT_KV.get(`broadcast_sent:${phone}`)) { dedupSkip++; continue; }
    // Клиент когда-то ответил «нет/отпишите» — больше не пишем
    if (await env.BOT_KV.get(`broadcast_optout:${phone}`)) { optoutSkip++; continue; }

    // ШАГ 1: ищем существующий контакт БЕЗ создания нового чата.
    // Если клиент уже писал нам — провалидируем блокировки по его userId.
    let resolved = await mhResolveContactStrict(env, token, phone,
      BROADCAST_CHANNEL_ID, BROADCAST_CHANNEL_UUID, false);

    if (resolved) {
      // Существующий контакт — проверяем блокировки
      if (await env.BOT_KV.get(`confirm_pending:user:${resolved.userId}`)) {
        pendingSkip++;
        continue;
      }
      if (await env.BOT_KV.get(`op:${resolved.userId}`)) {
        opSkip++;
        continue;
      }
      if (await env.BOT_KV.get(`broadcast_engage_pending:user:${resolved.userId}`)) {
        dedupSkip++;
        continue;
      }
    } else {
      // ОТКАЗ от need_create=true: message.help при попытке создать чат на WA2
      // игнорирует наш channel_uuid и привязывает контакт к WA1 (17222),
      // потому что у клиентов уже есть история на WA1. Наш фильтр channel_id===20916
      // не находит запись → send не делается → но триггер «Создать сделку» в
      // воронке Records Altegio уже сработал на сам факт contact_by_phone.
      // Итог: 84 пустых сделок 10.06 + 5.6% реальной отправки.
      // Решение: шлём ТОЛЬКО тем, у кого уже есть история на WA2.
      // Это соответствует правилу message.help bulk-FAQ.
      noContactSkip++;
      continue;
    }

    // Атомарная отправка с одним retry на сетевой/5xx сбой —
    // чтобы не оставлять пустой чат после успешного create.
    let ok = await mhSendDirect(env, token,
      BROADCAST_CHANNEL_UUID, resolved.userId, text);
    if (!ok) {
      await sleep(2000 + Math.floor(Math.random() * 2000));
      ok = await mhSendDirect(env, token,
        BROADCAST_CHANNEL_UUID, resolved.userId, text);
    }
    if (!ok) {
      console.error(`broadcast: send failed phone=${maskPhone(phone)} userId=${resolved.userId}`);
      continue;
    }

    sent++;
    await env.BOT_KV.put(`broadcast_sent:${phone}`, JSON.stringify({
      sentAt: new Date().toISOString(),
      templateIdx, userId: resolved.userId, step: 'engage',
    }), { expirationTtl: BROADCAST_DEDUP_TTL });
    // Pending для второго этапа: при ответе клиента (да/нет/что-то ещё)
    // processMessage заглянет сюда и поймёт что отправить.
    await env.BOT_KV.put(`broadcast_engage_pending:user:${resolved.userId}`,
      JSON.stringify({
        phone, templateIdx, sentAt: new Date().toISOString(),
      }), { expirationTtl: BROADCAST_ENGAGE_PENDING_TTL });
    await env.BOT_KV.put(hourKey, String(hourUsed + sent),
      { expirationTtl: BROADCAST_HOUR_COUNTER_TTL });
    await env.BOT_KV.put(dayKey, String(dayUsed + sent),
      { expirationTtl: 90000 });

    if (sent < tickQuota) {
      await sleep(BROADCAST_TICK_PAUSE_MIN
        + Math.floor(Math.random()
          * (BROADCAST_TICK_PAUSE_MAX - BROADCAST_TICK_PAUSE_MIN)));
    }
  }

  console.log(`broadcast engage tick: base=${base.length}, h=${now.hour}:${String(now.minute).padStart(2,'0')}, `
    + `template=${templateIdx + 1}, hour_used=${hourUsed + sent}/${BROADCAST_PER_HOUR}, `
    + `day_used=${dayUsed + sent}/${BROADCAST_PER_DAY}, this_tick=${sent}, `
    + `dedup=${dedupSkip}, optout=${optoutSkip}, no_contact=${noContactSkip}, `
    + `pending=${pendingSkip}, op=${opSkip}`);
}

// Выгрузка активной базы клиентов из Altegio с кешем в KV на BASE_CACHE_TTL.
// Берём ВСЕХ кто есть в базе с телефоном (фильтр visit_count > 0 убран
// 10.06.2026 — на WA2 база активных была охвачена ~70%, нужно расширение
// для продолжения рассылки). Источник: clients/search с пагинацией.
async function fetchBroadcastBase(env) {
  const cacheKey = `broadcast:base:${almatyNow().ymd}`;
  const cached = await env.BOT_KV.get(cacheKey, { type: 'json' });
  if (cached && Array.isArray(cached) && cached.length) return cached;

  const out = [];
  for (let page = 1; page <= 50; page++) {
    const url = `${ALTEGIO_API}/company/${env.ALTEGIO_COMPANY_ID}/clients/search`;
    let res;
    try {
      res = await fetch(url, {
        method: 'POST',
        headers: altegioHeaders(env),
        body: JSON.stringify({
          page,
          page_size: 200,
          fields: ['id', 'phone', 'name'],
          filters: [],
        }),
      });
    } catch (e) {
      console.error(`broadcast base page ${page}:`, e && e.message);
      break;
    }
    if (!res.ok) {
      console.error(`broadcast base page ${page}: HTTP ${res.status}`);
      break;
    }
    const data = await res.json().catch(() => null);
    const list = (data && data.data) || [];
    if (!list.length) break;
    for (const c of list) {
      if (!c || !c.phone) continue;
      out.push({ phone: c.phone, name: c.name });
    }
    if (list.length < 200) break;
  }

  console.log(`broadcast: base fetched ${out.length} clients`);
  await env.BOT_KV.put(cacheKey, JSON.stringify(out),
    { expirationTtl: BROADCAST_BASE_CACHE_TTL });
  return out;
}

// Строгий резолв контакта по телефону: ТОЛЬКО на канале BROADCAST_CHANNEL_ID.
// Если клиент на нём не писал — возвращает null (не открываем новый чат).
async function mhResolveContactStrict(env, token, phone,
  targetChannelId, targetChannelUuid, needCreate = false) {
  let res;
  const body = {
    phone,
    need_create: !!needCreate,
  };
  if (needCreate) body.channel_uuid = targetChannelUuid;
  try {
    res = await fetch(
      `${MH_API}/app/projects/${env.MH_PROJECT_ID}/contacts/contact_by_phone`,
      {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`,
          'content-type': 'application/json' },
        body: JSON.stringify(body),
      });
  } catch (e) {
    console.error('broadcast contact_by_phone:', e && e.message);
    return null;
  }
  if (!res.ok) {
    if (res.status === 404 || res.status === 400) return null;
    console.error(`broadcast contact_by_phone ${res.status}:`,
      (await res.text()).slice(0, 200));
    return null;
  }
  const data = await res.json().catch(() => null);
  if (!data) return null;
  const c = data.data || data;
  if (!c) return null;

  // ── PILOT DEBUG: показать структуру ответа MH ────────────────────────────
  // Логируем какие списки и какие channel_id видим — чтобы понять почему
  // валидация не находит targetChannelId.
  const listSummary = [];
  for (const [name, list] of [['users', c.users], ['channels', c.channels],
    ['channel_links', c.channel_links], ['contact_channels', c.contact_channels]]) {
    if (!Array.isArray(list)) { listSummary.push(`${name}=N/A`); continue; }
    const cids = list.map((x) => x && (x.channel_id ?? '?')).join(',');
    listSummary.push(`${name}=[${cids}]`);
  }
  console.log(`PILOT resolve phone=${maskPhone(phone)} needCreate=${needCreate} `
    + `target=${targetChannelId} lists: ${listSummary.join(' ')}`);

  for (const list of [c.users, c.channels, c.channel_links, c.contact_channels]) {
    if (!Array.isArray(list)) continue;
    for (const x of list) {
      if (!x) continue;
      const uid = x.user_id || x.id;
      const cid = x.channel_id;
      if (!uid) continue;
      if (Number(cid) !== Number(targetChannelId)) continue;
      if (x.blocked) continue;
      console.log(`PILOT resolve OK phone=${maskPhone(phone)} userId=${uid}`);
      return {
        channelUuid: targetChannelUuid,
        channelId: Number(targetChannelId),
        userId: uid,
        lastMessageAt: x.last_message || null,
      };
    }
  }
  console.log(`PILOT resolve NULL phone=${maskPhone(phone)} needCreate=${needCreate} `
    + `— ни один список не содержит channel_id=${targetChannelId}. `
    + `Top-level keys: ${Object.keys(c).join(',')}`);
  return null;
}

// Прямая отправка в message.help send_message без cold-фильтра / hour-cap.
// Эти проверки делает runBroadcastJob выше — нам нужен «тонкий» send.
async function mhSendDirect(env, token, channelUuid, userId, text) {
  const url = `${MH_API}/app/projects/${env.MH_PROJECT_ID}`
    + `/channels/${channelUuid}/send_message/${userId}`;
  console.log(`PILOT send start userId=${userId} channelUuid=${channelUuid.slice(0,8)}…`);
  for (let attempt = 0; attempt < 3; attempt++) {
    let res;
    try {
      const form = new FormData();
      form.append('text', text);
      form.append('destination', 'from_operator');
      res = await fetch(url, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: form,
      });
    } catch (e) {
      console.error(`PILOT send fetch attempt=${attempt} userId=${userId}:`, e && e.message);
      await sleep(500 * (attempt + 1));
      continue;
    }
    if (res.ok) {
      const data = await res.json().catch(() => null);
      const sentId = data && data.data && data.data.id;
      if (sentId) {
        await env.BOT_KV.put(`sent:${sentId}`, '1',
          { expirationTtl: SENT_TTL });
      }
      console.log(`PILOT send OK userId=${userId} attempt=${attempt} sentId=${sentId || 'none'}`);
      return true;
    }
    const bodyText = (await res.text()).slice(0, 300);
    console.error(`PILOT send FAIL userId=${userId} attempt=${attempt} status=${res.status} body=${bodyText}`);
    if (res.status !== 429 && res.status < 500) return false;
    const retryAfter = parseInt(res.headers.get('retry-after') || '0', 10);
    await sleep(retryAfter ? retryAfter * 1000 : 600 * (attempt + 1));
  }
  return false;
}

// ── Утилиты ────────────────────────────────────────────────────────────────
function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}
